    "q.l23#9.e" to "先放「不用但必須帶」的，再放重的，最後放隨時要拿的。頭燈與急救包要能在不解包的情況下取到。",
    "q.l23#10.p" to "上包之後的檢查順序，正確的是？",
    "q.l23#10.o0" to "繫腰帶並收緊",
    "q.l23#10.o1" to "調肩帶貼合",
    "q.l23#10.o2" to "扣胸帶",
    "q.l23#10.o3" to "起身走幾步，確認不晃",
    "q.l23#10.e" to "順序反了會導致重量壓在肩上：先繫腰帶定位，再調肩帶，胸帶只防肩帶外滑，最後必須走動驗證。",
    "q.l23#11.p" to "衝頂包常用容量是 35–50 升，旅行袋常用 ______ 升。",
    "q.l23#11.a0" to "90–120",
    "q.l23#11.a1" to "90-120",
    "q.l23#11.a2" to "90~120",
    "q.l23#11.e" to "旅行袋負責把大件從公路運到營地，容量要能裝下睡袋、羽絨、靴子和技術器材，一般 90–120 升。",
    "q.l23#12.p" to "腰帶承擔揹包重量的比例大約是 ______ %（填一個數）。",
    "q.l23#12.a0" to "60",
    "q.l23#12.a1" to "65",
    "q.l23#12.a2" to "70",
    "q.l23#12.a3" to "60–70",
    "q.l23#12.e" to "約 60–70%。這也是判斷揹著是否合適的標準：如果肩部明顯吃力，問題多半在腰帶。",
    "q.l23#13.p" to "把揹包部位與它應該裝的東西對應起來。",
    "q.l23#13.l0" to "貼背中上部",
    "q.l23#13.l1" to "包底",
    "q.l23#13.l2" to "頂袋",
    "q.l23#13.l3" to "側袋",
    "q.l23#13.r0" to "水、爐具、技術器材等重物",
    "q.l23#13.r1" to "睡袋與羽絨（裝防水袋）",
    "q.l23#13.r2" to "當天要用的保暖層、行動糧",
    "q.l23#13.r3" to "頭燈、急救小包、防曬",
    "q.l23#13.e" to "位置決定取用效率與重心。頭燈放側袋是為了天黑時不用翻包；睡袋放包底是因為一天只在營地用一次。",
    "q.l23#14.p" to "同伴的包明顯比你重很多，最合理的處理是？",
    "q.l23#14.o0" to "當場把各自的東西攤開重新分配，把公共裝備均攤",
    "q.l23#14.o1" to "讓他自己扛，這是他的選擇",
    "q.l23#14.o2" to "幫他背一半，自己超重也沒關係",
    "q.l23#14.o3" to "把公共裝備扔掉",
    "q.l23#14.e" to "隊伍的速度由最慢的人決定，而超重會讓最慢的人更慢。公共裝備（爐具、繩索、急救包）必須均攤，這是出發前就該做好的事。",
    "q.l24#0.p" to "選睡袋時應該看哪個溫標？",
    "q.l24#0.o0" to "舒適溫標",
    "q.l24#0.o1" to "極限溫標",
    "q.l24#0.o2" to "廠家宣傳語裡的最低溫度",
    "q.l24#0.o3" to "重量",
    "q.l24#0.e" to "舒適溫標是「穿著基礎層能睡整夜不冷」的溫度；極限溫標只是「不至於失溫」的生存邊界，兩者常差 10 ℃ 以上。",
    "q.l24#1.p" to "在高海拔，睡袋的舒適溫標應該怎麼定？",
    "q.l24#1.o0" to "比預期最低氣溫再低 5 ℃ 以上",
    "q.l24#1.o1" to "等於預期最低氣溫",
    "q.l24#1.o2" to "比預期最低氣溫高 5 ℃",
    "q.l24#1.o3" to "無所謂",
    "q.l24#1.e" to "留餘量的理由是：夜裡代謝下降、進食減少、帳篷內可能結霜，實際體感比預報更冷。",
    "q.l24#2.p" to "羽絨睡袋最需要防的是什麼？",
    "q.l24#2.o0" to "潮溼——受潮後幾乎不保暖",
    "q.l24#2.o1" to "壓折",
    "q.l24#2.o2" to "陽光",
    "q.l24#2.o3" to "摩擦",
    "q.l24#2.e" to "羽絨受潮後蓬鬆度坍塌，隔熱能力大幅下降，而且在野外很難真正烘乾。防水袋是最便宜有效的保險。",
    "q.l24#3.p" to "高海拔營地常見的防潮墊用法是？",
    "q.l24#3.o0" to "閉孔泡沫墊與充氣墊疊用，隔熱值相加",
    "q.l24#3.o1" to "只用充氣墊",
    "q.l24#3.o2" to "只用鋁箔墊",
    "q.l24#3.o3" to "直接睡在帳篷地面上",
    "q.l24#3.e" to "泡沫墊負責隔斷地面傳導，充氣墊提供平整與舒適。疊用還能互為備份：充氣墊漏了，泡沫墊仍在。",
    "q.l24#4.p" to "充氣墊在營地漏氣了，最先該做什麼？",
    "q.l24#4.o0" to "找到漏點貼補片，同時用泡沫墊頂上",
    "q.l24#4.o1" to "繼續睡，明天再說",
    "q.l24#4.o2" to "把氣全部放掉",
    "q.l24#4.o3" to "換一個帳篷",
    "q.l24#4.e" to "漏氣會持續惡化，而且夜裡溫度更低。補片 + 泡沫墊備份是標準處置，不要賭它能撐到天亮。",
    "q.l24#5.p" to "睡袋長期存放的正確方式是？",
    "q.l24#5.o0" to "攤開或鬆散地掛在乾燥處",
    "q.l24#5.o1" to "始終壓縮在收納袋裡",
    "q.l24#5.o2" to "真空壓縮",
    "q.l24#5.o3" to "密封在塑膠袋裡",
    "q.l24#5.e" to "長期壓縮會讓羽絨的蓬鬆結構疲勞，幾個季節下來保暖力明顯下降。存放要松、要幹。",
    "q.l24#6.p" to "哪些做法能實際改善高海拔的睡眠？",
    "q.l24#6.o0" to "睡前少喝水但要補夠全天水量",
    "q.l24#6.o1" to "戴耳塞隔絕帳篷裡的動靜",
    "q.l24#6.o2" to "把溼衣物帶進睡袋裡烘",
    "q.l24#6.o3" to "睡前吃太飽",
    "q.l24#6.e" to "把溼衣物塞進睡袋會帶走大量熱量、弄溼羽絨，是典型的錯誤做法；睡前吃太飽會加重夜間不適。",
    "q.l24#7.p" to "睡眠系統的組成通常包括哪些？",
    "q.l24#7.o0" to "睡袋（含內膽）",
    "q.l24#7.o1" to "防潮墊（泡沫 + 充氣）",
    "q.l24#7.o2" to "枕頭",
    "q.l24#7.o3" to "帳篷地布",
    "q.l24#7.e" to "這四件共同決定「地面傳導 + 空氣對流 + 舒適度」。缺一件，夜裡就會在某個方向上持續失溫。",
    "q.l24#8.p" to "搭好睡眠區的順序，正確的是？",
    "q.l24#8.o0" to "清平地面、清除碎石與尖物",
    "q.l24#8.o1" to "鋪地布與泡沫墊",
    "q.l24#8.o2" to "充氣墊充氣並檢查",
    "q.l24#8.o3" to "鋪開睡袋，留出翻身空間",
    "q.l24#8.e" to "順序錯了會返工：地面沒清乾淨，充氣墊一夜就可能被扎破。",
    "q.l24#9.p" to "睡袋的舒適溫標建議比預期最低氣溫再低 ______ ℃ 以上。",
    "q.l24#9.a0" to "5",
    "q.l24#9.e" to "留 5 ℃ 餘量是通用做法。高原夜間體感更低，這個餘量不算多。",
    "q.l24#10.p" to "羽絨睡袋受潮後幾乎不保暖，所以必須單獨放進 ______ 袋。",
    "q.l24#10.a0" to "防水",
    "q.l24#10.a1" to "防水袋",
    "q.l24#10.a2" to "dry bag",
    "q.l24#10.e" to "獨立防水袋的意義在於隔離：外層溼了，核心仍然乾燥。",
    "q.l24#11.p" to "把睡眠裝備與它的主要作用對應起來。",
    "q.l24#11.l0" to "閉孔泡沫墊",
    "q.l24#11.l1" to "充氣墊",
    "q.l24#11.l2" to "睡袋內膽",
    "q.l24#11.l3" to "耳塞",
    "q.l24#11.r0" to "隔斷地面傳導，且不怕扎破",
    "q.l24#11.r1" to "提供平整與舒適，可疊加以增加隔熱",
    "q.l24#11.r2" to "減少睡袋汙染與潮溼",
    "q.l24#11.r3" to "降低噪聲干擾，改善入睡",
    "q.l24#11.e" to "四種裝備解決四個不同問題：傳導、平整、溼度、噪聲。缺哪個，問題就從哪個方向冒出來。",
    "q.l24#12.p" to "帳篷裡結霜很嚴重，第二天早上應該怎麼處理？",
    "q.l24#12.o0" to "先把睡袋收進防水袋，再抖掉帳篷內壁的霜，避免弄溼睡袋",
    "q.l24#12.o1" to "先收帳篷，睡袋放外面",
    "q.l24#12.o2" to "用體溫把霜化掉",
    "q.l24#12.o3" to "不用管，曬一曬就好",
    "q.l24#12.e" to "結霜的帳篷一碰就掉冰屑。先把睡袋封好，是防止「一趟行程毀在早晨十分鐘」的關鍵動作。",
    "q.l24#13.p" to "為什麼高海拔的睡眠質量普遍變差？",
    "q.l24#13.o0" to "低氧導致週期性呼吸，人會被反覆從淺睡中喚醒",
    "q.l24#13.o1" to "帳篷太硬",
    "q.l24#13.o2" to "因為白天走得太少",
    "q.l24#13.o3" to "因為海拔高，時間變慢",
    "q.l24#13.e" to "這是生理性的。能做的只有改善條件（保暖、隔音、補水），而不是要求自己「必須睡滿八小時」。",
    "q.l24#14.p" to "隊裡只有一頂備用帳篷，應該優先給誰？",
    "q.l24#14.o0" to "給最可能失溫或已經出現高反症狀的人",
    "q.l24#14.o1" to "給領隊",
    "q.l24#14.o2" to "給體力最好的人",
    "q.l24#14.o3" to "抽籤決定",
    "q.l24#14.e" to "備用資源按風險分配，不按資歷或體力分配。這條在出發前就該講清楚，避免夜裡爭執。",
    "q.m02#10.p" to "攀登前的訓練，比較合理的結構是？",
    "q.m02#10.o0" to "以有氧耐力為主，配合力量與負重爬升，逐周增加負荷",
    "q.m02#10.o1" to "每天高強度間歇",
    "q.m02#10.o2" to "只練力量",
    "q.m02#10.o3" to "只練拉伸",
    "q.m02#10.e" to "登山是「長時間低強度」的運動，有氧基礎最重要。負荷要漸進，臨出發前兩週應該減量。",
    "q.m02#11.p" to "出發前兩週的訓練重點應該轉為？",
    "q.m02#11.o0" to "減量、保持狀態、保證睡眠",
    "q.m02#11.o1" to "加大強度",
    "q.m02#11.o2" to "嘗試新專案",
    "q.m02#11.o3" to "完全停止",
    "q.m02#11.e" to "帶著疲勞上山，等於把最差的狀態用在最需要的時刻。減量期是訓練的一部分，不是偷懶。",
    "q.m02#12.p" to "關於咖啡因在高海拔的使用，正確的是？",
    "q.m02#12.o0" to "適量可用，但不能替代睡眠與補水",
    "q.m02#12.o1" to "越多越提神",
    "q.m02#12.o2" to "完全禁用",
    "q.m02#12.o3" to "可以用來治高反",
    "q.m02#12.e" to "咖啡因能暫時改善主觀疲勞感，但不改變缺氧本身。用它硬撐，會把問題推到更晚、更危險的時候。",
    "q.l4#8.p" to "「休息步」的作用是？",
    "q.l4#8.o0" to "每一步都把重心壓在直立的腿上，讓另一條腿真正休息",
    "q.l4#8.o1" to "停下來休息",
    "q.l4#8.o2" to "放慢速度",
    "q.l4#8.o3" to "換手拿鎬",
    "q.l4#8.e" to "休息步是讓腿在行走中輪流承重，而不是全程肌肉緊張。長雪坡上，它是能否堅持到最後的關鍵。",
    "q.l4#9.p" to "橫切硬雪坡時，正確的做法是？",
    "q.l4#9.o0" to "上游腳在下、下游腳在上，鎬握在上坡側",
    "q.l4#9.o1" to "兩腳平行",
    "q.l4#9.o2" to "鎬握在下坡側",
    "q.l4#9.o3" to "身體朝向坡下",
    "q.l4#9.e" to "鎬在上坡側，滑倒時能立刻壓入雪面制動。腳位反了，滑墜時第一步就會絆住自己。",
    "q.l4#10.p" to "連續陡坡上升，更省力的走法是？",
    "q.l4#10.o0" to "走「之」字，減小坡度",
    "q.l4#10.o1" to "直線上升",
    "q.l4#10.o2" to "跑上去",
    "q.l4#10.o3" to "側身跳",
    "q.l4#10.e" to "之字路線把坡度換成距離，能顯著降低每次抬腿的高度。代價是路程變長，需要提前算時間。",
    "q.l4#11.p" to "下坡時膝蓋刺痛，最可能的原因是？",
    "q.l4#11.o0" to "步幅過大、落地時膝蓋伸直鎖死",
    "q.l4#11.o1" to "鞋子太軟",
    "q.l4#11.o2" to "襪子太厚",
    "q.l4#11.o3" to "揹包太輕",
    "q.l4#11.e" to "下坡的衝擊是上坡的數倍。縮小步幅、保持膝蓋微屈，是最有效的保護。",
    "q.l4#12.p" to "雪坡上「踢步」時，腳應該怎麼落地？",
    "q.l4#12.o0" to "用鞋底前部或整腳壓出水平臺階，腳尖略微上翹",
    "q.l4#12.o1" to "腳尖直插",
    "q.l4#12.o2" to "腳跟著地",
    "q.l4#12.o3" to "側腳掌",
    "q.l4#12.e" to "臺階要平才能站住。腳尖上翹能讓鞋底把雪壓成水平面，而不是挖一個斜洞。",
    "q.m03#10.p" to "營地與水源之間的推薦距離是？",
    "q.m03#10.o0" to "60 公尺以上",
    "q.m03#10.o1" to "5 公尺",
    "q.m03#10.o2" to "10 公尺",
    "q.m03#10.o3" to "越近越好",
    "q.m03#10.e" to "60 公尺（約 70 步）是通行的衛生距離，用於排洩、洗漱與洗碗。",
    "q.m03#11.p" to "野外用火的正確態度是？",
    "q.m03#11.o0" to "優先用爐具；確需用火時選已有火圈並徹底熄滅",
    "q.m03#11.o1" to "生火更有氣氛",
    "q.m03#11.o2" to "只要不引發山火就行",
    "q.m03#11.o3" to "用火可以驅趕動物",
    "q.m03#11.e" to "火跡會留存多年，也會誘導後來者在同一處生火。乾燥季節的火星可能帶來真正的災難。",
    "q.m03#12.p" to "遇到野生動物時，合理的做法是？",
    "q.m03#12.o0" to "保持距離、不投餵、慢慢退開，不追拍",
    "q.m03#12.o1" to "靠近拍照",
    "q.m03#12.o2" to "投餵以安撫",
    "q.m03#12.o3" to "大聲驅趕",
    "q.m03#12.e" to "投餵會改變動物行為、增加衝突風險。保持距離既保護自己，也保護它們。",
    "q.m04#10.p" to "看天氣預報時，比「降水機率」更該關注的是？",
    "q.m04#10.o0" to "風速、氣溫與降水形式（雨/雪）隨高度的分佈",
    "q.m04#10.o1" to "只有降水機率",
    "q.m04#10.o2" to "只有最高溫",
    "q.m04#10.o3" to "只有溼度",
    "q.m04#10.e" to "同樣的降水量，下雨還是下雪對行程影響完全不同。風速決定體感與能否行動，氣溫決定裝備。",
    "q.m04#11.p" to "山區午後常見的天氣模式是？",
    "q.m04#11.o0" to "雲量增加、對流發展，雷暴與陣雨機率上升",
    "q.m04#11.o1" to "持續晴朗",
    "q.m04#11.o2" to "風力減弱",
    "q.m04#11.o3" to "氣溫下降最快",
    "q.m04#11.e" to "這是「上午出發、午後離開暴露地形」這條規律的來源。行程設計要順應這個節律。",
    "q.m04#12.p" to "用氣溫遞減率估算雪線時，每 1,000 公尺大約降多少度？",
    "q.m04#12.o0" to "6.5 ℃",
    "q.m04#12.o1" to "2 ℃",
    "q.m04#12.o2" to "10 ℃",
    "q.m04#12.o3" to "15 ℃",
    "q.m04#12.e" to "6.5 ℃/1,000 m 是平均遞減率。用它可以把「零度層高度」粗算出來，判斷會下雨還是下雪。",
    "q.m05#10.p" to "入門雪山的「季節窗口」為什麼重要？",
    "q.m05#10.o0" to "不同季節的雪況、風力與許可政策差別很大，錯過窗口難度會翻倍",
    "q.m05#10.o1" to "因為票價",
    "q.m05#10.o2" to "因為人多",
    "q.m05#10.o3" to "因為日照",
    "q.m05#10.e" to "同一座山在季風前後是兩個難度。選山先選季節，再選路線。",
    "q.m05#11.p" to "選擇入門山峰時，「是否需要技術操作」指的是？",
    "q.m05#11.o0" to "是否需要結組、保護、冰裂縫行進等技術手段",
    "q.m05#11.o1" to "是否需要門票",
    "q.m05#11.o2" to "是否需要嚮導",
    "q.m05#11.o3" to "是否需要帳篷",
    "q.m05#11.e" to "徒步型與技術型的核心差別在這裡。第一次上雪山，優先選不需要技術操作的路線。",
    "q.m05#12.p" to "關於「登頂率」，正確的理解是？",
    "q.m05#12.o0" to "它反映天氣窗口與路線難度，但不同年份的統計口徑差別很大",
    "q.m05#12.o1" to "越高越好",
    "q.m05#12.o2" to "越低越安全",
    "q.m05#12.o3" to "沒有參考價值",
    "q.m05#12.e" to "登頂率是「資訊」不是「保證」。看它時要注意年份、季節與是否包含商業隊伍的協助。",
    "q.m25#12.p" to "下撤之後，最該做的覆盤是？",
    "q.m25#12.o0" to "回看當時的判斷依據：哪些資訊被忽略、哪個節點可以更早決定",
    "q.m25#12.o1" to "只記結論",
    "q.m25#12.o2" to "歸因於運氣",
    "q.m25#12.o3" to "不再提起",
    "q.m25#12.e" to "覆盤的目的不是追責，而是把「下次能更早發現」變成具體經驗。寫下時間線比寫感受有用。",
    "q.m06#10.p" to "技術攀登的三大系統裡，「保護」指的是？",
    "q.m06#10.o0" to "用錨點與繩索在墜落時把人接住",
    "q.m06#10.o1" to "走路",
    "q.m06#10.o2" to "攀爬動作",
    "q.m06#10.o3" to "裝備採購",
    "q.m06#10.e" to "移動、保護、確保（belay）構成閉環：會走、會保護自己、會保護別人，三者缺一都算不上會技術攀登。",
    "q.m06#11.p" to "為什麼技術課的順序通常是「先學制動，再學攀爬」？",
    "q.m06#11.o0" to "因為滑墜是最高頻的危險，制動是保底能力",
    "q.m06#11.o1" to "因為攀爬更難",
    "q.m06#11.o2" to "因為裝備順序",
    "q.m06#11.o3" to "因為教材這樣寫",
    "q.m06#11.e" to "會爬但不會停，等於把風險放大。制動、結組、保護這些「不出事時用不上」的技能要先形成肌肉記憶。",
    "q.m06#12.p" to "在安全地形上反覆模擬練習的價值是？",
    "q.m06#12.o0" to "把動作變成不需要思考的條件反射，真實場景下才有餘量判斷",
    "q.m06#12.o1" to "為了消耗時間",
    "q.m06#12.o2" to "為了拍照",
    "q.m06#12.o3" to "為了熟悉裝備價格",
    "q.m06#12.e" to "真實環境中，注意力會被天氣、疲勞與恐懼佔滿。能自動完成的動作，才可能在關鍵時刻做出來。",
    "q.l25#0.p" to "辦登山許可最容易被低估的是什麼？",
    "q.l25#0.o0" to "提前量與附加要求（嚮導、聯絡人、體檢證明）",
    "q.l25#0.o1" to "費用",
    "q.l25#0.o2" to "照片尺寸",
    "q.l25#0.o3" to "辦理窗口的營業時間",
    "q.l25#0.e" to "很多路線要求提前數週申請，並繫結當地嚮導或聯絡人。等到了山腳才辦，往往只能改路線。",
    "q.l25#1.p" to "挑選保險時，最需要確認的兩項是？",
    "q.l25#1.o0" to "技術攀登是否承保、高海拔直升機撤離是否承保",
    "q.l25#1.o1" to "是否含航班延誤",
    "q.l25#1.o2" to "是否能退保",
    "q.l25#1.o3" to "保費高低",
    "q.l25#1.e" to "普通旅行險常把「技術性攀登」與「高海拔」列為免責。真正出事時才發現不賠，是這類事故里最常見的二次傷害。",
    "q.l25#2.p" to "後勤計劃裡必須準備備用方案的是？",
    "q.l25#2.o0" to "交通、馱運、營地補給，逐段都要有備選",
    "q.l25#2.o1" to "只有交通",
    "q.l25#2.o2" to "只有住宿",
    "q.l25#2.o3" to "不需要備用方案",
    "q.l25#2.e" to "山區延誤是常態：路斷、航班取消、挑夫臨時變動。逐段有備選，才不會一處卡住全線崩。",
    "q.l25#3.p" to "給留守聯絡人留的行程書，最少要寫清什麼？",
    "q.l25#3.o0" to "路線、各檢查點時間、失聯多久啟動預案與報警方式",
    "q.l25#3.o1" to "只有山名",
    "q.l25#3.o2" to "只有隊友姓名",
    "q.l25#3.o3" to "只有預算",
    "q.l25#3.e" to "行程書的作用是讓別人能替你判斷「該不該擔心」。時間點與預案是核心，路線是前提。",
    "q.l25#4.p" to "為什麼預算要留 20% 餘量？",
    "q.l25#4.o0" to "延誤、額外住宿、臨時增加挑夫都會發生",
    "q.l25#4.o1" to "為了買紀念品",
    "q.l25#4.o2" to "為了給小費",
    "q.l25#4.o3" to "因為匯率會變",
    "q.l25#4.e" to "這些支出不是意外而是常態。留餘量的目的不是省錢，而是避免在山上因為錢的問題做出糟糕決策。",
    "q.l25#5.p" to "登頂證明通常需要哪些材料？",
    "q.l25#5.o0" to "登頂照片或影片、登頂宣告表、許可與身份檔案",
    "q.l25#5.o1" to "只有照片",
    "q.l25#5.o2" to "只有隊友簽字",
    "q.l25#5.o3" to "不需要任何材料",
    "q.l25#5.e" to "不同山峰要求不同，但照片、宣告表、許可這幾類基本都會用到。出發前確認，比回程補辦容易得多。",
    "q.l25#6.p" to "行前需要向隊員統一交代的事項包括？",
    "q.l25#6.o0" to "集合與撤離的時間地點",
    "q.l25#6.o1" to "對講機頻道與呼叫規則",
    "q.l25#6.o2" to "醫療資訊與用藥禁忌",
    "q.l25#6.o3" to "每人每天的伙食分配",
    "q.l25#6.e" to "前兩項關係到走散與救援，第三項是急救時的關鍵資訊；伙食分配屬於後勤細節，由領隊安排即可，不必全員討論。",
    "q.l25#7.p" to "下面哪些屬於「沒有它就可能被拒絕進入」的檔案？",
    "q.l25#7.o0" to "保護區或登山許可",
    "q.l25#7.o1" to "身份證明",
    "q.l25#7.o2" to "保險單（部分路線要求）",
    "q.l25#7.o3" to "登頂證書",
    "q.l25#7.e" to "登頂證書是回來之後才有的東西，不能當準入檔案。前兩項幾乎必查，第三項按路線要求。",
    "q.l25#8.p" to "從決定去一座山到出發，合理的推進順序是？",
    "q.l25#8.o0" to "確定路線與時間窗口",
    "q.l25#8.o1" to "辦許可、訂交通與馱運",
    "q.l25#8.o2" to "買針對性保險、核對免責條款",
    "q.l25#8.o3" to "整理檔案包並留行程書給聯絡人",
    "q.l25#8.e" to "先定路線才能辦許可，許可與交通定了才知道保險要覆蓋哪些天與哪些活動，最後才是檔案歸檔。",
    "q.l25#9.p" to "行李被延誤或無法同機到達時，最該隨身攜帶的是 ______（哪類裝備）。",
    "q.l25#9.a0" to "攀登靴",
    "q.l25#9.a1" to "高山靴",
    "q.l25#9.a2" to "靴子",
    "q.l25#9.a3" to "個人技術裝備",
    "q.l25#9.e" to "靴子與個人技術裝備一旦丟失幾乎無法臨時替代。多數隊伍要求這兩類必須隨身，不進託運。",
    "q.l25#10.p" to "預算通常建議留 ______ % 的餘量。",
    "q.l25#10.a0" to "20",
    "q.l25#10.e" to "20% 是經驗值。山區行程的額外支出往往集中在「延誤」與「人力」兩項上。",
    "q.l25#11.p" to "把檔案與它的用途對應起來。",
    "q.l25#11.l0" to "登山許可",
    "q.l25#11.l1" to "保險單與救援電話",
    "q.l25#11.l2" to "登頂宣告表",
    "q.l25#11.l3" to "行程書",
    "q.l25#11.r0" to "准入憑證，檢查站會查",
    "q.l25#11.r1" to "出險時聯絡救援與理賠的依據",
    "q.l25#11.r2" to "申請登頂證明時提交",
    "q.l25#11.r3" to "留給聯絡人，用於判斷何時報警",
    "q.l25#11.e" to "四份檔案服務四個場景：進門、出事、證明、失聯。少一份，對應的場景就會卡住。",
    "q.l25#12.p" to "隊伍出發前沒有確認「誰有權喊停」，最可能的後果是？",
    "q.l25#12.o0" to "該停的時候沒人敢開口，風險被集體沉默放大",
    "q.l25#12.o1" to "走得更快",
    "q.l25#12.o2" to "裝備更輕",
    "q.l25#12.o3" to "沒有影響",
    "q.l25#12.e" to "把「喊停」變成事先授予的許可權，而不是個人勇氣的考驗。這條在行前說清，比山上臨時爭論有用得多。",
    "q.l25#13.p" to "許可要求必須僱當地嚮導，但隊伍裡有人反對，正確的處理是？",
    "q.l25#13.o0" to "遵守規定，把嚮導計入預算與計劃",
    "q.l25#13.o1" to "繞過檢查站",
    "q.l25#13.o2" to "讓嚮導只掛名",
    "q.l25#13.o3" to "換一條不要求的路線並重新評估",
    "q.l25#13.e" to "規避許可不僅違法，也會讓救援與保險失效。要麼合規，要麼換路線——不能靠僥倖。",
    "q.l25#14.p" to "行前體檢與用藥資訊為什麼要提前收集？",
    "q.l25#14.o0" to "急救時需要知道禁忌與既往病史，高海拔會放大基礎病風險",
    "q.l25#14.o1" to "為了買保險打折",
    "q.l25#14.o2" to "為了分組",
    "q.l25#14.o3" to "沒有實際用途",
    "q.l25#14.e" to "在 5,000 公尺以上，一次普通感染或藥物過敏都可能演變成急症。資訊要在出發前收集，而不是等出事時挨個問。",
    "q.l42#0.p" to "「四三三」原則指的是？",
    "q.l42#0.o0" to "體力、時間、裝備各留三分之一餘量",
    "q.l42#0.o1" to "三個人三小時三條路線",
    "q.l42#0.o2" to "三種裝備三種天氣",
    "q.l42#0.o3" to "三次檢查三次確認",
    "q.l42#0.e" to "留餘量不是保守，而是把「意外」提前計入預算。用滿再遇變化，就只能靠運氣。",
    "q.l42#1.p" to "「三新不出行」裡的「三新」指？",
    "q.l42#1.o0" to "新路線、新隊友、新裝備",
    "q.l42#1.o1" to "新季節、新天氣、新海拔",
    "q.l42#1.o2" to "新計劃、新預算、新目標",
    "q.l42#1.o3" to "新嚮導、新車、新鞋",
    "q.l42#1.e" to "每一樣「新」都代表未知。同時疊三樣，等於把不確定性一次性拉滿。",
    "q.l42#2.p" to "為什麼要「先降後果，再降可能性」？",
    "q.l42#2.o0" to "後果一旦發生就無法挽回，而可能性只能降低不能消除",
    "q.l42#2.o1" to "因為降後果更便宜",
    "q.l42#2.o2" to "因為可能性無法計算",
    "q.l42#2.o3" to "兩者順序無關",
    "q.l42#2.e" to "例如結組、戴頭盔、留撤離通道，都是「即使發生也不至於致命」。這比「小心一點」有效得多。",
    "q.l42#3.p" to "STOP 原則的正確順序是？",
    "q.l42#3.o0" to "停、想、看、計劃",
    "q.l42#3.o1" to "看、停、想、計劃",
    "q.l42#3.o2" to "想、看、停、計劃",
    "q.l42#3.o3" to "停、看、想、計劃",
    "q.l42#3.e" to "先停下來，才談得上想與看。人在壓力下的第一反應往往是繼續走，這是最危險的預設動作。",
    "q.l42#4.p" to "計劃裡「什麼情況下放棄」這一條的作用是？",
    "q.l42#4.o0" to "把決策提前到情緒與目標壓力之外",
    "q.l42#4.o1" to "為了寫得完整",
    "q.l42#4.o2" to "為了應付檢查",
    "q.l42#4.o3" to "沒有實際作用",
    "q.l42#4.e" to "在山上、疲勞與目標壓力下臨時決定放棄，幾乎不可能。寫下來的條件才有約束力。",
    "q.l42#5.p" to "「安全建營三要訣」不包括？",
    "q.l42#5.o0" to "營地要儘量靠近水源邊",
    "q.l42#5.o1" to "避開地形陷阱",
    "q.l42#5.o2" to "留出撤離通道",
    "q.l42#5.o3" to "關鍵物資集中",
    "q.l42#5.e" to "貼水紮營是山洪事故的典型場景。三要訣的核心是「先保證能退」，風景與方便都排在後面。",
    "q.l42#6.p" to "隊伍剛換了新裝備、又走了新路線，按「三新」原則應該？",
    "q.l42#6.o0" to "至少換掉其中一項，或把難度降到能驗證裝備的程度",
    "q.l42#6.o1" to "沒關係，裝備新更安全",
    "q.l42#6.o2" to "加快進度",
    "q.l42#6.o3" to "分開走",
    "q.l42#6.e" to "新裝備需要驗證，新路線需要適應。兩樣同時來，出問題時無法判斷原因。",
    "q.l42#7.p" to "關於「風險 = 後果 × 可能性」，下面哪種說法對？",
    "q.l42#7.o0" to "後果極嚴重時，即使可能性很低也要處理",
    "q.l42#7.o1" to "可能性低就可以忽略",
    "q.l42#7.o2" to "只看可能性即可",
    "q.l42#7.o3" to "只看後果即可",
    "q.l42#7.e" to "乘積的意義在於：後果足夠大時，極低機率的事件仍然必須被預案覆蓋。",
    "q.l42#8.p" to "屬於「降低後果」的措施包括？",
    "q.l42#8.o0" to "結組行進、設保護點",
    "q.l42#8.o1" to "戴頭盔",
    "q.l42#8.o2" to "留出撤離通道",
    "q.l42#8.o3" to "提高體能",
    "q.l42#8.e" to "前三項都在「出事時減少傷害」。提高體能降低的是發生機率，不是後果。",
    "q.l42#9.p" to "屬於「降低可能性」的措施包括？",
    "q.l42#9.o0" to "檢視天氣與雪崩預報",
    "q.l42#9.o1" to "提前適應海拔",
    "q.l42#9.o2" to "選擇成熟路線",
    "q.l42#9.o3" to "只帶一個對講機",
    "q.l42#9.e" to "前三條都在減少「遇到危險」的機會。最後一項與風險大小無關，甚至削弱了冗餘。",
    "q.l42#10.p" to "出現哪些情況應該啟動 STOP？",
    "q.l42#10.o0" to "發現路線與地圖不符",
    "q.l42#10.o1" to "天氣在短時間內明顯變化",
    "q.l42#10.o2" to "有隊員狀態異常但說不出原因",
    "q.l42#10.o3" to "計劃進度落後半小時",
    "q.l42#10.e" to "前三條都是「資訊與預期不一致」的訊號。單純落後半小時屬於正常波動，先核對時間再決定。",
    "q.l42#11.p" to "把一次風險處置的順序排好。",
    "q.l42#11.o0" to "識別危險因素（地形、天氣、人員狀態）",
    "q.l42#11.o1" to "判斷後果與可能性",
    "q.l42#11.o2" to "優先選擇降低後果的措施",
    "q.l42#11.o3" to "執行並設定複核時間點",
    "q.l42#11.e" to "最後一步最容易被忽略：沒有複核時間點，措施會在不知不覺中失效。",
    "q.l42#12.p" to "把「三新」檢查的順序排好（出行前）。",
    "q.l42#12.o0" to "列出本次的新路線、新隊友、新裝備",
    "q.l42#12.o1" to "評估每一項帶來的未知",
    "q.l42#12.o2" to "決定減掉哪一項或降低難度",
    "q.l42#12.o3" to "把決定寫進計劃並告知隊員",
    "q.l42#12.e" to "關鍵在第三步：減項是一個主動決策，而不是「到時候小心點」。",
    "q.l42#13.p" to "「四三三」原則是把體力、時間、裝備各留 ______ 分之一的餘量。",
    "q.l42#13.a0" to "三",
    "q.l42#13.a1" to "1/3",
    "q.l42#13.a2" to "三分之一",
    "q.l42#13.e" to "留三分之一是經驗值。用得越多，遇到變化時越沒有騰挪空間。",
    "q.l42#14.p" to "風險等於後果乘以 ______。",
    "q.l42#14.a0" to "可能性",
    "q.l42#14.a1" to "機率",
    "q.l42#14.e" to "把風險拆成兩個乘數，就能判斷「該降哪一個」——通常先降後果。",
    "q.l42#15.p" to "「三新不出行」中，一次出行建議最多同時佔 ______ 樣「新」。",
    "q.l42#15.a0" to "1",
    "q.l42#15.a1" to "一",
    "q.l42#15.a2" to "2",
    "q.l42#15.a3" to "兩",
    "q.l42#15.e" to "最多一樣，最多兩樣已經是上限。三樣全佔，等於把計劃建立在三個未知上。",
    "q.l42#16.p" to "把措施與它的作用對應起來。",
    "q.l42#16.l0" to "結組行進",
    "q.l42#16.l1" to "檢視雪崩預報",
    "q.l42#16.l2" to "留撤離通道",
    "q.l42#16.l3" to "提前適應海拔",
    "q.l42#16.r0" to "降低後果（墜落不再單獨承擔）",
    "q.l42#16.r1" to "降低可能性（避開高風險日）",
    "q.l42#16.r2" to "降低後果（情況變壞時能退出）",
    "q.l42#16.r3" to "降低可能性（減少高山症）",
    "q.l42#16.e" to "四條的差別在於「改變結果」還是「改變機率」。判斷清楚，才知道該往哪投入。",
    "q.l42#17.p" to "把原則與它的適用場景對應起來。",
    "q.l42#17.l0" to "四三三",
    "q.l42#17.l1" to "三新不出行",
    "q.l42#17.l2" to "STOP",
    "q.l42#17.l3" to "後果 × 可能性",
    "q.l42#17.r0" to "行程與資源分配",
    "q.l42#17.r1" to "行前選擇與減項",
    "q.l42#17.r2" to "現場突然發現不對",
    "q.l42#17.r3" to "多個方案之間的取捨",
    "q.l42#17.e" to "四個工具分別用於「計劃、行前、現場、取捨」。它們不互相替代，而是分階段的。",
    "q.l22#10.p" to "雙繩（半繩）與單繩最本質的差別是？",
    "q.l22#10.o0" to "雙繩交替掛入保護點，能降低繩阻與衝擊，但操作更復雜",
    "q.l22#10.o1" to "雙繩更便宜",
    "q.l22#10.o2" to "雙繩更輕",
    "q.l22#10.o3" to "沒有差別",
    "q.l22#10.e" to "雙繩適合曲折、需要減少繩阻的路線；單繩更簡單直接。選哪種取決於路線形態，不是「哪個更專業」。",
    "q.l22#11.p" to "頭盔在經歷一次明顯撞擊後應該？",
    "q.l22#11.o0" to "退役更換，即使外觀完好",
    "q.l22#11.o1" to "繼續使用",
    "q.l22#11.o2" to "用膠粘一下",
    "q.l22#11.o3" to "只換內襯",
    "q.l22#11.e" to "頭盔靠泡沫吸能，撞擊後內部結構已經受損，外觀看不出來。二次撞擊時防護會大幅下降。",
    "q.l22#12.p" to "對講機在隊伍裡的使用紀律，最重要的是？",
    "q.l22#12.o0" to "固定頻道與呼叫規則，簡短報位，不佔用頻道閒聊",
    "q.l22#12.o1" to "音量開到最大",
    "q.l22#12.o2" to "隨時保持通話",
    "q.l22#12.o3" to "只由領隊攜帶",
    "q.l22#12.e" to "頻道是共享資源。長時間閒聊會讓真正需要的緊急呼叫進不來，也會快速耗盡電量。",
    "q.l22#13.p" to "衛星通訊裝置（如 inReach）與 PLB 的區別是？",
    "q.l22#13.o0" to "衛星裝置可雙向通訊，PLB 只能單向報警且專用於緊急情況",
    "q.l22#13.o1" to "PLB 能發簡訊",
    "q.l22#13.o2" to "兩者完全一樣",
    "q.l22#13.o3" to "衛星裝置不需要電",
    "q.l22#13.e" to "PLB 註冊後由救援機構響應，誤觸成本高；衛星裝置適合日常報平安與協調。兩者定位不同。",
    "q.l22#14.p" to "低溫下電池續航驟降，最實用的對策是？",
    "q.l22#14.o0" to "貼身存放備用電池，裝置不用時放內層口袋",
    "q.l22#14.o1" to "多帶幾塊放在揹包外側",
    "q.l22#14.o2" to "關掉所有功能",
    "q.l22#14.o3" to "用熱水袋加熱",
    "q.l22#14.e" to "鋰電池在 -20 ℃ 下容量可能只剩一半。保溫比多帶更有效，因為備用電池同樣會掉電。",
    "q.l22#15.p" to "出發前對離線地圖的正確做法是？",
    "q.l22#15.o0" to "下載整條路線的離線包，並在家裡試一次飛航模式下的定位",
    "q.l22#15.o1" to "只截圖路線",
    "q.l22#15.o2" to "依賴實時線上地圖",
    "q.l22#15.o3" to "列印一張小圖",
    "q.l22#15.e" to "「下載了」和「能離線用」是兩件事。在家測試一次，能提前發現沒下全或許可權問題。",
    "q.l5#10.p" to "冰爪底部積雪成團（balling）時，最有效的處理是？",
    "q.l5#10.o0" to "用鎬尖敲掉並塗防雪蠟，或換用帶防雪板的冰爪",
    "q.l5#10.o1" to "繼續走，走熱就化",
    "q.l5#10.o2" to "用腳踢樹",
    "q.l5#10.o3" to "脫掉冰爪",
    "q.l5#10.e" to "積雪會讓齒失去咬合，等於赤腳走冰坡。處理要快，別拖到下一個平臺。",
    "q.l5#11.p" to "前齒踢入時，腳踝應該保持什麼狀態？",
    "q.l5#11.o0" to "腳踝放鬆、讓齒自然垂直入冰，不要繃緊下壓",
    "q.l5#11.o1" to "腳踝繃緊",
    "q.l5#11.o2" to "腳尖上翹",
    "q.l5#11.o3" to "腳跟先落",
    "q.l5#11.e" to "繃緊會讓小腿提前疲勞，也讓齒以斜角入冰。放鬆腳踝，齒才能垂直咬住。",
    "q.l5#12.p" to "在硬冰（藍冰）上，法式平腳技術為什麼不可靠？",
    "q.l5#12.o0" to "平齒無法咬入硬冰，容易整體打滑",
    "q.l5#12.o1" to "因為太慢",
    "q.l5#12.o2" to "因為太累",
    "q.l5#12.o3" to "因為姿勢難看",
    "q.l5#12.e" to "法式依賴整排齒壓在雪面上。硬冰沒有可壓的雪層，必須改用前齒技術。",
    "q.l5#13.p" to "軟雪坡上，法式技術的優勢是？",
    "q.l5#13.o0" to "省力、速度快，適合長距離緩坡",
    "q.l5#13.o1" to "更安全",
    "q.l5#13.o2" to "更適合硬冰",
    "q.l5#13.o3" to "不需要冰鎬",
    "q.l5#13.e" to "軟雪能提供足夠的接觸面，平腳走比反覆踢前齒省力得多。技術選擇應該跟著雪質走。",
    "q.l5#14.p" to "下坡時使用法式技術，正確的姿勢是？",
    "q.l5#14.o0" to "腳尖朝下、腳跟先落，全腳掌壓入雪面",
    "q.l5#14.o1" to "腳尖朝上",
    "q.l5#14.o2" to "側身橫走",
    "q.l5#14.o3" to "只用前齒",
    "q.l5#14.e" to "下坡法式的關鍵是讓整排齒咬住雪面，同時保持重心在腳掌上方。腳跟先落能壓出臺階。",
    "q.l5#15.p" to "橫切時，靠坡一側的腳應該？",
    "q.l5#15.o0" to "用內側齒咬住坡面，腳踝向坡內傾斜",
    "q.l5#15.o1" to "平放",
    "q.l5#15.o2" to "腳尖朝下",
    "q.l5#15.o3" to "抬離地面",
    "q.l5#15.e" to "橫切時兩腳都要「咬」住坡面才能形成穩定支撐。腳踝僵硬會讓齒只能擦過表面。",
    "q.l6#10.p" to "自我制動時，鎬身應該壓在身體的哪個位置？",
    "q.l6#10.o0" to "肩與胸之間，靠體重壓住鎬頭",
    "q.l6#10.o1" to "腰部",
    "q.l6#10.o2" to "頭頂",
    "q.l6#10.o3" to "腿側",
    "q.l6#10.e" to "壓的位置越靠上，越能把體重轉成制動力。壓在腰部會讓鎬尖翹起，幾乎沒用。",
    "q.l6#11.p" to "「自制動握法」（self-arrest grip）指的是？",
    "q.l6#11.o0" to "拇指壓在鎬頭一側、手掌覆在鎬頭上，隨時能轉成制動",
    "q.l6#11.o1" to "雙手握鎬柄末端",
    "q.l6#11.o2" to "單手拎鎬",
    "q.l6#11.o3" to "手握腕帶",
    "q.l6#11.e" to "這個握法讓你在失穩瞬間不需要換手就能壓鎬。換手的那 0.5 秒往往就是滑出去的距離。",
    "q.l6#12.p" to "雪質對制動效果的影響是？",
    "q.l6#12.o0" to "軟雪容易制動，硬雪與冰面幾乎無法制動",
    "q.l6#12.o1" to "越硬越好制動",
    "q.l6#12.o2" to "與雪質無關",
    "q.l6#12.o3" to "溼雪最滑",
    "q.l6#12.e" to "制動靠鎬尖咬入。硬雪只能刮出淺痕，冰面則完全無效——所以冰坡要靠固定繩，而不是靠制動。",
    "q.l6#13.p" to "帶腕帶（leash）滑墜時的主要風險是？",
    "q.l6#13.o0" to "鎬被拽住時會扭傷手腕，或被拉扯到失控",
    "q.l6#13.o1" to "腕帶會斷",
    "q.l6#13.o2" to "鎬會丟",
    "q.l6#13.o3" to "影響美觀",
    "q.l6#13.e" to "腕帶在墜落中可能變成「鉤掛點」，把手腕拉到異常角度。技術地形多用防脫手繩替代。",
    "q.l6#14.p" to "制動成功停下來之後，第一件事應該做什麼？",
    "q.l6#14.o0" to "確認自己與隊友的位置和安全，再檢查傷情與裝備",
    "q.l6#14.o1" to "馬上站起來",
    "q.l6#14.o2" to "繼續下撤",
    "q.l6#14.o3" to "先撿回鎬",
    "q.l6#14.e" to "停住不等於安全：可能還懸在坡上，也可能有隊友被連帶。先評估，再動作。",
    "q.l6#15.p" to "為什麼「用鎬尖猛砸冰面」不是有效的制動動作？",
    "q.l6#15.o0" to "制動需要持續壓力而不是一次衝擊，猛砸會讓鎬彈開",
    "q.l6#15.o1" to "因為太吵",
    "q.l6#15.o2" to "因為鎬會壞",
    "q.l6#15.o3" to "因為冰太硬",
    "q.l6#15.e" to "制動是「壓住並滑行減速」的過程。一次衝擊只會崩出冰屑，身體繼續下滑。",
    "q.l7#10.p" to "失穩的瞬間，最先要保護的是？",
    "q.l7#10.o0" to "頭部，同時把身體轉成俯臥或仰臥的可制動姿態",
    "q.l7#10.o1" to "揹包",
    "q.l7#10.o2" to "冰鎬",
    "q.l7#10.o3" to "手機",
    "q.l7#10.e" to "頭部撞擊是滑墜致死的主要原因之一。轉體、護頭、壓鎬要同時開始。",
    "q.l7#11.p" to "看到落石或有人滑墜時，標準呼喊是？",
    "q.l7#11.o0" to "大聲喊「落石！」或「墜落！」，短促重複",
    "q.l7#11.o1" to "安靜觀察",
    "q.l7#11.o2" to "只揮手",
    "q.l7#11.o3" to "吹口哨",
    "q.l7#11.e" to "呼喊的作用是讓下方的人立刻抬頭並躲避。聲音比解釋重要，短促重複比長篇有效。",
    "q.l7#12.p" to "結組行進中一人滑墜，其他人應該？",
    "q.l7#12.o0" to "立即制動並保持繩的張力，不要同時移動",
    "q.l7#12.o1" to "一起跑過去",
    "q.l7#12.o2" to "鬆開繩子",
    "q.l7#12.o3" to "原地坐下",
    "q.l7#12.e" to "同時移動會讓繩失去張力，墜落者繼續下滑。制動的第一步是「穩住自己」。",
    "q.l7#13.p" to "滑墜停止後，繩子仍然繃緊，正確的處理是？",
    "q.l7#13.o0" to "維持張力，先建立保護再靠近檢視",
    "q.l7#13.o1" to "立刻松繩",
    "q.l7#13.o2" to "讓對方自己爬上來",
    "q.l7#13.o3" to "割斷繩子",
    "q.l7#13.e" to "松繩可能讓對方再次滑落。先把自己固定，才談得上救援。",
    "q.l7#14.p" to "為什麼冰爪在滑墜中反而可能造成傷害？",
    "q.l7#14.o0" to "齒會勾住雪面或衣物，導致扭傷或急停",
    "q.l7#14.o1" to "因為太重",
    "q.l7#14.o2" to "因為會脫落",
    "q.l7#14.o3" to "因為會磨壞",
    "q.l7#14.e" to "滑墜時腳突然被齒勾住，身體會以關節為軸翻轉。這也是「腳朝下、屈膝」姿勢重要的原因。",
    "q.l7#15.p" to "下撤階段事故高發，最主要的原因是？",
    "q.l7#15.o0" to "疲勞、注意力下降，加上「已經完成」的心理鬆懈",
    "q.l7#15.o1" to "天黑",
    "q.l7#15.o2" to "裝備損耗",
    "q.l7#15.o3" to "路線變難",
    "q.l7#15.e" to "下撤時的地形往往更暴露，而人的警惕性最低。把下撤當成「另一半行程」來計劃，是必要的。",
    "q.l8#10.p" to "較陡的硬雪坡下降，推薦的姿勢是？",
    "q.l8#10.o0" to "面朝坡內、三點接觸逐步下移",
    "q.l8#10.o1" to "面朝外快走",
    "q.l8#10.o2" to "滑降",
    "q.l8#10.o3" to "跳下",
    "q.l8#10.e" to "面朝坡內能用冰鎬隨時制動。面朝外只適合緩坡或軟雪。",
    "q.l8#11.p" to "控制式滑降（glissade）的制動準備是？",
    "q.l8#11.o0" to "鎬始終處於可壓入的姿勢，隨時能停",
    "q.l8#11.o1" to "把鎬收進揹包",
    "q.l8#11.o2" to "雙手張開",
    "q.l8#11.o3" to "閉眼",
    "q.l8#11.e" to "滑降的樂趣建立在「隨時能停」上。姿勢不對或雪質過硬時，滑降會直接變成滑墜。",
    "q.l8#12.p" to "繩降前必須完成的檢查是？",
    "q.l8#12.o0" to "錨點、繩結、繩尾、下降器穿繩方向、備份",
    "q.l8#12.o1" to "只看錨點",
    "q.l8#12.o2" to "只看繩長",
    "q.l8#12.o3" to "只看隊友",
    "q.l8#12.e" to "繩降事故幾乎都出在這五項中的某一項。念出來逐項確認，比「我覺得沒問題」可靠。",
    "q.l8#13.p" to "下降時最容易被上方落石擊中的位置是？",
    "q.l8#13.o0" to "繩子的正下方",
    "q.l8#13.o1" to "側面三公尺外",
    "q.l8#13.o2" to "錨點旁邊",
    "q.l8#13.o3" to "平臺後方",
    "q.l8#13.e" to "正下方是落石的必經路線。下降時儘量斜向一側，並在平臺邊緣快速透過。",
    "q.l8#14.p" to "雙繩下降後取繩失敗，最常見的原因是？",
    "q.l8#14.o0" to "繩尾打結、繩結卡在岩縫，或兩根繩長度不一致",
    "q.l8#14.o1" to "繩子太舊",
    "q.l8#14.o2" to "下降器太小",
    "q.l8#14.o3" to "錨點太高",
    "q.l8#14.e" to "取繩前要確認繩尾沒有打結、沒有纏掛、兩股長度一致。卡住時先改變角度，不要硬拽。",
    "q.l8#15.p" to "下降時繩尾打結的作用是？",
    "q.l8#15.o0" to "防止繩頭從下降器滑出導致失控墜落",
    "q.l8#15.o1" to "方便收繩",
    "q.l8#15.o2" to "標記長度",
    "q.l8#15.o3" to "減少磨損",
    "q.l8#15.e" to "繩長不夠時，繩頭滑出等於瞬間失去制動。這個結幾乎零成本，卻是很多事故的分水嶺。",
    "q.l9#10.p" to "八字結（figure-eight）相對單結的優勢是？",
    "q.l9#10.o0" to "受力後仍相對容易解開，且結構清晰易檢查",
    "q.l9#10.o1" to "更小",
    "q.l9#10.o2" to "更省繩",
    "q.l9#10.o3" to "不需要收尾",
    "q.l9#10.e" to "單結受力後會咬死，野外很難解開。八字結在承重後仍可拆解，這是它成為標準連線結的原因。",
    "q.l9#11.p" to "繩尾結（stopper knot）通常打在什麼位置？",
    "q.l9#11.o0" to "繩子的末端，防止繩頭從器械中滑出",
    "q.l9#11.o1" to "繩中間",
    "q.l9#11.o2" to "錨點上",
    "q.l9#11.o3" to "安全帶環上",
    "q.l9#11.e" to "下降、繩降、跟攀時都可能發生「繩頭滑出」。繩尾結是最後一道機械保險。",
    "q.l9#12.p" to "雙漁人結主要用於？",
    "q.l9#12.o0" to "連線兩根直徑相近的繩子",
    "q.l9#12.o1" to "連線繩子與安全帶",
    "q.l9#12.o2" to "做抓結",
    "q.l9#12.o3" to "固定錨點",
    "q.l9#12.e" to "雙漁人結體積小、透過性好，適合連線輔繩或扁帶。但它受力後較難解開，要留出繩尾。",
    "q.l9#13.p" to "所有繩結完成後都要做的一件事是？",
    "q.l9#13.o0" to "檢查走向與繩尾長度，並逐項複述確認",
    "q.l9#13.o1" to "拉一下就好",
    "q.l9#13.o2" to "拍照留證",
    "q.l9#13.o3" to "塗蠟",
    "q.l9#13.e" to "「打對了」和「打完了」是兩件事。繩尾太短會在受力後滑脫，檢查要成為固定動作。",
    "q.l9#14.p" to "為什麼繩索打結處會成為系統的薄弱點？",
    "q.l9#14.o0" to "打結會讓繩子彎曲，強度明顯下降",
    "q.l9#14.o1" to "因為結太重",
    "q.l9#14.o2" to "因為顏色",
    "q.l9#14.o3" to "因為摩擦生熱",
    "q.l9#14.e" to "繩子在結處彎曲，受力不均。設計系統時應把結放在低負荷位置，而不是關鍵承力點上。",
    "q.l9#15.p" to "抓結（prusik 等摩擦結）最重要的特性是？",
    "q.l9#15.o0" to "受力時咬住主繩，鬆開時能推動，可作單向備份",
    "q.l9#15.o1" to "永遠鎖死",
    "q.l9#15.o2" to "越粗越好",
    "q.l9#15.o3" to "只能用於下降",
    "q.l9#15.e" to "抓結的價值在「單向」：承重鎖止、空載可移。這也是它能做備份與上升的原因。",
    "q.l10#10.p" to "穿好安全帶後必須檢查的「反向扣」指的是？",
    "q.l10#10.o0" to "腰帶與腿環的回穿扣是否穿過雙環並留出足夠尾長",
    "q.l10#10.o1" to "主鎖是否鎖門",
    "q.l10#10.o2" to "繩結是否打緊",
    "q.l10#10.o3" to "頭盔是否扣好",
    "q.l10#10.e" to "回穿不到位是初學者最常見的安全帶錯誤，外觀看起來「穿好了」，受力時卻會鬆脫。",
    "q.l10#11.p" to "結組行進時，繩尾應該怎麼處理？",
    "q.l10#11.o0" to "末端固定在繩包或系在身上，避免拖地",
    "q.l10#11.o1" to "隨意拖在雪面",
    "q.l10#11.o2" to "完全展開",
    "q.l10#11.o3" to "纏在手上",
    "q.l10#11.e" to "拖地的繩尾會勾住冰爪、岩石與雪橋，也會在墜落時變成絆索。收好是基本紀律。",
    "q.l10#12.p" to "結組間距為什麼不能過短？",
    "q.l10#12.o0" to "一人墜入裂縫時會直接把隊友拽進去，救援空間也不夠",
    "q.l10#12.o1" to "因為繩不夠",
    "q.l10#12.o2" to "因為走不快",
    "q.l10#12.o3" to "因為不好看",
    "q.l10#12.e" to "間距是「反應距離」。太短等於把兩個人綁成一個重物，太長則制動與溝通變難。",
    "q.l10#13.p" to "從結組行進轉為領攀保護，最先要建立的是？",
    "q.l10#13.o0" to "可靠的確保站與自我保護",
    "q.l10#13.o1" to "繩子",
    "q.l10#13.o2" to "通訊",
    "q.l10#13.o3" to "拍照",
    "q.l10#13.e" to "轉換階段是事故高發點：此時人可能「既沒結組也沒保護」。先建站，再解繩。",
    "q.l10#14.p" to "結組在什麼情況下反而增加風險？",
    "q.l10#14.o0" to "在沒有墜落風險的緩坡上，繩結與繩距會增加絆倒與溝通成本",
    "q.l10#14.o1" to "任何時候",
    "q.l10#14.o2" to "有裂縫時",
    "q.l10#14.o3" to "下坡時",
    "q.l10#14.e" to "結組是「針對墜落與裂縫」的工具。用錯場景，它帶來的麻煩會超過收益。",
    "q.l10#15.p" to "結組前全隊應該統一的事項是？",
    "q.l10#15.o0" to "繩距、口令、透過裂縫區的順序與停等訊號",
    "q.l10#15.o1" to "裝備品牌",
    "q.l10#15.o2" to "行進速度",
    "q.l10#15.o3" to "拍照分工",
    "q.l10#15.e" to "結組的可靠性來自「反應一致」。沒有統一口令，第一次意外就會變成混亂。",
    "q.m07#12.p" to "主鎖的鎖門應該朝哪個方向？",
    "q.m07#12.o0" to "背向岩壁、遠離摩擦與受力方向，避免被繩或岩角頂開",
    "q.m07#12.o1" to "朝上",
    "q.m07#12.o2" to "朝下",
    "q.m07#12.o3" to "隨意",
    "q.m07#12.e" to "鎖門被外力頂開是真實存在的失效方式。方向選錯，等於把可靠性交給運氣。",
    "q.m07#13.p" to "扁帶連線兩個錨點時，為什麼不能繞過尖銳岩角？",
    "q.m07#13.o0" to "銳邊會切傷扁帶，受力時強度大幅下降",
    "q.m07#13.o1" to "因為不好看",
    "q.m07#13.o2" to "因為會滑",
    "q.m07#13.o3" to "因為太短",
    "q.m07#13.e" to "扁帶被切出一個小口，強度就可能只剩一半。必須經過時加護套或改用鏈條延長。",
    "q.m07#14.p" to "冰錐的打入角度通常是？",
    "q.m07#14.o0" to "略微向上（約 10–15 度），與受力方向相反",
    "q.m07#14.o1" to "完全水平",
    "q.m07#14.o2" to "向下傾斜",
    "q.m07#14.o3" to "隨意",
    "q.m07#14.e" to "略微向上能順著受力方向，讓錐體壓向冰面而不是被拔出。冰質差時要更長、更斜。",
    "q.m07#15.p" to "確保站只有單一錨點時，最該做的是？",
    "q.m07#15.o0" to "增加一個獨立備份，或改用更可靠的地形",
    "q.m07#15.o1" to "照常使用",
    "q.m07#15.o2" to "多掛幾個主鎖",
    "q.m07#15.o3" to "縮短繩長",
    "q.m07#15.e" to "主鎖數量不等於冗餘。冗餘的前提是「失效原因不同」。",
    "q.l26#0.p" to "1:50 000 的地圖上，1 公分代表實地多少米？",
    "q.l26#0.o0" to "500 公尺",
    "q.l26#0.o1" to "50 公尺",
    "q.l26#0.o2" to "5 000 公尺",
    "q.l26#0.o3" to "5 公尺",
    "q.l26#0.e" to "比例尺分母去掉兩個零就是「1 公分對應多少米」：50 000 → 500 公尺。這是所有讀圖計算的起點。",
    "q.l26#1.p" to "等高距指的是？",
    "q.l26#1.o0" to "相鄰兩條等高線之間的高差",
    "q.l26#1.o1" to "等高線之間的水平距離",
    "q.l26#1.o2" to "地圖上兩點的高差",
    "q.l26#1.o3" to "山峰的相對高度",
    "q.l26#1.e" to "等高距越大，圖越概括。判斷陡緩看的是等高線的疏密，判斷高差看的是等高距。",
    "q.l26#2.p" to "磁偏角的定義是？",
    "q.l26#2.o0" to "磁北與真北之間的夾角",
    "q.l26#2.o1" to "地圖與地面的夾角",
    "q.l26#2.o2" to "坡面的傾角",
    "q.l26#2.o3" to "磁針的誤差",
    "q.l26#2.e" to "磁偏角每個地區不同，且會逐年變化。地圖上通常標出當年的數值與年變化量，用之前要按年份校正。",
    "q.l26#3.p" to "在地圖上畫出到目標的方位角之後，正確的行進方式是？",
    "q.l26#3.o0" to "按方位角走，同時用等高線與地物不斷校正",
    "q.l26#3.o1" to "低頭盯著指北針一路直走",
    "q.l26#3.o2" to "只看 GPS 的箭頭",
    "q.l26#3.o3" to "沿最明顯的小路走，不管方位",
    "q.l26#3.e" to "方位角給你「大致方向」，地形特徵給你「具體位置」。只看針容易走偏一個山脊，代價是幾小時。",
    "q.l26#4.p" to "等高線越密，說明？",
    "q.l26#4.o0" to "坡越陡",
    "q.l26#4.o1" to "坡越緩",
    "q.l26#4.o2" to "海拔越高",
    "q.l26#4.o3" to "地表越平坦",
    "q.l26#4.e" to "等高線密 = 同樣的水平距離裡有更大的高差 = 更陡。這條在看「哪條上坡更省力」時最有用。",
    "q.l26#5.p" to "GPS 在野外最應該被當作什麼？",
    "q.l26#5.o0" to "加速器與備份，而不是唯一導航手段",
    "q.l26#5.o1" to "唯一導航手段",
    "q.l26#5.o2" to "娛樂裝置",
    "q.l26#5.o3" to "求救裝置",
    "q.l26#5.e" to "電量、低溫、進水、跌落都會讓它失效。紙質地圖與指北針是唯一不依賴電池的方案。",
    "q.l26#6.p" to "地圖定向（把地圖擺正）指的是？",
    "q.l26#6.o0" to "讓地圖的北與實際的北對齊",
    "q.l26#6.o1" to "把地圖折到當前區域",
    "q.l26#6.o2" to "把地圖裝進防水袋",
    "q.l26#6.o3" to "把地圖上的路線畫粗",
    "q.l26#6.e" to "地圖定向之後，圖上的山脊與山谷才能與眼前的對應起來。很多人讀不懂圖，第一步就錯在這裡。",
    "q.l26#7.p" to "在雪坡或霧中失去視野時，最可靠的定位方法是？",
    "q.l26#7.o0" to "用指北針測方位角 + 計時/計步估算距離",
    "q.l26#7.o1" to "憑感覺",
    "q.l26#7.o2" to "等雲開",
    "q.l26#7.o3" to "跟著別人的腳印",
    "q.l26#7.e" to "能見度差時地形參照全消失，只能靠「角度 + 距離」。計步需要提前標定自己的步頻，否則誤差很大。",
    "q.l26#8.p" to "一套不依賴電子的導航裝備至少包括？",
    "q.l26#8.o0" to "紙質地形圖（含當前區域）",
    "q.l26#8.o1" to "指北針",
    "q.l26#8.o2" to "高度計或手錶",
    "q.l26#8.o3" to "備用電池",
    "q.l26#8.e" to "第四項服務於電子裝置，不屬於「不依賴電子」的那一套。地圖、指北針、高度計三者配合，足以定位與行進。",
    "q.l26#9.p" to "哪些情況會讓 GPS 軌跡變得不可靠？",
    "q.l26#9.o0" to "峽谷與陡壁造成訊號遮擋",
    "q.l26#9.o1" to "低溫導致電量驟降",
    "q.l26#9.o2" to "在雪簷下停留",
    "q.l26#9.o3" to "路線本身很直",
    "q.l26#9.e" to "前三種都會讓定位漂移或斷電。路線直不直與訊號無關，但直路往往讓人更依賴裝置、更少看地形。",
    "q.l26#10.p" to "讀圖時用來確認自己位置的線索包括？",
    "q.l26#10.o0" to "所在坡面的朝向",
    "q.l26#10.o1" to "腳下的等高線形態（山脊/山谷/鞍部）",
    "q.l26#10.o2" to "與明顯地物的方位關係",
    "q.l26#10.o3" to "雲的形狀",
    "q.l26#10.e" to "坡向、等高線形態、與明顯地物的方位關係，三者交叉就能定位。雲的形狀屬於天氣判斷，不是定位線索。",
    "q.l26#11.p" to "把一次完整的方位定向排成正確順序。",
    "q.l26#11.o0" to "地圖定向，讓圖北對齊實北",
    "q.l26#11.o1" to "確認自己當前位置",
    "q.l26#11.o2" to "量出到目標點的方位角",
    "q.l26#11.o3" to "按方位角行進並核對地形",
    "q.l26#11.e" to "順序不能跳：位置不確定，量出來的方位角毫無意義；不核對地形，走的就是一條「理論直線」。",
    "q.l26#12.p" to "在沒有明顯地標的地形裡，走一段方位角的順序是？",
    "q.l26#12.o0" to "選一個遠處的中間目標點",
    "q.l26#12.o1" to "走到該點後重新核對位置",
    "q.l26#12.o2" to "再選下一個中間目標點",
    "q.l26#12.o3" to "接近目標後用地物確認",
    "q.l26#12.e" to "長距離直線在起伏地形裡幾乎走不出來。分段設中間點，是讓「角度」落到實際地形上的唯一辦法。",
    "q.l26#13.p" to "磁北與真北之間的夾角叫 ______ 角。",
    "q.l26#13.a0" to "磁偏",
    "q.l26#13.a1" to "磁偏角",
    "q.l26#13.a2" to "declination",
    "q.l26#13.e" to "磁偏角（declination）需要用地圖上標註的當年數值修正，否則每公里可能偏出幾十公尺。",
    "q.l26#14.p" to "1:25 000 的地圖上，1 公分代表實地 ______ 公尺。",
    "q.l26#14.a0" to "250",
    "q.l26#14.e" to "分母去掉兩個零：25 000 → 250 公尺。比例尺越大，細節越多，圖幅覆蓋越小。",
    "q.l26#15.p" to "等高距為 10 公尺時，從 3 200 公尺等高線走到 3 280 公尺等高線，需要跨過 ______ 條等高線（不含起點）。",
    "q.l26#15.a0" to "8",
    "q.l26#15.e" to "（3 280 − 3 200）÷ 10 = 8。這類計算在估算爬升與用時的時候每天都會用到。",
    "q.l26#16.p" to "把地形特徵與它在圖上的表現對應起來。",
    "q.l26#16.l0" to "山脊",
    "q.l26#16.l1" to "山谷",
    "q.l26#16.l2" to "鞍部",
    "q.l26#16.l3" to "陡崖",
    "q.l26#16.r0" to "等高線凸向低處",
    "q.l26#16.r1" to "等高線凸向高處",
    "q.l26#16.r2" to "兩組等高線之間的低點，兩側都高",
    "q.l26#16.r3" to "多條等高線重合或極密",
    "q.l26#16.e" to "「凸向低處是脊、凸向高處是谷」是讀圖最實用的一條口訣。鞍部是路線選擇裡的關鍵地形——它往往是最低通路。",
    "q.l26#17.p" to "把導航工具與它的侷限對應起來。",
    "q.l26#17.l0" to "GPS",
    "q.l26#17.l1" to "指北針",
    "q.l26#17.l2" to "高度計",
    "q.l26#17.l3" to "紙質地圖",
    "q.l26#17.r0" to "依賴電量與衛星訊號，峽谷與低溫下易失效",
    "q.l26#17.r1" to "受附近鐵磁物干擾，且需校正磁偏角",
    "q.l26#17.r2" to "只能給高度，不能給平面位置",
    "q.l26#17.r3" to "需要版本更新，可能不覆蓋新路線",
    "q.l26#17.e" to "每種工具都有失效方式，所以導航要「組合使用」：一種失效時另一種還能給你一個約束條件。",
    "q.l27#0.p" to "營地選址時，優先順序最高的是？",
    "q.l27#0.o0" to "避開落石、雪崩道與洪水線",
    "q.l27#0.o1" to "風景好",
    "q.l27#0.o2" to "離路線最近",
    "q.l27#0.o3" to "地面最平",
    "q.l27#0.e" to "安全 > 水源 > 平整 > 舒適。這條順序反過來，就會出「帳篷紮在雪崩堆積區」這類事故。",
    "q.l27#1.p" to "在雪坡上紮營，第一步應該做什麼？",
    "q.l27#1.o0" to "踩實雪面並挖出水平平臺",
    "q.l27#1.o1" to "直接鋪帳篷",
    "q.l27#1.o2" to "先燒水",
    "q.l27#1.o3" to "先固定風繩",
    "q.l27#1.e" to "雪面不平，睡一夜會持續滑動；平臺沒挖出來，帳篷受力不均，風一吹就變形。",
    "q.l27#2.p" to "關於營地和取水點的距離，合理的做法是？",
    "q.l27#2.o0" to "取水方便但要離水源 60 公尺以上紮營",
    "q.l27#2.o1" to "緊貼水邊",
    "q.l27#2.o2" to "在水裡",
    "q.l27#2.o3" to "越遠越好，兩公里",
    "q.l27#2.e" to "60 公尺是通行的衛生距離：既能減少汙染水源，也能避開夜間漲水。貼水紮營是山洪事故的典型場景。",
    "q.l27#3.p" to "大本營裡炊事區與睡眠區應該怎麼安排？",
    "q.l27#3.o0" to "分開設定，炊事區遠離睡眠區",
    "q.l27#3.o1" to "合併在一起更方便",
    "q.l27#3.o2" to "炊事區在帳篷內",
    "q.l27#3.o3" to "無所謂",
    "q.l27#3.e" to "分開的理由有三：明火風險、一氧化碳、食物氣味引來動物。擠在一起省了十幾公尺路，代價可能是整頂帳篷。",
    "q.l27#4.p" to "在冰面或硬雪上固定帳篷，正確的做法是？",
    "q.l27#4.o0" to "用冰錐、雪錨或埋雪袋，不能只靠石塊壓",
    "q.l27#4.o1" to "用石頭壓住就行",
    "q.l27#4.o2" to "把風繩系在登山杖上",
    "q.l27#4.o3" to "不用固定",
    "q.l27#4.e" to "冰面沒有可壓的鬆散物，風力會把帳篷連樁拔起。冰錐與雪錨才是有效錨點。",
    "q.l27#5.p" to "離開營地時，火跡應該怎麼處理？",
    "q.l27#5.o0" to "用水澆透、把灰燼散開並恢復原狀",
    "q.l27#5.o1" to "用土蓋上",
    "q.l27#5.o2" to "留著下次用",
    "q.l27#5.o3" to "不用管",
    "q.l27#5.e" to "把灰燼散開是為了讓它儘快迴歸自然外觀。留下的火圈會一直存在，也會誘導後來者在同一處生火。",
    "q.l27#6.p" to "颳大風時，帳篷最容易從哪個環節失效？",
    "q.l27#6.o0" to "風繩與固定點——受力不均先把一側拔起",
    "q.l27#6.o1" to "帳篷布料",
    "q.l27#6.o2" to "拉鍊",
    "q.l27#6.o3" to "地布",
    "q.l27#6.e" to "風繩角度與固定點決定抗風。帳篷被吹壞，多數不是布破了，而是某一側固定點先失效。",
    "q.l27#7.p" to "夜間下雪，早上發現帳篷被埋了一半，正確的處理是？",
    "q.l27#7.o0" to "先挖出通風口與門，再清周邊積雪",
    "q.l27#7.o1" to "先拍照",
    "q.l27#7.o2" to "直接收帳篷",
    "q.l27#7.o3" to "等雪停",
    "q.l27#7.e" to "通風口堵住意味著一氧化碳與缺氧風險。先保通氣，再談其他。",
    "q.l27#8.p" to "下面哪些屬於「地形陷阱」，不適合紮營？",
    "q.l27#8.o0" to "雪崩堆積區的坡腳",
    "q.l27#8.o1" to "乾涸河床與沖溝",
    "q.l27#8.o2" to "山脊的風口",
    "q.l27#8.o3" to "林間平坦空地",
    "q.l27#8.e" to "前三項分別是雪崩、山洪、強風的典型危險位。林間空地相對安全，但仍要檢查是否有枯枝與倒木。",
    "q.l27#9.p" to "一個合格的營地應該滿足哪些條件？",
    "q.l27#9.o0" to "地面平整、排水良好",
    "q.l27#9.o1" to "避風但不封閉",
    "q.l27#9.o2" to "有可用的水源",
    "q.l27#9.o3" to "手機訊號滿格",
    "q.l27#9.e" to "前三項決定能不能睡好、會不會失溫。訊號屬於附加條件，不能為了訊號把營地挪到暴露的山脊上。",
    "q.l27#10.p" to "野外排洩與衛生，正確的做法包括？",
    "q.l27#10.o0" to "挖 15–20 公分深的貓洞，遠離水源 60 公尺以上",
    "q.l27#10.o1" to "衛生紙帶走而不是燒掉",
    "q.l27#10.o2" to "集中在同一處解決",
    "q.l27#10.o3" to "埋在雪裡",
    "q.l27#10.e" to "集中會加劇區域性汙染，埋雪在融雪後會全部暴露。貓洞 + 帶走紙張是通行的低影響做法。",
    "q.l27#11.p" to "把營地建設排成合理順序。",
    "q.l27#11.o0" to "評估落石、雪崩、洪水風險",
    "q.l27#11.o1" to "選定帳篷位並清平地面",
    "q.l27#11.o2" to "搭帳、佈置風繩與固定點",
    "q.l27#11.o3" to "劃分炊事區、儲物區與廁所區",
    "q.l27#11.e" to "先評估風險再動工。很多人是先搭好帳篷，才想起來抬頭看上方有沒有裂縫與懸冰。",
    "q.l27#12.p" to "野外挖貓洞的深度通常是 ______ 公分左右。",
    "q.l27#12.a0" to "15–20",
    "q.l27#12.a1" to "15-20",
    "q.l27#12.a2" to "15",
    "q.l27#12.a3" to "20",
    "q.l27#12.a4" to "15~20",
    "q.l27#12.e" to "15–20 公分是常被引用的深度：足夠分解，又不至於挖穿表土層。",
    "q.l27#13.p" to "營地與水源、路徑的最小衛生距離通常取 ______ 公尺。",
    "q.l27#13.a0" to "60",
    "q.l27#13.e" to "60 公尺（約 70 步）是通行的 LNT 距離，用於排洩、洗碗與洗漱。",
    "q.l27#14.p" to "把營地功能區與它的要求對應起來。",
    "q.l27#14.l0" to "睡眠區",
    "q.l27#14.l1" to "炊事區",
    "q.l27#14.l2" to "儲物區",
    "q.l27#14.l3" to "廁所區",
    "q.l27#14.r0" to "平整、避風、遠離明火與氣味",
    "q.l27#14.r1" to "通風、遠離帳篷、注意用火安全",
    "q.l27#14.r2" to "防潮防動物，靠近但不佔通道",
    "q.l27#14.r3" to "遠離水源 60 公尺以上，避開坡面徑流",
    "q.l27#14.e" to "分割槽是為了讓每種活動在自己合適的條件下進行。分割槽混亂最直接的後果是帳篷裡有食物氣味、睡覺區旁邊有明火。",
    "q.l27#15.p" to "營地旁邊就是一條漂亮的溪流，但上游兩公里正在下暴雨，應該怎麼判斷？",
    "q.l27#15.o0" to "不在河床邊紮營，夜間漲水風險高",
    "q.l27#15.o1" to "沒關係，溪流很小",
    "q.l27#15.o2" to "把帳篷往水邊挪一點",
    "q.l27#15.o3" to "在河裡放石頭擋水",
    "q.l27#15.e" to "山區溪流漲水可能在幾分鐘內發生，且聲音先到、水後到。不在河床、沖溝、扇狀地紮營，是硬規則。",
    "q.l27#16.p" to "為什麼營地不宜選在孤立的大樹下？",
    "q.l27#16.o0" to "雷擊與斷枝風險都更高",
    "q.l27#16.o1" to "樹下不通風",
    "q.l27#16.o2" to "樹根會絆人",
    "q.l27#16.o3" to "遮光",
    "q.l27#16.e" to "孤立高點是雷擊首選路徑，同時風暴裡的斷枝是常見傷害來源。樹林裡應選林間空地而不是單棵大樹下。",
    "q.l28#0.p" to "STOP 原則的第一步是什麼？",
    "q.l28#0.o0" to "停下來",
    "q.l28#0.o1" to "馬上原路返回",
    "q.l28#0.o2" to "打電話",
    "q.l28#0.o3" to "往上爬看路",
    "q.l28#0.e" to "停下來是為了讓判斷回到理性。人在迷路時的第一反應往往是加速，而這正是事故擴大的開始。",
    "q.l28#1.p" to "國際通用的求救訊號數量是？",
    "q.l28#1.o0" to "三次（三聲哨、三次火光、三堆煙）",
    "q.l28#1.o1" to "一次",
    "q.l28#1.o2" to "五次",
    "q.l28#1.o3" to "越多越好",
    "q.l28#1.e" to "「三」是國際山地求救約定。連續三次、間隔一分鐘重複，才容易被識別為求救而不是偶然聲響。",
    "q.l28#2.p" to "在野外，哪種方式傳遞求救訊號最省力且傳得遠？",
    "q.l28#2.o0" to "哨子",
    "q.l28#2.o1" to "大聲喊叫",
    "q.l28#2.o2" to "揮手",
    "q.l28#2.o3" to "吹口哨（用嘴）",
    "q.l28#2.e" to "喊叫幾分鐘就會失聲，而哨子在風裡仍能穿透。這也是「十大必需品」裡包含哨子的原因。",
    "q.l28#3.p" to "迷路後發現自己站在一片沒有明顯地形的緩坡上，優先做什麼？",
    "q.l28#3.o0" to "回憶最後一個確定位置，判斷原路返回是否可行",
    "q.l28#3.o1" to "繼續往下走找路",
    "q.l28#3.o2" to "原地等到天黑",
    "q.l28#3.o3" to "分開找路",
    "q.l28#3.e" to "「最後一個確定位置」是唯一可靠的錨點。分開找路是迷路事故里最危險的選項——一個人變成兩個人失蹤。",
    "q.l28#4.p" to "等待救援時，最應該優先保證的是？",
    "q.l28#4.o0" to "保溫與取水，其次是讓自己顯眼",
    "q.l28#4.o1" to "把包裡的食物吃完",
    "q.l28#4.o2" to "繼續找路",
    "q.l28#4.o3" to "睡一覺",
    "q.l28#4.e" to "多數「迷路後死亡」的案例死於失溫與脫水，而不是找不到路。保溫、飲水、可見性，是等待期的三件事。",
    "q.l28#5.p" to "計劃外的被迫過夜，最需要但最常被留在營地的是？",
    "q.l28#5.o0" to "頭燈與保暖層",
    "q.l28#5.o1" to "零食",
    "q.l28#5.o2" to "地圖",
    "q.l28#5.o3" to "水壺",
    "q.l28#5.e" to "短途行動時人們常把這兩樣留在營地。一旦被迫過夜，它們恰好決定你能不能撐到天亮。",
    "q.l28#6.p" to "發現隊友沒有按時間歸隊，第一步應該做什麼？",
    "q.l28#6.o0" to "確認最後目擊點與時間，同時啟動預先約定的失聯流程",
    "q.l28#6.o1" to "全體分頭去找",
    "q.l28#6.o2" to "繼續等",
    "q.l28#6.o3" to "先收帳篷",
    "q.l28#6.e" to "先固定資訊（時間、位置、裝備、狀態），再決定搜尋方式。全員散開找人是二次事故的高發做法。",
    "q.l28#7.p" to "晴天的鏡面反光為什麼有效？",
    "q.l28#7.o0" to "反射光能被遠處與空中看到，傳播距離遠超聲音",
    "q.l28#7.o1" to "因為鏡子亮",
    "q.l28#7.o2" to "因為會發出聲音",
    "q.l28#7.o3" to "因為能點火",
    "q.l28#7.e" to "直升機與遠處隊伍最容易捕捉到規律性的閃光。有太陽時，鏡面是價效比最高的訊號工具。",
    "q.l28#8.p" to "迷路後應該避免的做法包括？",
    "q.l28#8.o0" to "天黑後繼續趕路",
    "q.l28#8.o1" to "分頭行動",
    "q.l28#8.o2" to "沿溪流一路下行",
    "q.l28#8.o3" to "原地停下並建立遮蔽",
    "q.l28#8.e" to "夜間行進、分散、盲目沿溪下行，是迷路事故里最常見的三個致命選擇。停下並建立遮蔽反而是正確答案。",
    "q.l28#9.p" to "「十大必需品」通常包括哪些？",
    "q.l28#9.o0" to "導航工具（地圖/指北針）",
    "q.l28#9.o1" to "頭燈",
    "q.l28#9.o2" to "額外的保暖衣物",
    "q.l28#9.o3" to "防曬與急救用品",
    "q.l28#9.e" to "十大必需品的核心邏輯是「被迫過夜也能活下來」：導航、照明、保暖、飲水、食物、防曬、急救、火種、刀具、遮蔽。",
    "q.l28#10.p" to "求救資訊裡必須說清的內容？",
    "q.l28#10.o0" to "位置（座標或明顯地標）",
    "q.l28#10.o1" to "人數與傷情",
    "q.l28#10.o2" to "裝備與補給情況",
    "q.l28#10.o3" to "隊伍成立年份",
    "q.l28#10.e" to "救援方要知道「在哪、幾個人、什麼狀態、能撐多久」。前四項缺一項，都會多花幾小時確認。",
    "q.l28#11.p" to "把迷路後的處置排成正確順序。",
    "q.l28#11.o0" to "停下來，確認自己確實迷路",
    "q.l28#11.o1" to "回憶最後一個確定位置",
    "q.l28#11.o2" to "評估原路返回與切上明顯地形的可行性",
    "q.l28#11.o3" to "定下計劃並執行，同時留好求救方案",
    "q.l28#11.e" to "順序的核心是「先承認、再定位、後決策」。沒有承認迷路，後面三步都不會真的執行。",
    "q.l28#12.p" to "等待救援時的優先順序，正確的是？",
    "q.l28#12.o0" to "找避風處並加保暖層",
    "q.l28#12.o1" to "取水或化雪",
    "q.l28#12.o2" to "佈置可見訊號（哨子、鏡面、顏色鮮豔物）",
    "q.l28#12.o3" to "按固定間隔重複呼叫",
    "q.l28#12.e" to "先保命，再求援。反過來做，人可能在發出訊號之前就已經失溫。",
    "q.l28#13.p" to "國際求救訊號通常重複 ______ 次為一組。",
    "q.l28#13.a0" to "3",
    "q.l28#13.a1" to "三",
    "q.l28#13.e" to "三次一組、間隔一分鐘重複，是山地與海上通用的約定。",
    "q.l28#14.p" to "迷路處置的四步口訣是 STOP，其中 P 代表 ______。",
    "q.l28#14.a0" to "Plan",
    "q.l28#14.a1" to "plan",
    "q.l28#14.a2" to "計劃",
    "q.l28#14.e" to "Stop / Think / Observe / Plan。先停、再想、再看、最後定計劃。",
    "q.l28#15.p" to "把求救方式與它的適用條件對應起來。",
    "q.l28#15.l0" to "哨子",
    "q.l28#15.l1" to "鏡面反光",
    "q.l28#15.l2" to "三堆煙",
    "q.l28#15.l3" to "鮮豔衣物",
    "q.l28#15.r0" to "任何天氣，短促三聲重複",
    "q.l28#15.r1" to "晴天有陽光、能見度好",
    "q.l28#15.r2" to "白天、無強風、有開闊地",
    "q.l28#15.r3" to "直升機或遠處搜尋時鋪在地面",
    "q.l28#15.e" to "沒有一種方式全天候有效，所以要「同時用幾種」。求救的本質是提高被發現的機率，而不是找到最完美的方法。",
    "q.l28#16.p" to "手機沒有訊號，但隊伍帶了衛星通訊裝置，什麼時候該用？",
    "q.l28#16.o0" to "確認需要外部救援時立即用，不要等到天黑",
    "q.l28#16.o1" to "等第二天再說",
    "q.l28#16.o2" to "只在有人受傷時用",
    "q.l28#16.o3" to "留到最後一天",
    "q.l28#16.e" to "衛星裝置的電量與天氣窗口都有限，救援響應也需要時間。等到天黑或天氣轉壞，直升機往往就進不來了。",
    "q.l28#17.p" to "如果判斷必須自己走出去，出發前應該做什麼？",
    "q.l28#17.o0" to "留下字條寫明去向與時間，帶齊保暖與照明，標定路線",
    "q.l28#17.o1" to "直接走",
    "q.l28#17.o2" to "把裝備都留下減輕負重",
    "q.l28#17.o3" to "分頭走",
    "q.l28#17.e" to "「走出去」是一個需要記錄的決策：字條讓搜尋隊知道你去哪，裝備決定你能不能撐到目的地。",
    "q.m08#12.p" to "崗什卡與哈巴這類 5,000 公尺級山峰，最需要提前安排的是？",
    "q.m08#12.o0" to "適應節奏與天氣窗口，而不是技術難度",
    "q.m08#12.o1" to "裝備採購",
    "q.m08#12.o2" to "拍照機位",
    "q.m08#12.o3" to "隊友分工",
    "q.m08#12.e" to "5,000 公尺級的難點通常在海拔與天氣，而不是技術。把時間留給適應，比多練一個動作更划算。",
    "q.m08#13.p" to "關於山峰許可與嚮導要求，正確的做法是？",
    "q.m08#13.o0" to "提前確認當地規定，需要嚮導或備案的嚴格照辦",
    "q.m08#13.o1" to "到了再問",
    "q.m08#13.o2" to "繞過檢查站",
    "q.m08#13.o3" to "找熟人通融",
    "q.m08#13.e" to "很多 5,000 公尺級山峰要求備案或嚮導。無許可攀登會讓救援與保險同時失效。",
    "q.m08#14.p" to "選擇「三峰→主峰」這類進階路徑的邏輯是？",
    "q.m08#14.o0" to "先在難度較低的路線上驗證適應與體力，再疊加技術難度",
    "q.m08#14.o1" to "因為便宜",
    "q.m08#14.o2" to "因為近",
    "q.m08#14.o3" to "因為人多",
    "q.m08#14.e" to "進階的本質是「一次只增加一個變數」。同時增加海拔與技術難度，出問題時很難判斷原因。",
    "q.m08#15.p" to "出發前必須確認的撤退路線資訊包括？",
    "q.m08#15.o0" to "下撤路徑、備用營地位置、最近的醫療點與聯絡方式",
    "q.m08#15.o1" to "只有下撤路徑",
    "q.m08#15.o2" to "只有醫療點",
    "q.m08#15.o3" to "不需要",
    "q.m08#15.e" to "撤退不是「往回走」這麼簡單。天氣變壞時，最近的備用營地可能才是唯一可行選擇。",
    "q.l13#14.p" to "AMS 症狀通常在抵達高海拔後多久出現？",
    "q.l13#14.o0" to "6–12 小時",
    "q.l13#14.o1" to "立刻",
    "q.l13#14.o2" to "3 天后",
    "q.l13#14.o3" to "一週後",
    "q.l13#14.e" to "這個時間窗很重要：上山當天下午到夜裡是觀察期，也是「不要繼續上升」的原因。",
    "q.l13#15.p" to "AMS 與 HACE 最關鍵的鑑別點是？",
    "q.l13#15.o0" to "是否出現共濟失調或意識改變",
    "q.l13#15.o1" to "頭痛程度",
    "q.l13#15.o2" to "是否噁心",
    "q.l13#15.o3" to "心率快慢",
    "q.l13#15.e" to "頭痛、噁心在 AMS 裡常見；一旦走路不穩、意識不清，就應按 HACE 處理並立即下降。",
    "q.l13#16.p" to "AMS 症狀緩解 24 小時後，能否繼續上升？",
    "q.l13#16.o0" to "可以，但應放慢節奏並密切觀察",
    "q.l13#16.o1" to "可以隨意上升",
    "q.l13#16.o2" to "永遠不能再上升",
    "q.l13#16.o3" to "必須下撤 1,000 公尺",
    "q.l13#16.e" to "症狀完全緩解是「適應進展」的訊號。但節奏要更保守，且一旦復發就應停止上升。",
    "q.l13#17.p" to "下列哪種情況容易被誤判為 AMS？",
    "q.l13#17.o0" to "脫水、感冒與睡眠不足",
    "q.l13#17.o1" to "骨折",
    "q.l13#17.o2" to "凍傷",
    "q.l13#17.o3" to "雪盲",
    "q.l13#17.e" to "三者的症狀與 AMS 重疊。補液、休息後明顯緩解的，多半不是 AMS；不緩解或加重的，按 AMS 處理。",
    "q.l13#18.p" to "AMS 時使用止痛藥，需要注意什麼？",
    "q.l13#18.o0" to "止痛藥只掩蓋症狀，不能作為繼續上升的依據",
    "q.l13#18.o1" to "吃了就能上升",
    "q.l13#18.o2" to "可以加大劑量",
    "q.l13#18.o3" to "完全不能用",
    "q.l13#18.e" to "止痛藥讓「訊號」消失，但病程還在。症狀被掩蓋後繼續上升，是最常見的惡化路徑。",
    "q.l13#19.p" to "為什麼兒童與老人的高山症更容易被漏診？",
    "q.l13#19.o0" to "他們表達症狀的能力弱，行為改變往往先於主訴",
    "q.l13#19.o1" to "因為他們不敏感",
    "q.l13#19.o2" to "因為他們適應快",
    "q.l13#19.o3" to "因為他們少上山",
    "q.l13#19.e" to "兒童表現為嗜睡、哭鬧、不吃；老人可能只表現為「沒精神」。觀察行為比等他們說更可靠。",
    "q.l15#12.p" to "適應過程中，身體最先發生的改變是？",
    "q.l15#12.o0" to "通氣量增加（呼吸變深變快）",
    "q.l15#12.o1" to "紅細胞增多",
    "q.l15#12.o2" to "肌肉變強",
    "q.l15#12.o3" to "心率下降",
    "q.l15#12.e" to "通氣增加在幾小時內就開始，紅細胞增多需要數天到數週。所以「第一晚」最難熬。",
    "q.l15#13.p" to "為什麼酒精與鎮靜類藥物會加重高山症反應？",
    "q.l15#13.o0" to "它們抑制呼吸驅動，讓夜間低氧更嚴重",
    "q.l15#13.o1" to "因為它們讓人脫水",
    "q.l15#13.o2" to "因為它們傷胃",
    "q.l15#13.o3" to "因為它們影響睡眠",
    "q.l15#13.e" to "高原上呼吸驅動本就被削弱，這類物質會進一步壓制。醉酒的樣子還容易與 HACE 早期混淆。",
    "q.l15#14.p" to "「週期性呼吸」在高原夜間很常見，它的機制是？",
    "q.l15#14.o0" to "低氧引起過度通氣，隨後二氧化碳過低導致呼吸暫停，迴圈反覆",
    "q.l15#14.o1" to "氣道阻塞",
    "q.l15#14.o2" to "心臟問題",
    "q.l15#14.o3" to "心理作用",
    "q.l15#14.e" to "這是生理性的，不必恐慌。但它會打斷睡眠，也是「睡低一點」的理由之一。",
    "q.l15#15.p" to "適應不良的早期訊號不包括？",
    "q.l15#15.o0" to "食慾變好、睡眠改善",
    "q.l15#15.o1" to "持續頭痛",
    "q.l15#15.o2" to "夜間頻繁憋醒",
    "q.l15#15.o3" to "活動能力下降",
    "q.l15#15.e" to "「吃得下、睡得好、走得動」是適應良好的三個標誌。反過來出現，就要放慢節奏。",
    "q.l15#16.p" to "間歇性低氧訓練（預適應）的證據強度如何？",
    "q.l15#16.o0" to "有一定生理效應，但不能替代實地適應",
    "q.l15#16.o1" to "可以完全替代適應",
    "q.l15#16.o2" to "完全無效",
    "q.l15#16.o3" to "只對運動員有效",
    "q.l15#16.e" to "預適應可能略微縮短適應時間，但上升速度與睡眠海拔仍是決定因素。別把它當捷徑。",
    "q.l15#17.p" to "感冒未愈就上高海拔，主要風險是？",
    "q.l15#17.o0" to "呼吸道炎症增加 HAPE 風險",
    "q.l15#17.o1" to "會傳染隊友",
    "q.l15#17.o2" to "會加重感冒",
    "q.l15#17.o3" to "沒有影響",
    "q.l15#17.e" to "這是最容易被忽略的一條。把感冒當成「小毛病」硬上，是 HAPE 的常見誘因。",
    "q.l15#18.p" to "適應期安排的「休息日」應該怎麼用？",
    "q.l15#18.o0" to "留在同一海拔活動、補覺補食，而不是完全躺平",
    "q.l15#18.o1" to "完全臥床",
    "q.l15#18.o2" to "繼續上升",
    "q.l15#18.o3" to "下山休息",
    "q.l15#18.e" to "輕度活動有助於通氣與迴圈。完全躺平反而會讓適應變慢，也不利於食慾。",
    "q.l15#19.p" to "為什麼說「行程設計本身就是預防」？",
    "q.l15#19.o0" to "上升速度與睡眠海拔決定了大部分風險，改行程比吃藥更根本",
    "q.l15#19.o1" to "因為行程好寫",
    "q.l15#19.o2" to "因為藥貴",
    "q.l15#19.o3" to "因為嚮導要求",
    "q.l15#19.e" to "把適應日寫進計劃的人，很少需要用藥；把行程排滿的人，往往靠藥硬撐。",
    "q.l14#12.p" to "HACE 的共濟失調，現場最簡單的測試是？",
    "q.l14#12.o0" to "腳跟接腳尖走一條直線",
    "q.l14#12.o1" to "單腳站立",
    "q.l14#12.o2" to "深蹲",
    "q.l14#12.o3" to "原地跳",
    "q.l14#12.e" to "走不成直線、步態搖晃就是陽性。這個測試不需要裝置，任何人都會做，適合作為日常篩查。",
    "q.l14#13.p" to "HAPE 的咳嗽通常會怎麼演變？",
    "q.l14#13.o0" to "從乾咳轉為咳泡沫樣痰，活動能力急劇下降",
    "q.l14#13.o1" to "從有痰轉為乾咳",
    "q.l14#13.o2" to "一直不變",
    "q.l14#13.o3" to "只在夜間出現",
    "q.l14#13.e" to "泡沫痰與靜息呼吸困難是 HAPE 的典型組合。等到出現粉紅色泡沫痰時，往往已經相當嚴重。",
    "q.l14#14.p" to "HAPE 更常發生在行程的哪個階段？",
    "q.l14#14.o0" to "上升後的第一到第二個夜晚",
    "q.l14#14.o1" to "出發前",
    "q.l14#14.o2" to "下撤途中",
    "q.l14#14.o3" to "回到平原後",
    "q.l14#14.e" to "夜間低氧最重，HAPE 常在第二晚出現。這也是「第一晚要特別留意」的原因。",
    "q.l14#15.p" to "疑似 HACE 或 HAPE 時，處置的優先順序是？",
    "q.l14#15.o0" to "立即下降 + 吸氧，藥物是輔助",
    "q.l14#15.o1" to "先吃藥觀察",
    "q.l14#15.o2" to "先休息一晚",
    "q.l14#15.o3" to "先等待救援",
    "q.l14#15.e" to "下降是唯一能確定性逆轉病程的措施。藥物與氧氣是為了「爭取下降的時間」。",
    "q.l14#16.p" to "高壓氧袋（Gamow bag）的作用與限制是？",
    "q.l14#16.o0" to "模擬下降、爭取時間，但不能替代真正的下降",
    "q.l14#16.o1" to "可以治癒",
    "q.l14#16.o2" to "可以長期使用",
    "q.l14#16.o3" to "只能給清醒者用",
    "q.l14#16.e" to "氧袋是「移動的低海拔」，需要人操作、耗體力、容量有限。它是過渡手段，不是終點。",
    "q.l14#17.p" to "一次行程中發生過 HAPE，恢復後應該？",
    "q.l14#17.o0" to "本次行程不再上升，安排下撤",
    "q.l14#17.o1" to "休息兩天再上",
    "q.l14#17.o2" to "換條路線繼續",
    "q.l14#17.o3" to "減半劑量繼續",
    "q.l14#17.e" to "HAPE 復發風險高，且再次發作可能更快更重。這一次的攀登應該結束。",
    "q.l14#18.p" to "HACE 的「意識改變」具體表現包括？",
    "q.l14#18.o0" to "嗜睡、答非所問、行為異常、出現幻覺",
    "q.l14#18.o1" to "只有昏迷",
    "q.l14#18.o2" to "只有頭痛",
    "q.l14#18.o3" to "只有噁心",
    "q.l14#18.e" to "早期可能只是「比平時安靜」或「說話重複」。隊友往往比本人更早發現，所以要互相觀察。",
    "q.l14#19.p" to "為什麼 HAPE 與 HACE 可能同時出現？",
    "q.l14#19.o0" to "兩者都是重度高山症的表現，病理上可以並存",
    "q.l14#19.o1" to "因為用藥相同",
    "q.l14#19.o2" to "因為症狀相似",
    "q.l14#19.o3" to "不會同時出現",
    "q.l14#19.e" to "臨床上常見 HACE 合併 HAPE 的病例。處置原則一致：下降、吸氧、必要時用藥。",
    "q.l16#12.p" to "失溫分級裡，「輕度」大致對應核心溫度？",
    "q.l16#12.o0" to "35–32 ℃，意識清醒、顫抖明顯",
    "q.l16#12.o1" to "38 ℃",
    "q.l16#12.o2" to "30 ℃ 以下",
    "q.l16#12.o3" to "28 ℃ 以下",
    "q.l16#12.e" to "輕度以顫抖與意識清醒為特徵。顫抖是身體還在產熱的訊號，也是「還有救」的訊號。",
    "q.l16#13.p" to "「顫抖停止」為什麼是危險訊號？",
    "q.l16#13.o0" to "說明身體已無法透過產熱維持體溫，進入中度以上失溫",
    "q.l16#13.o1" to "說明恢復了",
    "q.l16#13.o2" to "說明睡著了",
    "q.l16#13.o3" to "說明太累",
    "q.l16#13.e" to "從「抖得停不下來」到「不抖了」，不是好轉，而是代償失敗。需要立即復溫與送醫。",
    "q.l16#14.p" to "對意識不清的失溫者，正確的做法是？",
    "q.l16#14.o0" to "不給熱飲，改為保溫、隔離地面、輕柔搬運",
    "q.l16#14.o1" to "喂熱糖水",
    "q.l16#14.o2" to "搓手腳",
    "q.l16#14.o3" to "讓他走路",
    "q.l16#14.e" to "意識不清時吞嚥反射不可靠，喂飲會誤吸。粗暴搬動可能誘發心律失常。",
    "q.l16#15.p" to "現場復溫凍傷肢體，水溫應該控制在？",
    "q.l16#15.o0" to "37–40 ℃",
    "q.l16#15.o1" to "50–60 ℃",
    "q.l16#15.o2" to "冰水",
    "q.l16#15.o3" to "越熱越好",
    "q.l16#15.e" to "這個溫度接近體溫，既能復溫又不燙傷。過熱會造成二次損傷，過冷沒有效果。",
    "q.l16#16.p" to "為什麼凍傷復溫後要避免再次凍融？",
    "q.l16#16.o0" to "反覆凍融造成的組織損傷遠大於一次凍傷",
    "q.l16#16.o1" to "因為會疼",
    "q.l16#16.o2" to "因為會腫",
    "q.l16#16.o3" to "因為會留疤",
    "q.l16#16.e" to "「復溫後凍回去」比「一直凍著」更糟。所以復溫要在確保不再受凍的前提下進行。",
    "q.l16#17.p" to "凍傷部位在現場不建議做的是？",
    "q.l16#17.o0" to "用雪搓、用火烤、用酒精擦",
    "q.l16#17.o1" to "溫水復溫",
    "q.l16#17.o2" to "無菌敷料包裹",
    "q.l16#17.o3" to "抬高患肢",
    "q.l16#17.e" to "摩擦與乾熱都會加重組織損傷。現場只做「溫水復溫 + 保護 + 止痛」。",
    "q.l16#18.p" to "足部凍傷後，還能繼續行走嗎？",
    "q.l16#18.o0" to "儘量不要，行走會加重組織損傷；能等到救援就等",
    "q.l16#18.o1" to "可以走",
    "q.l16#18.o2" to "跑起來更快",
    "q.l16#18.o3" to "只要不疼就能走",
    "q.l16#18.e" to "復溫後的凍傷腳再承重，損傷會顯著加重。這也是「什麼時候復溫」需要權衡的原因。",
    "q.l16#19.p" to "預防失溫最關鍵的三件事是？",
    "q.l16#19.o0" to "保持乾燥、擋住風、及時補能量",
    "q.l16#19.o1" to "多穿衣服",
    "q.l16#19.o2" to "多喝熱水",
    "q.l16#19.o3" to "多走路",
    "q.l16#19.e" to "溼、風、能量不足是失溫的三個入口。加法是「排汗層 + 防風層 + 定時進食」。",
    "q.l29#0.p" to "在高海拔判斷脫水，最可靠的日常指標是？",
    "q.l29#0.o0" to "尿色變深、尿量減少",
    "q.l29#0.o1" to "口渴程度",
    "q.l29#0.o2" to "體重",
    "q.l29#0.o3" to "皮膚是否乾燥",
    "q.l29#0.e" to "口渴出現時身體已經缺水量明顯。尿色是最便宜的監測手段：淺黃為合適，深黃說明需要補液。",
    "q.l29#1.p" to "熱射病的判定核心是？",
    "q.l29#1.o0" to "核心溫度超過 40 ℃ 並伴意識改變",
    "q.l29#1.o1" to "出很多汗",
    "q.l29#1.o2" to "皮膚髮紅",
    "q.l29#1.o3" to "心跳加快",
    "q.l29#1.e" to "一旦出現意識改變（胡言亂語、步態不穩、昏迷），就應按熱射病處理並立即降溫送醫，不必等體溫計。",
    "q.l29#2.p" to "熱病處置的正確順序是？",
    "q.l29#2.o0" to "移到陰涼 → 解開衣物 → 物理降溫 → 補電解質",
    "q.l29#2.o1" to "先補電解質 → 再降溫",
    "q.l29#2.o2" to "先喂水 → 再抬到陰涼",
    "q.l29#2.o3" to "先按摩四肢",
    "q.l29#2.e" to "降溫優先於補液：高溫本身在損傷器官，而補液需要時間起效。按摩四肢反而可能加重迴圈負擔。",
    "q.l29#3.p" to "中暑者意識不清時，正確的做法是？",
    "q.l29#3.o0" to "不強行喂水，改為溼敷降溫並儘快送醫",
    "q.l29#3.o1" to "灌水",
    "q.l29#3.o2" to "喂鹽丸",
    "q.l29#3.o3" to "讓他自己喝",
    "q.l29#3.e" to "意識不清時吞嚥反射不可靠，強行喂水會誤吸。此時唯一有效的是降溫與專業救援。",
    "q.l29#4.p" to "水泡影響行走時，正確的處理是？",
    "q.l29#4.o0" to "消毒後從邊緣引流，保留表皮並覆蓋敷料",
    "q.l29#4.o1" to "整塊撕掉",
    "q.l29#4.o2" to "用針從中間扎",
    "q.l29#4.o3" to "不管它，繼續走",
    "q.l29#4.e" to "保留表皮是最好的敷料，能防感染。從中間扎孔容易撕裂，整塊撕掉則是把傷口暴露給髒襪子。",
    "q.l29#5.p" to "一度燙傷（皮膚髮紅、疼痛）的現場處理是？",
    "q.l29#5.o0" to "涼水衝 20 分鐘，再覆蓋清潔敷料",
    "q.l29#5.o1" to "塗牙膏",
    "q.l29#5.o2" to "塗油",
    "q.l29#5.o3" to "用酒精擦",
    "q.l29#5.e" to "冷水沖洗能帶走餘熱、減輕組織損傷。牙膏、油膏會封住熱量並增加感染風險。",
    "q.l29#6.p" to "高原上曬傷為什麼比平原更嚴重？",
    "q.l29#6.o0" to "紫外線更強，且雪面反射會加倍暴露",
    "q.l29#6.o1" to "因為風大",
    "q.l29#6.o2" to "因為皮膚更薄",
    "q.l29#6.o3" to "因為出汗多",
    "q.l29#6.e" to "海拔每升高 1,000 公尺紫外線約增 10–12%，雪面還能反射大部分紫外線。陰天與雪霧天同樣會曬傷。",
    "q.l29#7.p" to "判斷補液是否足夠，最實用的一組觀察是？",
    "q.l29#7.o0" to "尿色、尿量、靜息心率與精神狀態",
    "q.l29#7.o1" to "體重變化",
    "q.l29#7.o2" to "皮膚彈性",
    "q.l29#7.o3" to "口渴感",
    "q.l29#7.e" to "四項合起來才有意義。單看口渴或單看尿色都可能漏判，尤其在寒冷環境裡尿液會被濃縮。",
    "q.l29#8.p" to "隊員出現熱痙攣（大量出汗後肌肉抽筋），正確處理是？",
    "q.l29#8.o0" to "停止運動、到陰涼處、補充含電解質液體並輕柔拉伸",
    "q.l29#8.o1" to "繼續走，走開就好",
    "q.l29#8.o2" to "只喝白水",
    "q.l29#8.o3" to "用力揉搓肌肉",
    "q.l29#8.e" to "熱痙攣是電解質丟失的訊號。只補白水會進一步稀釋血鈉，可能讓情況變糟。",
    "q.l29#9.p" to "哪些因素會明顯增加熱病風險？",
    "q.l29#9.o0" to "高溼、無風",
    "q.l29#9.o1" to "穿著不透氣的衣物",
    "q.l29#9.o2" to "前一天睡眠不足",
    "q.l29#9.o3" to "大量出汗後只補白水",
    "q.l29#9.e" to "四項都在削弱散熱或電解質平衡。熱病從來不是單一原因，而是幾個不利條件疊加的結果。",
    "q.l29#10.p" to "常見外傷裡，現場必須優先處理的是？",
    "q.l29#10.o0" to "大量出血",
    "q.l29#10.o1" to "疑似脊柱損傷的搬運",
    "q.l29#10.o2" to "影響行走的足部傷口",
    "q.l29#10.o3" to "輕微擦傷",
    "q.l29#10.e" to "止血、脊柱保護、恢復行動能力屬於「不處理就惡化」的一類；輕微擦傷可以等回到營地再清創。",
    "q.l29#11.p" to "戶外應急小藥盒通常應包含？",
    "q.l29#11.o0" to "止痛退熱藥",
    "q.l29#11.o1" to "抗過敏藥",
    "q.l29#11.o2" to "止瀉與口服補液鹽",
    "q.l29#11.o3" to "抗生素（自行隨意使用）",
    "q.l29#11.e" to "前三種屬於對症處理，用途明確、風險可控。抗生素必須由醫生判斷，隨身攜帶不等於可以自行服用。",
    "q.l29#12.p" to "熱射病的現場處置順序，正確的是？",
    "q.l29#12.o0" to "移到陰涼、脫去多餘衣物",
    "q.l29#12.o1" to "冷水澆淋或冰敷頸部、腋下、腹股溝",
    "q.l29#12.o2" to "監測意識與呼吸，準備呼救",
    "q.l29#12.o3" to "儘快轉運，途中持續降溫",
    "q.l29#12.e" to "順序的核心是「降溫不中斷」。熱射病的死亡率與高溫持續時間直接相關，轉運途中也要繼續降溫。",
    "q.l29#13.p" to "處理足部水泡的順序，正確的是？",
    "q.l29#13.o0" to "清潔雙手與工具並消毒",
    "q.l29#13.o1" to "從水泡邊緣穿刺引流",
    "q.l29#13.o2" to "保留表皮，覆蓋敷料",
    "q.l29#13.o3" to "換乾爽襪子，調整鞋帶",
    "q.l29#13.e" to "感染是水泡最主要的併發症。消毒、保留表皮、保持乾燥，三步缺一不可。",
    "q.l29#14.p" to "熱射病的核心溫度判定線是 ______ ℃（填整數）。",
    "q.l29#14.a0" to "40",
    "q.l29#14.e" to "40 ℃ 加上意識改變，是熱射病的經典判定。現場沒有體溫計時，以意識狀態為先。",
    "q.l29#15.p" to "燙傷後建議用涼水持續沖洗約 ______ 分鐘。",
    "q.l29#15.a0" to "20",
    "q.l29#15.e" to "20 分鐘能有效帶走餘熱。時間不夠，熱量會繼續向深層組織傳導。",
    "q.l29#16.p" to "脫水最早期的可靠訊號之一是尿色變 ______。",
    "q.l29#16.a0" to "深",
    "q.l29#16.a1" to "深黃",
    "q.l29#16.a2" to "變深",
    "q.l29#16.e" to "尿色變深說明尿液被濃縮。這是最便宜、最容易每天自查的指標。",
    "q.l29#17.p" to "把熱病分級與典型表現對應起來。",
    "q.l29#17.l0" to "熱痙攣",
    "q.l29#17.l1" to "熱衰竭",
    "q.l29#17.l2" to "熱射病前期",
    "q.l29#17.l3" to "熱射病",
    "q.l29#17.r0" to "大量出汗後肌肉抽筋，意識清醒",
    "q.l29#17.r1" to "乏力、頭暈、噁心，皮膚溼冷",
    "q.l29#17.r2" to "體溫升高、頭痛、動作不協調",
    "q.l29#17.r3" to "核心溫度 >40 ℃ 並出現意識改變",
    "q.l29#17.e" to "四級是連續惡化的過程，不是四個獨立疾病。識別在哪一級，決定你是「停下補水」還是「立即降溫呼救」。",
    "q.l29#18.p" to "把外傷與現場處置對應起來。",
    "q.l29#18.l0" to "大量出血",
    "q.l29#18.l1" to "扭傷",
    "q.l29#18.l2" to "燒傷",
    "q.l29#18.l3" to "疑似脊柱損傷",
    "q.l29#18.r0" to "直接壓迫止血，必要時加壓包紮",
    "q.l29#18.r1" to "休息、冷敷、加壓、抬高（RICE）",
    "q.l29#18.r2" to "涼水衝 20 分鐘後覆蓋清潔敷料",
    "q.l29#18.r3" to "避免搬動，保持軸線固定並呼救",
    "q.l29#18.e" to "四類處置的共同點是「先做不會做錯的動作」：壓迫、固定、降溫、不動。等專業判斷，而不是臨場發明手法。",
    "q.l29#19.p" to "隊伍裡有人連續兩天尿色深黃、頭痛、乏力，最合理的判斷是？",
    "q.l29#19.o0" to "先按脫水處理並觀察，同時警惕高山症",
    "q.l29#19.o1" to "一定是高反，立即下撤",
    "q.l29#19.o2" to "只是累了",
    "q.l29#19.o3" to "多喝咖啡提神",
    "q.l29#19.e" to "脫水與 AMS 症狀高度重疊，處置也不衝突：補液、休息、觀察。若補液後仍不緩解或出現走路不穩，再按高山症處理。",
    "q.l29#20.p" to "為什麼在高海拔不主張「等到口渴再喝水」？",
    "q.l29#20.o0" to "口渴滯後於實際缺水，且高海拔呼吸失水更多",
    "q.l29#20.o1" to "因為水太重",
    "q.l29#20.o2" to "因為喝水會高反",
    "q.l29#20.o3" to "因為會頻繁上廁所",
    "q.l29#20.e" to "高原乾燥、呼吸量大，隱性失水明顯。等到口渴，判斷力往往已經開始下降。",
    "q.l29#21.p" to "隊員在烈日下走完後出現頭痛、噁心、皮膚溼冷，第一步做什麼？",
    "q.l29#21.o0" to "立即停止運動、移到陰涼、開始降溫並補電解質",
    "q.l29#21.o1" to "繼續走到營地",
    "q.l29#21.o2" to "給他吃止痛藥繼續走",
    "q.l29#21.o3" to "讓他多穿點防止受涼",
    "q.l29#21.e" to "這是熱衰竭的典型表現。繼續運動會迅速推向熱射病，而熱射病是可以在幾十分鐘內致命的。",
    "q.l29#22.p" to "關於防曬，下面哪項最容易被忽略？",
    "q.l29#22.o0" to "嘴唇、鼻翼、耳後與下巴下方",
    "q.l29#22.o1" to "手臂",
    "q.l29#22.o2" to "小腿",
    "q.l29#22.o3" to "脖子後面",
    "q.l29#22.e" to "這些部位要麼沒有黑色素保護，要麼被反射光從下方照到。曬傷後進食、說話、戴頭盔都會疼。",
    "q.l30#0.p" to "急救包為什麼要分三層？",
    "q.l30#0.o0" to "三層用途不同：隨身處置、隊伍處置、大本營醫療",
    "q.l30#0.o1" to "為了好看",
    "q.l30#0.o2" to "為了分攤重量",
    "q.l30#0.o3" to "為了多帶藥",
    "q.l30#0.e" to "隨身包要能在三十秒內拿到，隊伍包要能處理骨折與失溫，大本營箱要能撐多日。合併成一個大包，等於在最需要的時候找不到東西。",
    "q.l30#1.p" to "個人隨身急救小包最該包含哪一組？",
    "q.l30#1.o0" to "止血敷料、水泡貼、止痛藥、防曬",
    "q.l30#1.o1" to "夾板與頸託",
    "q.l30#1.o2" to "氧氣瓶",
    "q.l30#1.o3" to "靜脈輸液",
    "q.l30#1.e" to "隨身包解決「立刻要用、體積要小」的問題。夾板與氧氣屬於隊伍層，不可能隨身。",
    "q.l30#2.p" to "隊伍急救包裡最不該缺的是？",
    "q.l30#2.o0" to "固定與保溫器材（夾板、保溫毯）",
    "q.l30#2.o1" to "創可貼",
    "q.l30#2.o2" to "體溫計",
    "q.l30#2.o3" to "潤喉糖",
    "q.l30#2.e" to "在高海拔，失溫與骨折是最需要現場處理的兩類問題。固定與保溫決定能否撐到救援到達。",
    "q.l30#3.p" to "關於處方藥的使用，正確的原則是？",
    "q.l30#3.o0" to "由醫生開具並說明適應證，隊內不互相推薦",
    "q.l30#3.o1" to "誰有經驗誰決定",
    "q.l30#3.o2" to "按說明書自己吃",
    "q.l30#3.o3" to "隊友之間可以互相分",
    "q.l30#3.e" to "高原用藥的禁忌與相互作用很多，且劑量與病程相關。互相給藥是這類事故里最常見的錯誤來源。",
    "q.l30#4.p" to "血氧監測的正確用法是？",
    "q.l30#4.o0" to "看同一高度的變化趨勢，而不是單次數值",
    "q.l30#4.o1" to "低於 90 就立即下撤",
    "q.l30#4.o2" to "只在白天測",
    "q.l30#4.o3" to "看誰的數字最高",
    "q.l30#4.e" to "單次血氧受溫度、末梢迴圈、測量方式影響很大。連續下降 + 症狀出現，才是有意義的訊號。",
    "q.l30#5.p" to "撤離預案裡最需要提前明確的是？",
    "q.l30#5.o0" to "誰有權決定撤離、聯絡誰、送到哪",
    "q.l30#5.o1" to "誰負責拍照",
    "q.l30#5.o2" to "誰背氧氣",
    "q.l30#5.o3" to "誰帶現金",
    "q.l30#5.e" to "撤離決策在壓力下最容易拖延。事先指定決策人與聯絡鏈，能把「討論幾小時」壓縮成「十分鐘」。",
    "q.l30#6.p" to "大本營醫療箱與隊伍包的關鍵區別是？",
    "q.l30#6.o0" to "大本營可以放處方藥、監測裝置與批次補給",
    "q.l30#6.o1" to "大本營的更輕",
    "q.l30#6.o2" to "大本營的只放創可貼",
    "q.l30#6.o3" to "沒有區別",
    "q.l30#6.e" to "大本營有穩定環境與固定人員，可以承擔更復雜的醫療物資；隊伍包必須輕、必須能隨身。",
    "q.l30#7.p" to "醫療角色應該怎麼安排？",
    "q.l30#7.o0" to "出發前指定醫療負責人，並讓全員知道是誰",
    "q.l30#7.o1" to "到時候看誰懂",
    "q.l30#7.o2" to "由體力最好的人兼",
    "q.l30#7.o3" to "不需要角色",
    "q.l30#7.e" to "角色不清，現場就會出現「大家都在等別人決定」。指定負責人不意味著他是醫生，而是他負責判斷與聯絡。",
    "q.l30#8.p" to "應急小藥盒裡適合常備的類別包括？",
    "q.l30#8.o0" to "止痛退熱",
    "q.l30#8.o1" to "抗過敏",
    "q.l30#8.o2" to "止瀉與口服補液鹽",
    "q.l30#8.o3" to "鎮靜安眠類",
    "q.l30#8.e" to "鎮靜安眠類會抑制呼吸驅動，在高海拔屬於高風險藥物，必須由醫生決定，不能作為常備自用。",
    "q.l30#9.p" to "哪些資訊應該寫進隊伍的醫療卡？",
    "q.l30#9.o0" to "過敏史",
    "q.l30#9.o1" to "長期用藥與劑量",
    "q.l30#9.o2" to "既往高山症史",
    "q.l30#9.o3" to "血型",
    "q.l30#9.e" to "四項都在急救時用到。血型在野外輸血場景裡幾乎用不上，但在轉運交接時是有用資訊。",
    "q.l30#10.p" to "判斷是否需要啟動撤離的因素包括？",
    "q.l30#10.o0" to "意識狀態改變",
    "q.l30#10.o1" to "靜息呼吸困難",
    "q.l30#10.o2" to "無法自行行走",
    "q.l30#10.o3" to "輕微頭痛但能吃能睡",
    "q.l30#10.e" to "前三項都是「不能再等」的訊號。輕微頭痛可以先觀察、補液、休息，不必立即撤離——過度反應也會消耗救援資源。",
    "q.l30#11.p" to "處理一名疑似骨折的隊員，順序正確的是？",
    "q.l30#11.o0" to "確認現場安全，避免二次傷害",
    "q.l30#11.o1" to "止血、覆蓋傷口",
    "q.l30#11.o2" to "固定傷肢，檢查末梢迴圈",
    "q.l30#11.o3" to "保溫並安排轉運",
    "q.l30#11.e" to "固定之後一定要檢查末梢（溫度、顏色、脈搏），否則可能因為綁得太緊造成新的損傷。",
    "q.l30#12.p" to "醫療事件的上報與記錄順序，正確的是？",
    "q.l30#12.o0" to "記錄時間、地點、症狀與處置",
    "q.l30#12.o1" to "通知隊內醫療負責人",
    "q.l30#12.o2" to "聯絡外部救援或醫生",
    "q.l30#12.o3" to "交接時把記錄一併交出",
    "q.l30#12.e" to "記錄先於聯絡：資訊不清楚，外部醫生也無法給建議。交接時記錄是最有價值的東西。",
    "q.l30#13.p" to "急救包通常分為個人隨身包、隊伍包與 ______ 醫療箱三層。",
    "q.l30#13.a0" to "大本營",
    "q.l30#13.a1" to "營地",
    "q.l30#13.a2" to "基地",
    "q.l30#13.e" to "三層分級是急救包設計的通用做法，核心是「按取用速度分層」。",
    "q.l30#14.p" to "判斷高山症情變化，血氧應看 ______ 而不是單次數值。",
    "q.l30#14.a0" to "趨勢",
    "q.l30#14.a1" to "變化趨勢",
    "q.l30#14.e" to "趨勢比絕對值可靠。同一高度持續下降，往往比一個偶然的低值更值得警惕。",
    "q.l30#15.p" to "把三層急救物資與它的定位對應起來。",
    "q.l30#15.l0" to "個人隨身包",
    "q.l30#15.l1" to "隊伍包",
    "q.l30#15.l2" to "大本營醫療箱",
    "q.l30#15.l3" to "撤離檔案",
    "q.l30#15.r0" to "30 秒內可取，處理出血、水泡、止痛",
    "q.l30#15.r1" to "處理固定、清創、保溫、給氧",
    "q.l30#15.r2" to "處方藥、監測裝置、多日補給",
    "q.l30#15.r3" to "保險單、救援電話、醫療記錄",
    "q.l30#15.e" to "四者的共同點是「事先分層」。臨時翻一個大包，往往在最急的那幾分鐘裡最慢。",
    "q.l30#16.p" to "隊友提出「帶點抗生素，路上不舒服就吃」，最合理的回應是？",
    "q.l30#16.o0" to "可以帶，但必須由醫生說明什麼情況下用、用多久",
    "q.l30#16.o1" to "帶著隨便吃",
    "q.l30#16.o2" to "完全不帶",
    "q.l30#16.o3" to "帶激素更有效",
    "q.l30#16.e" to "抗生素的關鍵是適應證與療程。帶了卻沒有明確規則，比不帶更危險——半程停藥會導致耐藥與復發。",
    "q.l30#17.p" to "在 6,000 公尺營地，隊友出現靜息呼吸困難，但血氧 82%、還能說話。應該？",
    "q.l30#17.o0" to "按疑似 HAPE 處理：休息、吸氧、準備下降",
    "q.l30#17.o1" to "繼續觀察一天",
    "q.l30#17.o2" to "讓他多喝水",
    "q.l30#17.o3" to "給他吃止痛藥",
    "q.l30#17.e" to "靜息呼吸困難是 HAPE 的典型訊號，血氧數字再「還行」也不能推翻症狀。下降是最確定的處置。",
    "q.l30#18.p" to "醫療記錄裡最容易被漏掉、但最重要的兩項是？",
    "q.l30#18.o0" to "時間與變化過程",
    "q.l30#18.o1" to "姓名與年齡",
    "q.l30#18.o2" to "血型與體重",
    "q.l30#18.o3" to "用藥品牌",
    "q.l30#18.e" to "「什麼時候開始、怎麼變化的」決定判斷。缺了時間軸，症狀描述幾乎無法解讀。",
    "q.l30#19.p" to "隊伍包裡的保溫毯（急救毯）主要用途是？",
    "q.l30#19.o0" to "反射體熱、擋風，配合隔絕地面使用",
    "q.l30#19.o1" to "當雨衣",
    "q.l30#19.o2" to "當擔架",
    "q.l30#19.o3" to "當帳篷",
    "q.l30#19.e" to "急救毯幾乎不透氣，單裹會積聚汗水。正確用法是「隔絕地面 + 擋風 + 配合衣物」，而不是直接貼身裹住。",
    "q.l30#20.p" to "為什麼建議在出發前做一次「醫療演練」？",
    "q.l30#20.o0" to "讓每個人知道東西在哪、角色是誰、流程怎麼走",
    "q.l30#20.o1" to "為了拍照",
    "q.l30#20.o2" to "為了消耗藥品",
    "q.l30#20.o3" to "沒有必要",
    "q.l30#20.e" to "急救的瓶頸通常不是知識，而是「找東西」和「等別人決定」。演練能把這兩項壓縮到幾分鐘。",
    "q.l30#21.p" to "有隊員隱瞞了哮喘病史，出發後才說，最該做的是？",
    "q.l30#21.o0" to "立即評估當前狀態、調整計劃、把資訊告知醫療負責人",
    "q.l30#21.o1" to "批評他一頓",
    "q.l30#21.o2" to "繼續走",
    "q.l30#21.o3" to "讓他自己負責",
    "q.l30#21.e" to "隱瞞病史的風險在於急救時用錯藥或漏判。發現後要補資訊、改計劃，而不是追責——追責只會讓人更不願說。",
    "q.l31#0.p" to "預測高山症最有力的單一因素是什麼？",
    "q.l31#0.o0" to "既往高山症病史",
    "q.l31#0.o1" to "年齡",
    "q.l31#0.o2" to "體能水平",
    "q.l31#0.o3" to "性別",
    "q.l31#0.e" to "既往史的意義在於它反映了個體的適應特徵。有過 AMS 的人，需要更保守的上升節奏。",
    "q.l31#1.p" to "關於體能和高山症反應的關係，正確的說法是？",
    "q.l31#1.o0" to "體能好不等於不容易高反，甚至可能因為升得快而更危險",
    "q.l31#1.o1" to "體能越好越安全",
    "q.l31#1.o2" to "體能越好越容易高反",
    "q.l31#1.o3" to "完全無關",
    "q.l31#1.e" to "體能決定你能走多快，適應決定你能升多高。兩者不是一回事，把體能當護身符是常見誤判。",
    "q.l31#2.p" to "下列哪一項會明顯增加高山症風險？",
    "q.l31#2.o0" to "帶著呼吸道感染上山",
    "q.l31#2.o1" to "提前一天到達",
    "q.l31#2.o2" to "多喝水",
    "q.l31#2.o3" to "睡眠充足",
    "q.l31#2.e" to "感染會讓肺泡與氣道處於炎症狀態，HAPE 的風險隨之上升。感冒未愈就上升，是臨床上常見的誘因。",
    "q.l31#3.p" to "年齡與高山症風險的關係是？",
    "q.l31#3.o0" to "年齡不是主要因素，個體差異更重要",
    "q.l31#3.o1" to "越年輕越危險",
    "q.l31#3.o2" to "越老越危險",
    "q.l31#3.o3" to "只與年齡有關",
    "q.l31#3.e" to "研究裡年齡的獨立作用很弱。真正有解釋力的是既往史、上升速度與健康狀況。",
    "q.l31#4.p" to "對「容易高反的人」最有效的預防措施是？",
    "q.l31#4.o0" to "放慢上升速度並安排適應日",
    "q.l31#4.o1" to "提前吃止痛藥",
    "q.l31#4.o2" to "多帶氧氣瓶",
    "q.l31#4.o3" to "加強體能訓練",
    "q.l31#4.e" to "行程設計本身就是最有效的預防。藥與氧是補救手段，節奏才是根本。",
    "q.l31#5.p" to "乙醯唑胺的作用邊界是？",
    "q.l31#5.o0" to "減輕症狀、幫助適應，但不能替代上升節奏",
    "q.l31#5.o1" to "可以讓人直接上 5,000 公尺",
    "q.l31#5.o2" to "能治好 HACE",
    "q.l31#5.o3" to "沒有任何副作用",
    "q.l31#5.e" to "它透過促進碳酸氫鹽排洩來刺激呼吸，屬於「輔助適應」。用它硬撐快速上升，只是把風險推後。",
    "q.l31#6.p" to "睡眠海拔為什麼比白天到達的最高點更重要？",
    "q.l31#6.o0" to "夜間通氣下降，低氧最重，睡眠高度決定夜間缺氧程度",
    "q.l31#6.o1" to "因為床更硬",
    "q.l31#6.o2" to "因為夜裡更冷",
    "q.l31#6.o3" to "因為睡不好會心情差",
    "q.l31#6.e" to "夜裡呼吸驅動最低，血氧下降最明顯。控制睡眠海拔的日升幅，是適應策略的核心。",
    "q.l31#7.p" to "女性在月經期上高海拔，正確的態度是？",
    "q.l31#7.o0" to "不是禁忌，但要關注鐵狀態與個人反應",
    "q.l31#7.o1" to "絕對不能上",
    "q.l31#7.o2" to "必須吃藥",
    "q.l31#7.o3" to "與男性完全相同，無需關注",
    "q.l31#7.e" to "月經不是高原禁忌，但貧血、經量多、疼痛會影響狀態與判斷。個體化評估比一刀切的規則更合理。",
    "q.l31#8.p" to "團隊裡有人「上次 5,000 公尺完全沒事」，這次是否可以加快上升？",
    "q.l31#8.o0" to "不能，每次反應都可能不同，仍按標準節奏",
    "q.l31#8.o1" to "可以，他有經驗",
    "q.l31#8.o2" to "可以快一倍",
    "q.l31#8.o3" to "可以跳過適應日",
    "q.l31#8.e" to "既往無症狀只是「這次風險略低」，不是免疫。把上一次當保證，是很多隊伍出事的起點。",
    "q.l31#9.p" to "兒童與青少年在高海拔的適應能力？",
    "q.l31#9.o0" to "與成人相近，但表達症狀的能力更弱，需要更細緻的觀察",
    "q.l31#9.o1" to "明顯更差",
    "q.l31#9.o2" to "明顯更強",
    "q.l31#9.o3" to "完全不能上高原",
    "q.l31#9.e" to "生理適應相近，難點在溝通：孩子說不清「頭痛」與「不舒服」，行為改變往往才是第一個訊號。",
    "q.l31#10.p" to "屬於「可執行的預防節奏」的做法包括？",
    "q.l31#10.o0" to "3,000 公尺以上睡眠海拔每天上升不超過 500 公尺",
    "q.l31#10.o1" to "每升 1,000 公尺安排一個休息日",
    "q.l31#10.o2" to "白天爬高、夜間睡低",
    "q.l31#10.o3" to "第一天直接睡到 4,000 公尺",
    "q.l31#10.e" to "前三條是公認的節奏原則。第一條尤其重要：它管的是「睡在哪」，不是「走到哪」。",
    "q.l31#11.p" to "哪些人需要更保守的上升計劃？",
    "q.l31#11.o0" to "既往有 AMS 或 HAPE 病史",
    "q.l31#11.o1" to "近期有呼吸道感染",
    "q.l31#11.o2" to "有睡眠呼吸暫停",
    "q.l31#11.o3" to "常年跑馬拉松",
    "q.l31#11.e" to "前三項直接削弱夜間通氣或既往適應表現。馬拉松成績好不能抵消這些因素。",
    "q.l31#12.p" to "預防措施裡屬於「非藥物」的有？",
    "q.l31#12.o0" to "控制上升速度",
    "q.l31#12.o1" to "避免酒精與鎮靜藥",
    "q.l31#12.o2" to "保證碳水攝入與飲水",
    "q.l31#12.o3" to "提前服用乙醯唑胺",
    "q.l31#12.e" to "酒精與鎮靜藥抑制呼吸驅動，是夜間低氧的放大器。最後一項屬於藥物，不是非藥物措施。",
    "q.l31#13.p" to "出現 AMS 症狀後的處置順序，正確的是？",
    "q.l31#13.o0" to "停止上升，原地休息觀察",
    "q.l31#13.o1" to "補液、保證進食與保暖",
    "q.l31#13.o2" to "評估症狀是否加重（走路是否穩、是否靜息呼吸困難）",
    "q.l31#13.o3" to "加重則立即下降並尋求醫療支援",
    "q.l31#13.e" to "核心是「不帶著症狀往上走」。觀察不等於硬撐，出現危險訊號就必須下降。",
    "q.l31#14.p" to "3,000 公尺以上，睡眠海拔的日升幅建議不超過 ______ 公尺。",
    "q.l31#14.a0" to "500",
    "q.l31#14.e" to "500 公尺是通行做法。注意它限制的是「睡哪」，白天可以上得更高。",
    "q.l31#15.p" to "大約每升高 ______ 公尺，建議安排一個休息日。",
    "q.l31#15.a0" to "1000",
    "q.l31#15.a1" to "1 000",
    "q.l31#15.a2" to "1,000",
    "q.l31#15.e" to "1,000 公尺一個休息日是常見節奏，具體還要看個人反應與路線條件。",
    "q.l31#16.p" to "把風險因素與它主要影響的疾病對應起來。",
    "q.l31#16.l0" to "快速上升",
    "q.l31#16.l1" to "呼吸道感染",
    "q.l31#16.l2" to "既往 HAPE 病史",
    "q.l31#16.l3" to "睡眠呼吸暫停",
    "q.l31#16.r0" to "AMS 與 HACE 的共同誘因",
    "q.l31#16.r1" to "主要增加 HAPE 風險",
    "q.l31#16.r2" to "再次發生 HAPE 的最強預測因子",
    "q.l31#16.r3" to "夜間低氧加重，影響適應",
    "q.l31#16.e" to "四者都指向同一件事：夜間通氣與肺迴圈承受的壓力。識別自己屬於哪一類，才能定出合適的節奏。",
    "q.l31#17.p" to "把預防手段與它的性質對應起來。",
    "q.l31#17.l0" to "控制上升速度",
    "q.l31#17.l1" to "適應日",
    "q.l31#17.l2" to "乙醯唑胺",
    "q.l31#17.l3" to "地塞米松",
    "q.l31#17.r0" to "行程設計，最根本的預防",
    "q.l31#17.r1" to "行程設計，用時間換適應",
    "q.l31#17.r2" to "輔助適應，處方藥",
    "q.l31#17.r3" to "治療用藥，不用於常規預防",
    "q.l31#17.e" to "前兩項不需要醫生，後兩項需要。把治療藥當預防藥，是很有風險的做法。",
    "q.l31#18.p" to "隊伍裡有人明顯比別人更容易高反，最合理的安排是？",
    "q.l31#18.o0" to "讓他走在隊伍中前段但按最慢節奏，並提前設好下撤點",
    "q.l31#18.o1" to "讓他走在最後",
    "q.l31#18.o2" to "讓他多吃藥",
    "q.l31#18.o3" to "勸他別來",
    "q.l31#18.e" to "節奏統一、位置可見、下撤點明確，這三件事比「勸退」更實際。把他甩在最後，是最容易出事的安排。",
    "q.l31#19.p" to "「我上次吃過乙醯唑胺，這次自己提前吃」這句話的問題在哪？",
    "q.l31#19.o0" to "用藥需要醫生評估適應證、劑量與禁忌，不能憑經驗自服",
    "q.l31#19.o1" to "藥太貴",
    "q.l31#19.o2" to "吃了會困",
    "q.l31#19.o3" to "沒有問題",
    "q.l31#19.e" to "磺胺過敏、腎功能、同時服用的其他藥物都會改變判斷。經驗可以提示「可能有效」，不能替代評估。",
    "q.l31#20.p" to "如果一名隊員在 4,500 公尺出現 AMS 症狀，但堅持要按計劃上 5,000 公尺，領隊應該？",
    "q.l31#20.o0" to "明確拒絕並給出替代方案（原地適應或下撤）",
    "q.l31#20.o1" to "讓他自己決定",
    "q.l31#20.o2" to "加藥後放行",
    "q.l31#20.o3" to "全隊陪他上",
    "q.l31#20.e" to "「不帶著症狀上升」是硬規則，不能靠投票或意志突破。給出替代方案，比單純禁止更容易被接受。",
    "q.l31#21.p" to "關於高海拔的飲水與飲食，哪一條是對的？",
    "q.l31#21.o0" to "主動少量多次飲水，優先碳水，保持食慾",
    "q.l31#21.o1" to "少喝水減少上廁所",
    "q.l31#21.o2" to "只吃高蛋白",
    "q.l31#21.o3" to "靠咖啡代替正餐",
    "q.l31#21.e" to "脫水與食慾下降會同時拖慢適應。高原上「能吃能喝」本身就是一項能力。",
    "q.l31#22.p" to "預防策略裡最容易被忽略、但對 HAPE 最關鍵的一條是？",
    "q.l31#22.o0" to "感冒未愈不上高海拔",
    "q.l31#22.o1" to "多帶一件衣服",
    "q.l31#22.o2" to "帶上血氧儀",
    "q.l31#22.o3" to "提前訂好住宿",
    "q.l31#22.e" to "呼吸道感染是 HAPE 的重要誘因，而它往往被當成「小毛病」。這條規則的價效比極高。",
    "q.m09#12.p" to "乙醯唑胺用於預防時的常用成人劑量是？",
    "q.m09#12.o0" to "125 mg，每日兩次",
    "q.m09#12.o1" to "500 mg，每日一次",
    "q.m09#12.o2" to "1,000 mg，每日一次",
    "q.m09#12.o3" to "按需服用",
    "q.m09#12.e" to "125 mg 每日兩次是技能書採用的口徑。它屬於處方藥，禁忌與副作用需醫生評估。",
    "q.m09#13.p" to "乙醯唑胺常見的副作用包括？",
    "q.m09#13.o0" to "手腳麻刺感、味覺改變（尤其對碳酸飲料）、多尿",
    "q.m09#13.o1" to "嗜睡",
    "q.m09#13.o2" to "心跳加快",
    "q.m09#13.o3" to "血壓升高",
    "q.m09#13.e" to "這些副作用通常可耐受，但會影響飲水與睡眠。磺胺過敏者禁用。",
    "q.m09#14.p" to "地塞米松用於 HACE 的常用劑量是？",
    "q.m09#14.o0" to "4 mg，每 6 小時",
    "q.m09#14.o1" to "1 mg，每日一次",
    "q.m09#14.o2" to "20 mg，每 12 小時",
    "q.m09#14.o3" to "按需一次",
    "q.m09#14.e" to "4 mg 每 6 小時是技能書口徑。它是治療用藥，不能替代下降。",
    "q.m09#15.p" to "硝苯地平主要用於？",
    "q.m09#15.o0" to "HAPE 的預防與治療",
    "q.m09#15.o1" to "AMS",
    "q.m09#15.o2" to "凍傷",
    "q.m09#15.o3" to "脫水",
    "q.m09#15.e" to "硝苯地平透過降低肺血管阻力起作用，常用 20–30 mg 每 12 小時。它不治療 AMS。",
    "q.m09#16.p" to "服用地塞米松後症狀明顯緩解，此時最正確的做法是？",
    "q.m09#16.o0" to "仍然下降——藥物只是爭取時間",
    "q.m09#16.o1" to "取消下撤",
    "q.m09#16.o2" to "繼續上升",
    "q.m09#16.o3" to "停藥觀察",
    "q.m09#16.e" to "激素掩蓋症狀，病程仍在進展。症狀緩解後繼續上升是最危險的誤判。",
    "q.m09#17.p" to "為什麼「帶藥」不等於「會用藥」？",
    "q.m09#17.o0" to "劑量、適應證與禁忌需要醫生判斷，隊友之間不應互相推薦",
    "q.m09#17.o1" to "因為藥會過期",
    "q.m09#17.o2" to "因為藥太重",
    "q.m09#17.o3" to "因為說明書難懂",
    "q.m09#17.e" to "高原用藥的坑很多：磺胺過敏、哮喘、合併用藥。沒有評估就吃藥，風險可能大於收益。",
    "q.m09#18.p" to "阿司匹林在高原的作用是？",
    "q.m09#18.o0" to "緩解頭痛，屬於對症處理，不改變病程",
    "q.m09#18.o1" to "預防 HAPE",
    "q.m09#18.o2" to "治療 HACE",
    "q.m09#18.o3" to "提高血氧",
    "q.m09#18.e" to "對症處理的定位要清楚：它讓你舒服一點，但不代表可以繼續上升。",
    "q.m09#19.p" to "「什麼藥都不吃、儘快下降」在什麼情況下是最穩的選擇？",
    "q.m09#19.o0" to "症狀重、無法判斷病因，或沒有醫生指導時",
    "q.m09#19.o1" to "任何時候",
    "q.m09#19.o2" to "只有輕症",
    "q.m09#19.o3" to "只有下撤方便時",
    "q.m09#19.e" to "下降是唯一確定有效的措施。當藥物變成「靠猜」時，下降永遠是更安全的那條路。",
    "q.l11#12.p" to "兩個保護點夾角為 0°（完全平行）時，每個點大致承擔多少負荷？",
    "q.l11#12.o0" to "各 50%",
    "q.l11#12.o1" to "各 71%",
    "q.l11#12.o2" to "各 100%",
    "q.l11#12.o3" to "各 25%",
    "q.l11#12.e" to "夾角越小，負荷越接近均分。這就是「扁帶夾角控制在 60° 以內」的由來。",
    "q.l11#13.p" to "夾角 60° 時，每個點承擔的負荷約為？",
    "q.l11#13.o0" to "58%",
    "q.l11#13.o1" to "50%",
    "q.l11#13.o2" to "71%",
    "q.l11#13.o3" to "100%",
    "q.l11#13.e" to "從 0° 的 50% 到 60° 的 58% 再到 90° 的 71%，負荷隨角度快速上升。",
    "q.l11#14.p" to "為什麼確保站要「預先收緊」？",
    "q.l11#14.o0" to "某一節點失效時不產生衝擊性延展，其餘點仍在原位",
    "q.l11#14.o1" to "為了好看",
    "q.l11#14.o2" to "為了省繩",
    "q.l11#14.o3" to "為了方便拆",
    "q.l11#14.e" to "鬆弛的系統在受力瞬間會產生衝擊載荷，遠大於靜載。No Extension 講的就是這件事。",
    "q.l11#15.p" to "三個保護點比兩個更好，前提是？",
    "q.l11#15.o0" to "三個點彼此獨立、失效原因不同，並且受力均衡",
    "q.l11#15.o1" to "數量越多越好",
    "q.l11#15.o2" to "只要掛上就行",
    "q.l11#15.o3" to "用一根扁帶串起來",
    "q.l11#15.e" to "用一條扁帶把三個點串成鏈，仍然是一次失效拖垮全部。數量不等於冗餘。",
    "q.l11#16.p" to "主鎖在確保站裡的受力方向應該？",
    "q.l11#16.o0" to "沿主鎖長軸受力，避免橫向拉扯鎖門",
    "q.l11#16.o1" to "橫向受力",
    "q.l11#16.o2" to "任意方向",
    "q.l11#16.o3" to "只掛鎖門一側",
    "q.l11#16.e" to "主鎖的強度標稱是沿長軸的。橫拉時強度可能只剩三分之一，鎖門被頂開的風險也更高。",
    "q.l11#17.p" to "天然保護點（大樹、岩柱）最需要確認的是？",
    "q.l11#17.o0" to "整體穩固性與根部狀況，而不是「看起來粗」",
    "q.l11#17.o1" to "樹皮顏色",
    "q.l11#17.o2" to "高度",
    "q.l11#17.o3" to "位置是否好看",
    "q.l11#17.e" to "枯根、空心、凍融鬆動的岩柱，外觀可能完全正常。用鎬柄敲擊聽聲音是常用檢查。",
    "q.l11#18.p" to "雪地保護點（雪錐、埋雪錨）可靠性主要取決於？",
    "q.l11#18.o0" to "雪層強度、埋設質量與溫度變化",
    "q.l11#18.o1" to "繩子顏色",
    "q.l11#18.o2" to "埋得多深",
    "q.l11#18.o3" to "雪錐品牌",
    "q.l11#18.e" to "化雪時整段可能失效，這也是「午後不要在雪錨系統上停留」的原因。",
    "q.l11#19.p" to "確保站搭得慢，會帶來什麼實際風險？",
    "q.l11#19.o0" to "暴露時間變長，落石、天氣與失溫風險同步上升",
    "q.l11#19.o1" to "沒有風險",
    "q.l11#19.o2" to "只是效率問題",
    "q.l11#19.o3" to "影響心情",
    "q.l11#19.e" to "確保站是「暴露位置」。練熟流程不只為了快，而是為了縮短待在危險裡的時間。",
    "q.l12#12.p" to "透過裂縫密集區時，正確的人員組織是？",
    "q.l12#12.o0" to "逐個透過，一次只讓一個人在風險段上",
    "q.l12#12.o1" to "全隊並排",
    "q.l12#12.o2" to "一起快速透過",
    "q.l12#12.o3" to "兩人一組並肩",
    "q.l12#12.e" to "「一次一個人」把系統載荷降到最低，也讓制動與救援有反應空間。",
    "q.l12#13.p" to "繩上打結的間距通常是？",
    "q.l12#13.o0" to "每 2–3 公尺一個",
    "q.l12#13.o1" to "每 20 公尺一個",
    "q.l12#13.o2" to "只在兩端打",
    "q.l12#13.o3" to "不需要打",
    "q.l12#13.e" to "密集的繩結能在墜落時增加摩擦與卡點，減少墜入深度。代價是抽繩稍麻煩。",
    "q.l12#14.p" to "隊友墜入裂縫、自己正在制動，身體應該保持什麼姿勢？",
    "q.l12#14.o0" to "俯臥、壓低重心、鎬壓入雪面",
    "q.l12#14.o1" to "站立",
    "q.l12#14.o2" to "坐姿",
    "q.l12#14.o3" to "仰臥",
    "q.l12#14.e" to "俯臥能把體重轉成摩擦，鎬壓入雪面提供額外支點。站立會被直接拽倒。",
    "q.l12#15.p" to "Z 系統（3:1）救援中最關鍵的器材組合是？",
    "q.l12#15.o0" to "抓結 + 滑輪（或主鎖）+ 備用抓結",
    "q.l12#15.o1" to "兩把冰鎬",
    "q.l12#15.o2" to "上升器 + 繩梯",
    "q.l12#15.o3" to "雪鏟 + 探杆",
    "q.l12#15.e" to "3:1 靠「滑輪組 + 單向抓結」實現。沒有抓結，拉上來的繩會立刻被拉回去。",
    "q.l12#16.p" to "墜落者被拉住後，第一步應該做的是？",
    "q.l12#16.o0" to "確認其意識與傷情，並讓他建立自我固定（抓結或冰鎬）",
    "q.l12#16.o1" to "立刻開始拉昇",
    "q.l12#16.o2" to "讓他自己爬",
    "q.l12#16.o3" to "松繩",
    "q.l12#16.e" to "先讓墜落者「不再依賴繩子」，救援者才能騰出手建系統。拉昇是下一步。",
    "q.l12#17.p" to "冰裂縫救援為什麼強調「通訊」？",
    "q.l12#17.o0" to "繩子長度與噪聲會讓對話失效，需要事先約定拉繩訊號",
    "q.l12#17.o1" to "因為要聊天",
    "q.l12#17.o2" to "因為對講機貴",
    "q.l12#17.o3" to "因為隊友會怕",
    "q.l12#17.e" to "常見的約定是一拉「停」、兩拉「拉」、三拉「放」。事先說好，現場才不亂。",
    "q.l12#18.p" to "裂縫區行進時，繩子應該保持什麼狀態？",
    "q.l12#18.o0" to "適度張緊，不拖地也不過鬆",
    "q.l12#18.o1" to "完全拖地",
    "q.l12#18.o2" to "繃得筆直",
    "q.l12#18.o3" to "捲起來",
    "q.l12#18.e" to "拖地會被齒或岩石勾住，繃緊則會互相牽扯。適度張力是「能立刻制動」的前提。",
    "q.l12#19.p" to "冰川末端與冰瀑區，為什麼通常安排在清晨透過？",
    "q.l12#19.o0" to "低溫使雪橋與冰體更穩定，落冰也相對少",
    "q.l12#19.o1" to "因為人少",
    "q.l12#19.o2" to "因為不曬",
    "q.l12#19.o3" to "因為嚮導習慣",
    "q.l12#19.e" to "溫度是穩定性的關鍵變數。午後融水與落冰都會顯著增加風險。",
    "q.l18#13.p" to "為什麼「背風坡」更容易形成危險雪層？",
    "q.l18#13.o0" to "風把雪搬運到背風側堆積成雪簷與軟硬夾層",
    "q.l18#13.o1" to "因為更冷",
    "q.l18#13.o2" to "因為雪更溼",
    "q.l18#13.o3" to "因為人少",
    "q.l18#13.e" to "風輸運會在背風坡形成「軟雪壓硬層」的結構，一旦觸發往往整片滑動。",
    "q.l18#14.p" to "雪崩危險等級 1–5 中，5 級意味著？",
    "q.l18#14.o0" to "極端危險，自然雪崩廣泛發生，應避免進入雪崩地形",
    "q.l18#14.o1" to "輕微危險",
    "q.l18#14.o2" to "中等危險",
    "q.l18#14.o3" to "無法判斷",
    "q.l18#14.e" to "等級是「可能性 + 規模」的綜合。5 級不是「更難登」，而是「不該去」。",
    "q.l18#15.p" to "出發前讀雪崩簡報（bulletin），最該關注的三項是？",
    "q.l18#15.o0" to "危險等級、問題型別（如風板/溼雪）、危險坡向與高度帶",
    "q.l18#15.o1" to "溫度、溼度、氣壓",
    "q.l18#15.o2" to "風速、雲量、能見度",
    "q.l18#15.o3" to "路線長度、爬升、耗時",
    "q.l18#15.e" to "簡報的核心資訊是「哪裡、什麼問題、多容易觸發」。只記等級不記坡向，等於沒用。",
    "q.l18#16.p" to "多人透過雪崩地形時，正確做法是？",
    "q.l18#16.o0" to "一人一次透過，其他人待在安全點觀察",
    "q.l18#16.o1" to "全隊一起透過",
    "q.l18#16.o2" to "並排透過",
    "q.l18#16.o3" to "快速跑過",
    "q.l18#16.e" to "一次一個人，是把「可能被埋的人數」降到最低。全隊一起透過是事故放大的典型方式。",
    "q.l18#17.p" to "雪崩三件套的正確使用順序是？",
    "q.l18#17.o0" to "信標搜尋 → 探杆定位 → 雪鏟挖掘",
    "q.l18#17.o1" to "先挖 → 再探 → 再搜",
    "q.l18#17.o2" to "三件同時用",
    "q.l18#17.o3" to "先探 → 再搜 → 再挖",
    "q.l18#17.e" to "順序錯了會浪費最寶貴的幾分鐘。搜尋階段的目標是「找到」，挖掘是「夠到」。",
    "q.l18#18.p" to "春季溼雪崩與冬季幹雪崩的主要差別是？",
    "q.l18#18.o0" to "溼雪崩更慢但密度大、衝擊力強，常在午後發生",
    "q.l18#18.o1" to "溼雪崩更快",
    "q.l18#18.o2" to "溼雪崩不會埋人",
    "q.l18#18.o3" to "沒有差別",
    "q.l18#18.e" to "溼雪崩的觸發常與融水、日照有關，時間窗口集中在午後。行程安排要避開這個時段。",
    "q.l18#19.p" to "雪層測試（如挖雪坑觀察層結）的價值與侷限是？",
    "q.l18#19.o0" to "能提供局地資訊，但不能代表整面坡",
    "q.l18#19.o1" to "可以完全預測雪崩",
    "q.l18#19.o2" to "沒有價值",
    "q.l18#19.o3" to "只在春季有用",
    "q.l18#19.e" to "雪坑是「一個點」的資訊。地形、坡向、風的影響範圍遠大於一個坑。",
    "q.m10#12.p" to "相對溼度接近飽和時，最直接的天氣含義是？",
    "q.m10#12.o0" to "雲底降低、容易起霧與降水",
    "q.m10#12.o1" to "氣溫升高",
    "q.m10#12.o2" to "風力減弱",
    "q.m10#12.o3" to "氣壓升高",
    "q.m10#12.e" to "飽和意味著水汽開始凝結。登山時「雲底快速下降」往往比「開始下雨」更早出現。",
    "q.m10#13.p" to "冷鋒過境後，通常會出現？",
    "q.m10#13.o0" to "氣溫下降、風向轉變、能見度轉好",
    "q.m10#13.o1" to "氣溫上升",
    "q.m10#13.o2" to "持續降雨",
    "q.m10#13.o3" to "風力減弱",
    "q.m10#13.e" to "鋒後往往是「好天氣但很冷、風大」。這也是很多隊伍在「天氣轉好」時低估風寒的原因。",
    "q.m10#14.p" to "地形雲（貼在山腰的雲）對攀登的意義是？",
    "q.m10#14.o0" to "提示強風與高溼度，山脊可能已經無法通行",
    "q.m10#14.o1" to "只是好看",
    "q.m10#14.o2" to "說明天氣穩定",
    "q.m10#14.o3" to "與風無關",
    "q.m10#14.e" to "地形雲是「風與溼」的視覺化。看到雲被吹得快速移動，基本可以判斷山脊風力超限。",
    "q.m10#15.p" to "為什麼預報的「時效」越長越不可靠？",
    "q.m10#15.o0" to "大氣是混沌系統，誤差會隨時間指數放大",
    "q.m10#15.o1" to "因為模型太差",
    "q.m10#15.o2" to "因為資料不全",
    "q.m10#15.o3" to "因為海拔高",
    "q.m10#15.e" to "3 天內的趨勢較可信，7 天以上只能當參考。行程要留出「等窗口」的時間。",
    "q.m10#16.p" to "山區氣象站的資料與你要去的海拔，差別主要來自？",
    "q.m10#16.o0" to "海拔差帶來的氣溫、風速與降水形式差異",
    "q.m10#16.o1" to "儀器誤差",
    "q.m10#16.o2" to "時區",
    "q.m10#16.o3" to "緯度",
    "q.m10#16.e" to "山谷站點的「小雨」在 5,000 公尺可能是「大雪 + 大風」。讀預報必須換算高度。",
    "q.m10#17.p" to "看到閃電後 30 秒內聽到雷聲，說明？",
    "q.m10#17.o0" to "雷暴已經很近，應立即離開暴露地形",
    "q.m10#17.o1" to "雷暴很遠",
    "q.m10#17.o2" to "安全",
    "q.m10#17.o3" to "只是巧合",
    "q.m10#17.e" to "光速與聲速的差可以估算距離。間隔越短越近，「30 秒」是常用的行動閾值。",
    "q.m10#18.p" to "為什麼衝頂常安排在凌晨？",
    "q.m10#18.o0" to "雪面凍結更穩、午後雲與風通常更強",
    "q.m10#18.o1" to "因為要拍照",
    "q.m10#18.o2" to "因為人少",
    "q.m10#18.o3" to "因為嚮導習慣",
    "q.m10#18.e" to "凌晨的硬雪與穩定天氣窗口是主要理由。代價是低溫與睡眠不足，需要提前準備。",
    "q.m10#19.p" to "天氣窗口變窄時，最先應該放棄的是什麼？",
    "q.m10#19.o0" to "登頂目標，而不是安全餘量",
    "q.m10#19.o1" to "保暖層",
    "q.m10#19.o2" to "備份裝備",
    "q.m10#19.o3" to "通訊裝置",
    "q.m10#19.e" to "窗口不足時，壓縮的往往是「餘量」——這正是事故的開始。正確的取捨是先放棄目標。",
    "q.m11#12.p" to "玉珠峰南坡為什麼適合作為 6000 公尺級第一站？",
    "q.m11#12.o0" to "雪坡相對平緩、交通可達、路線成熟",
    "q.m11#12.o1" to "因為最高",
    "q.m11#12.o2" to "因為技術最難",
    "q.m11#12.o3" to "因為人少",
    "q.m11#12.e" to "「第一座 6000」的目標是驗證適應與體力，不是挑戰技術。路線成熟能降低未知。",
    "q.m11#13.p" to "啟孜峰所在的山脈是？",
    "q.m11#13.o0" to "念青唐古拉山脈",
    "q.m11#13.o1" to "崑崙山脈",
    "q.m11#13.o2" to "喜馬拉雅山脈",
    "q.m11#13.o3" to "喀喇崑崙山脈",
    "q.m11#13.e" to "啟孜在西藏當雄，屬念青唐古拉。山脈決定氣候與季節窗口，是選峰的重要背景。",
    "q.m11#14.p" to "羅布切東峰最典型的用途是？",
    "q.m11#14.o0" to "作為 6000 公尺級與 8000 公尺之間的過渡與技術訓練",
    "q.m11#14.o1" to "作為旅遊線路",
    "q.m11#14.o2" to "作為滑雪場",
    "q.m11#14.o3" to "作為觀景臺",
    "q.m11#14.e" to "它就在珠峰徒步路線旁，雪坡較陡、交通方便，是常見的過渡峰。",
    "q.m11#15.p" to "島峰（Imja Tse）的技術特徵是？",
    "q.m11#15.o0" to "需要結組與冰裂縫行進，是經典的技術型 6000 公尺",
    "q.m11#15.o1" to "純徒步",
    "q.m11#15.o2" to "只需雪坡行走",
    "q.m11#15.o3" to "全年無雪",
    "q.m11#15.e" to "島峰的「技術」主要體現在冰川與裂縫，而不是岩壁。結組與裂縫救援是必備能力。",
    "q.m11#16.p" to "6000 公尺級選峰時，比海拔更值得關注的是？",
    "q.m11#16.o0" to "路線形態（雪坡/冰川/岩壁）與撤退難度",
    "q.m11#16.o1" to "名字好不好聽",
    "q.m11#16.o2" to "距離遠近",
    "q.m11#16.o3" to "費用高低",
    "q.m11#16.e" to "同樣是 6,100 公尺，雪坡與冰川路線的要求差一個量級。先看形態，再看海拔。",
    "q.m11#17.p" to "6000 公尺級的許可與嚮導要求，通常比 5,000 公尺級？",
    "q.m11#17.o0" to "更嚴格，多需備案或強制嚮導",
    "q.m11#17.o1" to "更寬鬆",
    "q.m11#17.o2" to "完全相同",
    "q.m11#17.o3" to "沒有要求",
    "q.m11#17.e" to "海拔越高、路線越偏，管理越嚴。出發前確認規定，比到山腳再問省事得多。",
    "q.m11#18.p" to "為什麼 6000 公尺級要「假設冰裂縫存在」？",
    "q.m11#18.o0" to "雪橋覆蓋後無法目視判斷，必須按有裂縫來結組",
    "q.m11#18.o1" to "因為裂縫一定存在",
    "q.m11#18.o2" to "因為嚮導要求",
    "q.m11#18.o3" to "因為保險規定",
    "q.m11#18.e" to "「看不見」不等於「沒有」。結組的成本很低，墜落裂縫的代價很高。",
    "q.m11#19.p" to "6000 公尺級的適應安排，通常比 5,000 公尺級？",
    "q.m11#19.o0" to "更長，因為睡眠海拔更高、恢復更慢",
    "q.m11#19.o1" to "更短",
    "q.m11#19.o2" to "相同",
    "q.m11#19.o3" to "不需要",
    "q.m11#19.e" to "海拔每上一個臺階，適應時間都要增加。把 5,000 公尺的節奏直接搬到 6,000 公尺，是常見的低估。",
    "q.l43#0.p" to "高海拔皮膚問題的三個主要來源是？",
    "q.l43#0.o0" to "乾燥、紫外線、風",
    "q.l43#0.o1" to "寒冷、潮溼、摩擦",
    "q.l43#0.o2" to "缺氧、低壓、低溫",
    "q.l43#0.o3" to "飲食、睡眠、壓力",
    "q.l43#0.e" to "這三件事同時作用，皮膚屏障很快就破。保溼與防曬不是「講究」，是維持工作能力。",
    "q.l43#1.p" to "暖貼的正確用法是？",
    "q.l43#1.o0" to "貼在後腰、腹部或靴子外側，不直接貼皮膚",
    "q.l43#1.o1" to "直接貼皮膚",
    "q.l43#1.o2" to "貼在額頭",
    "q.l43#1.o3" to "睡覺時貼滿全身",
    "q.l43#1.e" to "直接貼皮膚可能低溫燙傷，而低溫燙傷在高海拔癒合很慢。它防的是核心溫度下降。",
    "q.l43#2.p" to "洗碗水的正確處理是？",
    "q.l43#2.o0" to "濾掉殘渣後分散潑灑，殘渣帶走",
    "q.l43#2.o1" to "倒進溪流",
    "q.l43#2.o2" to "倒在帳篷邊",
    "q.l43#2.o3" to "倒進廁所坑",
    "q.l43#2.e" to "殘渣是汙染與動物誘因。濾出帶走、水分散潑灑，是低影響的做法。",
    "q.l43#3.p" to "為什麼貼身層要優先清洗？",
    "q.l43#3.o0" to "汗鹽會磨破皮膚，而破皮在高海拔很難癒合",
    "q.l43#3.o1" to "因為好看",
    "q.l43#3.o2" to "因為輕",
    "q.l43#3.o3" to "因為便宜",
    "q.l43#3.e" to "貼身層的鹽分與細菌會持續刺激皮膚。一處破皮在乾燥與低溫下可能幾周不愈。",
    "q.l43#4.p" to "羽絨服髒了或溼了，正確做法是？",
    "q.l43#4.o0" to "不洗，抖掉浮雪後晾乾",
    "q.l43#4.o1" to "用洗衣粉搓洗",
    "q.l43#4.o2" to "擰乾",
    "q.l43#4.o3" to "用火烤乾",
    "q.l43#4.e" to "羽絨清洗後很難在野外恢復蓬鬆。溼了只晾，別烤——烤會損傷面料與羽絨。",
    "q.l43#5.p" to "營地秩序三條不包括？",
    "q.l43#5.o0" to "把食物放進帳篷過夜",
    "q.l43#5.o1" to "鞋放門廳",
    "q.l43#5.o2" to "食物不進帳篷",
    "q.l43#5.o3" to "垃圾集中掛高",
    "q.l43#5.e" to "食物進帳篷會把動物直接引到睡眠區，也讓氣味長期留在睡袋上。這三條同時防潮、防動物、防汙染。",
    "q.l43#6.p" to "高海拔護唇為什麼重要？",
    "q.l43#6.o0" to "嘴唇沒有黑色素保護，乾裂後進食與說話都會疼",
    "q.l43#6.o1" to "因為好看",
    "q.l43#6.o2" to "因為會被曬黑",
    "q.l43#6.o3" to "因為會腫",
    "q.l43#6.e" to "唇部是最容易忽略的防曬部位，也是「疼起來影響進食」的部位。護唇膏要隨身。",
    "q.l43#7.p" to "個人護理時間應該怎麼安排？",
    "q.l43#7.o0" to "固定成每天的短流程（早晚各幾分鐘），而不是有空才做",
    "q.l43#7.o1" to "等有太陽再做",
    "q.l43#7.o2" to "一週一次",
    "q.l43#7.o3" to "看心情",
    "q.l43#7.e" to "護理的價值來自「持續」。固定流程能在疲勞時也執行，靠意志臨場決定通常會跳過。",
    "q.l43#8.p" to "營地生活需要「一人一套、標記姓名」的物品包括？",
    "q.l43#8.o0" to "餐具",
    "q.l43#8.o1" to "洗漱用品",
    "q.l43#8.o2" to "水杯",
    "q.l43#8.o3" to "帳篷",
    "q.l43#8.e" to "前三項是入口與皮膚接觸的物品，混用會傳播腸道與皮膚問題。帳篷按人分配，不必標名。",
    "q.l43#9.p" to "高海拔每天要做的護理動作包括？",
    "q.l43#9.o0" to "塗防曬（含唇部）",
    "q.l43#9.o1" to "保溼",
    "q.l43#9.o2" to "換幹襪、晾鞋",
    "q.l43#9.o3" to "每天洗澡",
    "q.l43#9.e" to "前三條直接關係到皮膚與腳的狀態。每天洗澡在高海拔既不現實也沒必要，區域性清潔即可。",
    "q.l43#10.p" to "暖貼使用要避免的情況包括？",
    "q.l43#10.o0" to "直接貼皮膚",
    "q.l43#10.o1" to "睡覺時長時間貼同一處",
    "q.l43#10.o2" to "貼在已經凍傷的部位",
    "q.l43#10.o3" to "貼在後腰",
    "q.l43#10.e" to "前三條都可能造成低溫燙傷，或在感覺遲鈍時加重損傷。後腰是常用位置。",
    "q.l43#11.p" to "把到達營地後的生活流程排好。",
    "q.l43#11.o0" to "先換下溼的貼身層並加保暖層",
    "q.l43#11.o1" to "搭帳、鋪睡墊、晾鞋襪",
    "q.l43#11.o2" to "燒水、進食、補水",
    "q.l43#11.o3" to "固定護理流程（防曬/保溼/護唇/處理破皮）",
    "q.l43#11.e" to "順序的核心是「先止住熱量流失」。先做飯後換衣，是最常見的錯誤。",
    "q.l43#12.p" to "暖貼應貼在後腰、腹部或靴子外側，不要直接貼 ______。",
    "q.l43#12.a0" to "皮膚",
    "q.l43#12.a1" to "身體",
    "q.l43#12.e" to "直接貼皮膚可能低溫燙傷，而燙傷在高海拔極難癒合。",
    "q.l43#13.p" to "營地秩序要求食物不進 ______。",
    "q.l43#13.a0" to "帳篷",
    "q.l43#13.a1" to "睡帳",
    "q.l43#13.e" to "食物氣味會把動物引到睡眠區，也會長期留在睡袋與衣物上。",
    "q.l43#14.p" to "把護理動作與它防的問題對應起來。",
    "q.l43#14.l0" to "防曬與護唇",
    "q.l43#14.l1" to "保溼",
    "q.l43#14.l2" to "換幹襪",
    "q.l43#14.l3" to "暖貼",
    "q.l43#14.r0" to "紫外線灼傷（含雪盲風險）",
    "q.l43#14.r1" to "皮膚乾裂、屏障受損",
    "q.l43#14.r2" to "水泡與浸漬",
    "q.l43#14.r3" to "核心溫度下降",
    "q.l43#14.e" to "四個動作對應四類問題。它們都不難，難的是每天堅持做。",
    "q.l43#15.p" to "高海拔洗衣服，最現實的做法是？",
    "q.l43#15.o0" to "只洗貼身層，用少量洗滌劑漂淨，掛在帳篷內晾",
    "q.l43#15.o1" to "全洗一遍",
    "q.l43#15.o2" to "不洗",
    "q.l43#15.o3" to "用雪搓",
    "q.l43#15.e" to "水與燃料都寶貴。貼身層是唯一必須洗的，其餘靠晾曬與拍打。",
    "q.l43#16.p" to "防曬霜在高海拔的補塗頻率建議是？",
    "q.l43#16.o0" to "每 2–3 小時一次，出汗或融雪後補塗",
    "q.l43#16.o1" to "早上一次",
    "q.l43#16.o2" to "每天一次",
    "q.l43#16.o3" to "不補",
    "q.l43#16.e" to "紫外線強、風大、雪面反射，防曬膜很快失效。補塗比選高倍數更重要。",
    "q.l43#17.p" to "營地夜間外出，最容易忽略的是？",
    "q.l43#17.o0" to "穿鞋或營地鞋，不要只穿襪子踩雪",
    "q.l43#17.o1" to "帶相機",
    "q.l43#17.o2" to "帶水",
    "q.l43#17.o3" to "戴帽子",
    "q.l43#17.e" to "襪子溼了會整夜冰涼，也增加凍傷與失溫風險。營地鞋是最簡單有效的裝備。",
    "q.l43#18.p" to "溼巾、紙巾這類消耗品應該怎麼規劃？",
    "q.l43#18.o0" to "按天分裝並留一份備用，避免受潮",
    "q.l43#18.o1" to "整包帶",
    "q.l43#18.o2" to "多帶",
    "q.l43#18.o3" to "不帶",
    "q.l43#18.e" to "整包容易受潮也佔空間。按天分裝能控制用量，也能在溼了之後還有備份。",
    "q.l43#19.p" to "個人護理用品中最該「帶雙份」的是？",
    "q.l43#19.o0" to "護唇膏與防曬",
    "q.l43#19.o1" to "洗髮水",
    "q.l43#19.o2" to "香水",
    "q.l43#19.o3" to "剃鬚刀",
    "q.l43#19.e" to "這兩樣體積小、丟失後無法替代，而且直接影響進食與皮膚屏障。",
    "q.l17#14.p" to "判斷冰況時，「爛冰」（dinner-plating）指的是？",
    "q.l17#14.o0" to "冰面呈片狀剝離，鎬一敲就大片脫落",
    "q.l17#14.o1" to "冰很硬",
    "q.l17#14.o2" to "冰裡有氣泡",
    "q.l17#14.o3" to "冰面結霜",
    "q.l17#14.e" to "爛冰說明冰體結構差，鎬與冰錐都難以可靠咬合。遇到大面積爛冰應改線或下撤。",
    "q.l17#15.p" to "流水冰與黑冰，哪個更適合攀爬？",
    "q.l17#15.o0" to "黑冰（緻密、無氣泡）強度高、冰錐可靠",
    "q.l17#15.o1" to "流水冰更穩",
    "q.l17#15.o2" to "兩者一樣",
    "q.l17#15.o3" to "都不適合",
    "q.l17#15.e" to "緻密透明冰強度高、冰錐咬合好；流水冰與蜂窩冰內部空腔多，保護可靠性大幅下降。",
    "q.l17#16.p" to "打冰錐時，錐體通常應該？",
    "q.l17#16.o0" to "略向上傾斜（約 10°），手柄朝下便於掛鎖",
    "q.l17#16.o1" to "完全水平",
    "q.l17#16.o2" to "向下傾斜",
    "q.l17#16.o3" to "任意角度",
    "q.l17#16.e" to "略向上能順著受力方向，減少拔出風險。手柄朝下方便掛鎖，也減少繩索被頂開的可能。",
    "q.l17#17.p" to "冰錐的最佳長度取決於？",
    "q.l17#17.o0" to "冰質：硬冰用短錐，軟冰/爛冰用長錐",
    "q.l17#17.o1" to "越短越好",
    "q.l17#17.o2" to "越長越好",
    "q.l17#17.o3" to "與冰質無關",
    "q.l17#17.e" to "短錐在軟冰裡咬不住，長錐在硬冰裡打入困難且耗時。選錐是「按冰質」而不是「按習慣」。",
    "q.l17#18.p" to "攀冰確保站通常需要？",
    "q.l17#18.o0" to "至少兩個可靠冰錐，並用扁帶或繩連線均衡",
    "q.l17#18.o1" to "一個冰錐就夠",
    "q.l17#18.o2" to "三個冰錐串在一條扁帶上",
    "q.l17#18.o3" to "只用岩塞",
    "q.l17#18.e" to "「兩個獨立點 + 均衡」是底線。單個冰錐失效時，系統會整體失效。",
    "q.l17#19.p" to "冰壁上「找休息位」的技巧是？",
    "q.l17#19.o0" to "把重心壓到直腿、用鎬掛住，讓手臂輪流放鬆",
    "q.l17#19.o1" to "一直用雙臂掛住",
    "q.l17#19.o2" to "坐下來",
    "q.l17#19.o3" to "鬆開雙腳",
    "q.l17#19.e" to "攀冰的瓶頸是前臂泵感。會休息的人能多爬幾十公尺，不會休息的人在第一個難點就力竭。",
    "q.l17#20.p" to "為什麼攀冰時護目鏡/眼鏡很重要？",
    "q.l17#20.o0" to "落冰與碎屑會持續打在臉上",
    "q.l17#20.o1" to "為了好看",
    "q.l17#20.o2" to "為了防紫外線",
    "q.l17#20.o3" to "為了防霧",
    "q.l17#20.e" to "揮鎬時碎冰會往下掉，跟攀者與保護者都在「落冰區」裡。護目是低成本的必要裝備。",
    "q.l17#21.p" to "落冰時，保護者應該？",
    "q.l17#21.o0" to "貼壁站立、儘量靠近岩壁下方，並提前觀察落冰路徑",
    "q.l17#21.o1" to "站遠一點",
    "q.l17#21.o2" to "抬頭看",
    "q.l17#21.o3" to "用手擋",
    "q.l17#21.e" to "冰壁下方是「漏斗」。貼壁往往比遠離更安全，因為落冰有拋物線。",
    "q.l17#22.p" to "攀冰下撤常用「阿巴拉克夫冰洞（v-thread）」，它的優點是？",
    "q.l17#22.o0" to "不需要留下裝備，抽繩即可回收",
    "q.l17#22.o1" to "最快",
    "q.l17#22.o2" to "最安全",
    "q.l17#22.o3" to "不需要冰錐",
    "q.l17#22.e" to "兩個相交的冰洞穿繩打結，下降後抽繩回收。它減少了器材損失，但需要正確的角度與長度。",
    "q.l17#23.p" to "冰況在一天內的變化，最明顯的驅動因素是？",
    "q.l17#23.o0" to "日照與氣溫：向陽面午後變軟、陰面保持硬",
    "q.l17#23.o1" to "風速",
    "q.l17#23.o2" to "氣壓",
    "q.l17#23.o3" to "溼度",
    "q.l17#23.e" to "同一面冰壁，上午與下午可能是兩種難度。行程安排要考慮「這面牆什麼時候最穩」。",
    "q.l17#24.p" to "攀冰時的腳法，前齒踢入應該？",
    "q.l17#24.o0" to "屈膝抬腳、前齒垂直踢入，落點分散",
    "q.l17#24.o1" to "腳尖平貼冰面",
    "q.l17#24.o2" to "用腳跟踩",
    "q.l17#24.o3" to "連續快速點踢",
    "q.l17#24.e" to "垂直入冰才能咬住。落點分散能避免把同一塊冰踢碎，也減少「冰面被踢爛」的風險。",
    "q.l17#25.p" to "雙臂「泵感」嚴重時，最不該做的是？",
    "q.l17#25.o0" to "繼續硬上到下一個保護點",
    "q.l17#25.o1" to "找位置休息",
    "q.l17#25.o2" to "甩手放鬆",
    "q.l17#25.o3" to "換用更省力的姿勢",
    "q.l17#25.e" to "泵感是前臂血流不足的訊號。硬上會導致「抓不住鎬」——這是攀冰墜落最常見的原因。",
    "q.l17#26.p" to "冰錐被打入後，為什麼不宜反覆拔出重打？",
    "q.l17#26.o0" to "孔洞會擴大、冰體結構受損，二次咬合力下降",
    "q.l17#26.o1" to "因為麻煩",
    "q.l17#26.o2" to "因為會凍住",
    "q.l17#26.o3" to "因為會彎",
    "q.l17#26.e" to "同一個孔重打，錐體可能直接鬆動。選點前先想清楚，比反覆試更省時間也更安全。",
    "q.l17#27.p" to "攀冰與攀岩在保護上的主要差別是？",
    "q.l17#27.o0" to "保護點強度更依賴介質（冰）的狀態，且會隨時間變化",
    "q.l17#27.o1" to "攀冰不需要保護",
    "q.l17#27.o2" to "攀冰只用頂繩",
    "q.l17#27.o3" to "沒有差別",
    "q.l17#27.e" to "岩塞與螺栓的強度相對穩定，冰錐的可靠性會隨溫度與時間變化。這是攀冰判斷更難的根本原因。",
    "q.m12#16.p" to "3:1 系統的理論機械優勢是？",
    "q.m12#16.o0" to "拉動 1 公尺繩子，負載上升約 1/3 公尺",
    "q.m12#16.o1" to "負載減為 1/2",
    "q.m12#16.o2" to "速度不變",
    "q.m12#16.o3" to "不需要抓結",
    "q.m12#16.e" to "機械優勢 = 承重繩段數。3:1 意味著出力約為負載的三分之一（不計摩擦）。",
    "q.m12#17.p" to "實際救援中，5:1 系統的效率通常？",
    "q.m12#17.o0" to "低於理論值，因為滑輪與繩的摩擦損耗",
    "q.m12#17.o1" to "高於理論值",
    "q.m12#17.o2" to "完全等於理論值",
    "q.m12#17.o3" to "與摩擦無關",
    "q.m12#17.e" to "每個滑輪都有摩擦損失，實際效率常見只有理論值的六七成。設計時要留餘量。",
    "q.m12#18.p" to "使用主鎖代替滑輪做「轉向點」時，主要代價是？",
    "q.m12#18.o0" to "摩擦顯著增加，效率下降",
    "q.m12#18.o1" to "強度不足",
    "q.m12#18.o2" to "會磨損安全帶",
    "q.m12#18.o3" to "無法鎖定",
    "q.m12#18.e" to "主鎖能轉向但不減少摩擦，拉力的一部分會被摩擦吃掉。有滑輪時應優先用滑輪。",
    "q.m12#19.p" to "救援系統中的「單向抓結」作用是？",
    "q.m12#19.o0" to "拉回後鎖住，防止負載回落",
    "q.m12#19.o1" to "增加強度",
    "q.m12#19.o2" to "減少摩擦",
    "q.m12#19.o3" to "連線兩根繩",
    "q.m12#19.e" to "沒有抓結，每次鬆手負載就滑回去。抓結是「把間歇拉力累積成位移」的關鍵。",
    "q.m12#20.p" to "為什麼救援系統要設「備份抓結」？",
    "q.m12#20.o0" to "主抓結可能打滑或失效，備份是最後一道保險",
    "q.m12#20.o1" to "為了好看",
    "q.m12#20.o2" to "為了增加拉力",
    "q.m12#20.o3" to "為了省繩",
    "q.m12#20.e" to "抓結的可靠性依賴繩徑匹配與狀態。關鍵系統中，雙抓結是常規做法。",
    "q.m12#21.p" to "拖拽傷員時，系統應該儘量？",
    "q.m12#21.o0" to "貼著地形走，避免傷員撞到岩壁或雪簷",
    "q.m12#21.o1" to "拉得越高越好",
    "q.m12#21.o2" to "越快越好",
    "q.m12#21.o3" to "垂直提升",
    "q.m12#21.e" to "拖拽的傷害常來自碰撞而不是拉力。路線規劃與保護點的位置同樣重要。",
    "q.m12#22.p" to "6:1 系統（複合系統）相比 3:1 的代價是？",
    "q.m12#22.o0" to "需要更多器材、設定更慢、繩長消耗更大",
    "q.m12#22.o1" to "更省力但更快",
    "q.m12#22.o2" to "沒有代價",
    "q.m12#22.o3" to "無法回收",
    "q.m12#22.e" to "機械優勢越高，設定越複雜、需要的繩越長。救援中「快」往往比「省力」更重要。",
    "q.m12#23.p" to "系統中途需要「轉換」時，最基本的要求是？",
    "q.m12#23.o0" to "任何時刻至少有一個裝置在承重，且不出現無連線空檔",
    "q.m12#23.o1" to "動作快",
    "q.m12#23.o2" to "兩人配合",
    "q.m12#23.o3" to "用同一根繩",
    "q.m12#23.e" to "轉換是救援事故的高發點。凡是「拆舊建新」，都要先建立新連線。",
    "q.m12#24.p" to "繩索在系統中繞過銳邊時應該？",
    "q.m12#24.o0" to "加護套或改變走向，避免繩皮被切傷",
    "q.m12#24.o1" to "直接繞過",
    "q.m12#24.o2" to "拉緊一點",
    "q.m12#24.o3" to "用扁帶代替",
    "q.m12#24.e" to "受力繩被切傷後強度驟降。護套的成本很低，代價卻可能是一條繩甚至一次墜落。",
    "q.m12#25.p" to "為什麼救援系統的錨點要求比一般確保站更高？",
    "q.m12#25.o0" to "要承受的是靜載 + 動態波動，且往往只有一個系統",
    "q.m12#25.o1" to "因為更重要",
    "q.m12#25.o2" to "因為人多",
    "q.m12#25.o3" to "因為繩長",
    "q.m12#25.e" to "救援時沒有第二個確保站兜底。錨點失效意味著「兩個人一起掉下去」。",
    "q.m12#26.p" to "估算拉昇所需力量時，除了機械優勢還要考慮？",
    "q.m12#26.o0" to "傷員與裝備重量、繩與滑輪的摩擦、地形阻力",
    "q.m12#26.o1" to "天氣",
    "q.m12#26.o2" to "時間",
    "q.m12#26.o3" to "隊友體重",
    "q.m12#26.e" to "「理論拉力」常被低估。加上摩擦與地形，實際需要的力可能是理論值的兩倍。",
    "q.m12#27.p" to "系統搭建完成後，最先應該做的是？",
    "q.m12#27.o0" to "空載試拉一次，確認走向、抓結與錨點都正常",
    "q.m12#27.o1" to "立刻拉人",
    "q.m12#27.o2" to "拍照",
    "q.m12#27.o3" to "收繩",
    "q.m12#27.e" to "空載試拉能發現 80% 的搭建錯誤。這一步花十秒，可能省掉一次系統失效。",
    "q.l32#0.p" to "固定繩按用途分三類，下面哪一組是對的？",
    "q.l32#0.o0" to "扶手繩、短段固定繩、探險修路",
    "q.l32#0.o1" to "單繩、雙繩、對繩",
    "q.l32#0.o2" to "動力繩、靜力繩、輔繩",
    "q.l32#0.o3" to "上段、中段、下段",
    "q.l32#0.e" to "三類對應三種場景與三種標準做法。混淆場景，就會用扶手繩的做法去修一條整季使用的路線。",
    "q.l32#1.p" to "長距離固定繩應該用哪種繩？",
    "q.l32#1.o0" to "靜力繩（低延展）",
    "q.l32#1.o1" to "動力繩",
    "q.l32#1.o2" to "輔繩",
    "q.l32#1.o3" to "扁帶",
    "q.l32#1.e" to "動力繩的延展是為衝墜設計的，用在固定繩上會讓人在繩上「上下彈」，同時磨損更快。",
    "q.l32#2.p" to "固定繩常用的靜力繩直徑範圍是？",
    "q.l32#2.o0" to "9–11 毫米",
    "q.l32#2.o1" to "5–6 毫米",
    "q.l32#2.o2" to "7–8 毫米",
    "q.l32#2.o3" to "12–14 毫米",
    "q.l32#2.e" to "太細耐磨性差、手感滑；太粗重量與體積都上升。9–11 毫米是探險修路的常用區間。",
    "q.l32#3.p" to "「兩個錨點串在一條扁帶上」的問題是什麼？",
    "q.l32#3.o0" to "屬於串聯失效，不是冗餘",
    "q.l32#3.o1" to "太浪費扁帶",
    "q.l32#3.o2" to "不好看",
    "q.l32#3.o3" to "會影響繩速",
    "q.l32#3.e" to "串聯結構裡，一個點失效會讓整條系統鬆動、受力突變。冗餘的前提是「各自獨立地連到主鎖」。",
    "q.l32#4.p" to "錨點五檢查裡，「獨立」指的是？",
    "q.l32#4.o0" to "兩個錨點要在不同岩體、不同樹、不同螺栓上",
    "q.l32#4.o1" to "兩個錨點距離近",
    "q.l32#4.o2" to "用同一條扁帶",
    "q.l32#4.o3" to "同一個裂縫裡的兩個塞子",
    "q.l32#4.e" to "同一個裂縫裡的兩個塞子，在同一岩體失效時會一起崩脫。獨立性判斷的是「失效原因是否相同」。",
    "q.l32#5.p" to "錨點的「方向」檢查指的是？",
    "q.l32#5.o0" to "錨點要能承受實際受力方向，不只是向下",
    "q.l32#5.o1" to "錨點朝向風景",
    "q.l32#5.o2" to "繩子走向要直",
    "q.l32#5.o3" to "錨點要在上方",
    "q.l32#5.e" to "修路時的橫向擺盪、上升時的擺動都會產生側向力。只考慮向下的錨點，會在側向受力時失效。",
    "q.l32#6.p" to "雪地錨點最需要額外警惕的是？",
    "q.l32#6.o0" to "雪層強度與融化風險——化雪時可能整段失效",
    "q.l32#6.o1" to "雪太軟不好埋",
    "q.l32#6.o2" to "雪會弄溼繩子",
    "q.l32#6.o3" to "雪錐太重",
    "q.l32#6.e" to "雪錨的可靠性高度依賴溫度與時間。下午化雪時的錨點，可能和清晨完全不是一回事。",
    "q.l32#7.p" to "繩尾打結的作用是？",
    "q.l32#7.o0" to "防止繩頭從器械中滑出",
    "q.l32#7.o1" to "方便收繩",
    "q.l32#7.o2" to "標記長度",
    "q.l32#7.o3" to "增加摩擦",
    "q.l32#7.e" to "下降或跟攀時繩頭一旦滑出器械，人就失去連線。繩尾結是成本最低、收益最高的一道保險。",
    "q.l32#8.p" to "中間轉點（re-belay）的主要作用是？",
    "q.l32#8.o0" to "讓繩子順滑過渡，把墜落與磨損限制在一段之內",
    "q.l32#8.o1" to "增加重量",
    "q.l32#8.o2" to "方便拍照",
    "q.l32#8.o3" to "替代確保站",
    "q.l32#8.e" to "長路線不做轉點，繩子會在岩角處形成巨大折角，抽繩困難、磨損集中、墜落距離也變長。",
    "q.l32#9.p" to "修路時，下方能不能站人？",
    "q.l32#9.o0" to "不能，修路者在上方作業時下方必須清空",
    "q.l32#9.o1" to "可以，方便遞工具",
    "q.l32#9.o2" to "可以，只要戴頭盔",
    "q.l32#9.o3" to "可以，只要不打鬧",
    "q.l32#9.e" to "落石是修路作業最主要的傷害來源。下方站人等於把最危險的位置留給隊友。",
    "q.l32#10.p" to "修路規劃階段就該確定的四件事是？",
    "q.l32#10.o0" to "每段起終點、轉點與撤退點、繩長、固定方式",
    "q.l32#10.o1" to "顏色、品牌、價格、重量",
    "q.l32#10.o2" to "誰先上、誰拍照、誰燒水、誰記賬",
    "q.l32#10.o3" to "天氣、心情、預算、假期",
    "q.l32#10.e" to "這四項決定了一次修路能否安全撤退。跳過規劃直接上繩，等於把撤退方案留給了運氣。",
    "q.l32#11.p" to "為什麼固定繩要做到「定期檢查、記錄在案」？",
    "q.l32#11.o0" to "修路路線往往用整季，繩況會隨日曬、磨損、凍融變化",
    "q.l32#11.o1" to "為了審計",
    "q.l32#11.o2" to "為了分攤責任",
    "q.l32#11.o3" to "沒必要",
    "q.l32#11.e" to "繩皮起毛、變硬、區域性扁平都是退役訊號。沒有記錄，就沒有人說得清這條繩掛了多少天。",
    "q.l32#12.p" to "錨點五檢查包括哪些？",
    "q.l32#12.o0" to "獨立",
    "q.l32#12.o1" to "均衡",
    "q.l32#12.o2" to "方向",
    "q.l32#12.o3" to "銳邊保護",
    "q.l32#12.e" to "第五項是「備份」。五項裡最容易漏的是銳邊：扁帶被岩角切傷後，強度可能只剩很小一部分。",
    "q.l32#13.p" to "哪些情況說明固定繩應該退役？",
    "q.l32#13.o0" to "繩皮起毛、能摸到繩芯",
    "q.l32#13.o1" to "繩索變硬、手感發脆",
    "q.l32#13.o2" to "區域性壓扁變形",
    "q.l32#13.o3" to "顏色褪了",
    "q.l32#13.e" to "前三項都是結構損傷。褪色只是外觀，但也要注意它與紫外線老化的相關性。",
    "q.l32#14.p" to "修路作業裡的自我保護要求包括？",
    "q.l32#14.o0" to "任何時候至少兩個連線點",
    "q.l32#14.o1" to "戴頭盔",
    "q.l32#14.o2" to "設上方警戒、防止落石",
    "q.l32#14.o3" to "繩袋管理餘繩",
    "q.l32#14.e" to "四者共同構成「作業面安全」。其中「兩個連線點」是唯一的硬原則，例外只有直接系入繩子領攀。",
    "q.l32#15.p" to "固定繩系統的冗餘可以體現在哪些層面？",
    "q.l32#15.o0" to "錨點冗餘（兩個獨立點）",
    "q.l32#15.o1" to "連線冗餘（PAS/扁帶備份）",
    "q.l32#15.o2" to "器械冗餘（備份抓結）",
    "q.l32#15.o3" to "顏色冗餘（多買幾種顏色）",
    "q.l32#15.e" to "三層冗餘分別對應「系統不失效、轉移不落空、器械不單獨承重」。顏色與安全無關。",
    "q.l32#16.p" to "把一段固定繩的架設順序排成正確次序。",
    "q.l32#16.o0" to "確定起終點與轉點位置，估算繩長",
    "q.l32#16.o1" to "建立錨點（獨立、均衡、有備份）",
    "q.l32#16.o2" to "鋪設繩子，設定中間轉點",
    "q.l32#16.o3" to "繩尾打結並記錄繩況",
    "q.l32#16.e" to "繩長要留出打結與連線餘量，寧長勿短。繩尾結放在最後，但它絕不能省。",
    "q.l32#17.p" to "發現錨點其中一個點可疑，正確的處置順序是？",
    "q.l32#17.o0" to "停止使用該段，把人員置於安全位置",
    "q.l32#17.o1" to "補充獨立備份點",
    "q.l32#17.o2" to "重新均衡受力",
    "q.l32#17.o3" to "檢查並記錄，再決定是否繼續",
    "q.l32#17.e" to "先把人放到安全位置，再談技術處置。順序反了，處置過程本身就會變成事故現場。",
    "q.l32#18.p" to "固定繩長期使用的日常流程，正確的是？",
    "q.l32#18.o0" to "出發前檢查錨點與繩況",
    "q.l32#18.o1" to "透過時確認兩個連線",
    "q.l32#18.o2" to "收隊時檢查磨損與繩尾結",
    "q.l32#18.o3" to "記錄檢查日期與問題",
    "q.l32#18.e" to "這套流程的價值在於「把檢查變成習慣」。靠記憶管理一條整季的固定繩，遲早會漏。",
    "q.l32#19.p" to "動力繩的標準號是 EN ______。",
    "q.l32#19.a0" to "892",
    "q.l32#19.e" to "動力繩 EN 892 / UIAA 101，靜力繩 EN 1891 / UIAA 110。採購與檢查時按標準號核對。",
    "q.l32#20.p" to "固定繩應選用 ______ 繩（填「動力」或「靜力」）。",
    "q.l32#20.a0" to "靜力",
    "q.l32#20.a1" to "靜力繩",
    "q.l32#20.e" to "靜力繩低延展、耐磨，適合長期固定。動力繩的延展會讓固定繩在使用中不斷上下彈。",
    "q.l32#21.p" to "修路時，繩尾必須 ______，防止繩頭滑出器械。",
    "q.l32#21.a0" to "打結",
    "q.l32#21.a1" to "打繩尾結",
    "q.l32#21.e" to "這是最容易被省略的一步，也是後果最直接的一步。",
    "q.l32#22.p" to "探險修路常用的靜力繩直徑區間是 ______–11 毫米。",
    "q.l32#22.a0" to "9",
    "q.l32#22.e" to "9–11 毫米兼顧耐磨與重量。低於 9 毫米磨損快，高於 11 毫米負重明顯。",
    "q.l32#23.p" to "把固定繩型別與它的典型場景對應起來。",
    "q.l32#23.l0" to "扶手繩",
    "q.l32#23.l1" to "短段固定繩",
    "q.l32#23.l2" to "探險修路",
    "q.l32#23.l3" to "中間轉點",
    "q.l32#23.r0" to "短距離暴露路段，扶著透過",
    "q.l32#23.r1" to "一段陡坡或一個繩距，反覆上下",
    "q.l32#23.r2" to "長路線、多繩距、負重、整季使用",
    "q.l32#23.r3" to "把長繩分段，減少折角與磨損",
    "q.l32#23.e" to "場景決定標準：越長期、越負重、越暴露，對錨點冗餘與繩況記錄的要求越高。",
    "q.l32#24.p" to "把器材與它的標準號對應起來。",
    "q.l32#24.l0" to "靜力繩",
    "q.l32#24.l1" to "動力繩",
    "q.l32#24.l2" to "上升器",
    "q.l32#24.l3" to "安全帶",
    "q.l32#24.r0" to "EN 1891 / UIAA 110",
    "q.l32#24.r1" to "EN 892 / UIAA 101",
    "q.l32#24.r2" to "EN 567",
    "q.l32#24.r3" to "EN 12277",
    "q.l32#24.e" to "標準號是採購與檢查的依據，也用於判斷「這件器材原本是為哪種受力設計的」。",
    "q.l32#25.p" to "把錨點問題與它的後果對應起來。",
    "q.l32#25.l0" to "串聯失效",
    "q.l32#25.l1" to "受力方向單一",
    "q.l32#25.l2" to "銳邊無保護",
    "q.l32#25.l3" to "單點無備份",
    "q.l32#25.r0" to "一點失效導致整條系統鬆動、受力突變",
    "q.l32#25.r1" to "側向受力時錨點拔出或斷裂",
    "q.l32#25.r2" to "扁帶被切傷，強度大幅下降",
    "q.l32#25.r3" to "唯一連線失效即完全失去保護",
    "q.l32#25.e" to "四類問題對應四種失效方式。它們常常同時存在，所以檢查要逐項過，而不是「看著還行」。",
    "q.l32#26.p" to "隊友說「這條繩才用了一個季節，不用檢查」，最合理的回應是？",
    "q.l32#26.o0" to "固定繩的損耗看的是暴露與磨損，不是季節長短",
    "q.l32#26.o1" to "確實不用檢查",
    "q.l32#26.o2" to "換個顏色就行",
    "q.l32#26.o3" to "只要沒斷就能用",
    "q.l32#26.e" to "日曬、凍融、岩角摩擦都在累積損傷。固定繩的檢查週期由使用強度決定，而不是日曆。",
    "q.l32#27.p" to "修路時繩長估算的原則是？",
    "q.l32#27.o0" to "留出打結與連線餘量，寧長勿短",
    "q.l32#27.o1" to "正好等於段長",
    "q.l32#27.o2" to "越短越輕越好",
    "q.l32#27.o3" to "按地圖直線距離算",
    "q.l32#27.e" to "繩短了整段作廢，繩長了只是重一點。打結、連線、轉點都要吃長度，估算時必須計入。",
    "q.l32#28.p" to "一名隊員要透過一段有橫向擺盪的固定繩，最需要確認的是？",
    "q.l32#28.o0" to "錨點是否能承受側向受力，以及是否有第二個連線點",
    "q.l32#28.o1" to "繩子顏色",
    "q.l32#28.o2" to "繩長",
    "q.l32#28.o3" to "他的體重",
    "q.l32#28.e" to "橫向擺盪是把「向下」的錨點變成「側向」受力，很多錨點正是這樣被拔出來的。",
    "q.l32#29.p" to "為什麼固定繩路線要設「撤退點」？",
    "q.l32#29.o0" to "天氣或人員狀態變化時，能在一段之內安全退出",
    "q.l32#29.o1" to "為了休息",
    "q.l32#29.o2" to "為了堆放裝備",
    "q.l32#29.o3" to "為了拍照",
    "q.l32#29.e" to "長路線不可能每次都走到底。撤退點決定了「情況變壞時還有沒有選擇」。",
    "q.l33#0.p" to "上升固定繩的標準配置不包括下面哪一項？",
    "q.l33#0.o0" to "下降器（8 字或管式）",
    "q.l33#0.o1" to "手式上升器",
    "q.l33#0.o2" to "腳踏繩",
    "q.l33#0.o3" to "備份抓結",
    "q.l33#0.e" to "上升階段不需要下降器；它屬於換繩與下降環節。配置清單按「當前動作」來定，不是把全部器材都掛上。",
    "q.l33#1.p" to "上升動作的口訣是？",
    "q.l33#1.o0" to "站起、坐、推",
    "q.l33#1.o1" to "拉、撐、跳",
    "q.l33#1.o2" to "蹲、跳、抓",
    "q.l33#1.o3" to "推、拉、坐",
    "q.l33#1.e" to "雙腳踩腳踏站起→重心上移→推胸式→坐下→推手式。節奏對了能省一半體力。",
    "q.l33#2.p" to "上升時重心應該？",
    "q.l33#2.o0" to "貼近繩子",
    "q.l33#2.o1" to "儘量向外",
    "q.l33#2.o2" to "左右擺動",
    "q.l33#2.o3" to "儘量後仰",
    "q.l33#2.e" to "重心外蕩會讓上升器受側向力、容易脫開，同時大幅增加體力消耗。貼繩是安全也是效率。",
    "q.l33#3.p" to "「兩點連線」原則的例外是什麼？",
    "q.l33#3.o0" to "直接系入繩子領攀",
    "q.l33#3.o1" to "天氣好時",
    "q.l33#3.o2" to "白天",
    "q.l33#3.o3" to "短距離時",
    "q.l33#3.e" to "領攀時人本身就是系統的一部分，無法再掛第二個點。除此之外，任何時候都應有兩個獨立連線。",
    "q.l33#4.p" to "過繩結的第一原則是？",
    "q.l33#4.o0" to "先建新連線，再拆舊連線",
    "q.l33#4.o1" to "先拆舊連線，再建新連線",
    "q.l33#4.o2" to "兩把同時操作",
    "q.l33#4.o3" to "直接跳過繩結",
    "q.l33#4.e" to "順序反了就會短暫出現「只靠一個點」甚至「沒有點」的狀態。過結的本質是一次受控的系統轉移。",
    "q.l33#5.p" to "過結過程中，允許兩把上升器同時離開繩子嗎？",
    "q.l33#5.o0" to "不允許，任何時刻至少一把在繩上並受力",
    "q.l33#5.o1" to "允許，只要動作快",
    "q.l33#5.o2" to "允許，只要有人看著",
    "q.l33#5.o3" to "允許，短繩結可以",
    "q.l33#5.e" to "兩把同時脫開意味著人失去全部上行連線。寧可多花一分鐘重新佈置，也不要賭一次。",
    "q.l33#6.p" to "上升轉下降的第一步是？",
    "q.l33#6.o0" to "用 PAS 或扁帶把自己掛入錨點",
    "q.l33#6.o1" to "先拆手式上升器",
    "q.l33#6.o2" to "先裝下降器",
    "q.l33#6.o3" to "先解開胸式",
    "q.l33#6.e" to "先獲得一個獨立於上升系統的連線，才談得上拆舊系統。這是所有換繩動作的共同起點。",
    "q.l33#7.p" to "裝好下降器之後、拆上升器之前，必須做什麼？",
    "q.l33#7.o0" to "讓下降器受力並測試",
    "q.l33#7.o1" to "先解開安全帶",
    "q.l33#7.o2" to "先收繩",
    "q.l33#7.o3" to "先摘頭盔",
    "q.l33#7.e" to "「測試受力」是確認新系統真的能承受體重的唯一方式。跳過這一步，拆掉舊系統就可能直接墜落。",
    "q.l33#8.p" to "下降時，下降器上方的摩擦結（備份）作用是？",
    "q.l33#8.o0" to "在失手時自動鎖住，作為獨立備份",
    "q.l33#8.o1" to "增加下降速度",
    "q.l33#8.o2" to "保護繩子",
    "q.l33#8.o3" to "標記位置",
    "q.l33#8.e" to "摩擦結在鬆開制動手時會咬住繩子。它是「手鬆開」這一最危險瞬間的唯一防線。",
    "q.l33#9.p" to "下降前繩尾打結的目的是？",
    "q.l33#9.o0" to "防止繩頭從下降器中滑出",
    "q.l33#9.o1" to "方便收繩",
    "q.l33#9.o2" to "標記繩長",
    "q.l33#9.o3" to "減少磨損",
    "q.l33#9.e" to "繩長不夠時，繩頭滑出意味著瞬間失去制動。繩尾結是下降前的必檢項。",
    "q.l33#10.p" to "透過中間轉點時，正確的順序是？",
    "q.l33#10.o0" to "先掛入轉點錨點，再移動上升器，最後解除錨點連線",
    "q.l33#10.o1" to "先移動上升器，再掛錨點",
    "q.l33#10.o2" to "直接透過，不掛錨點",
    "q.l33#10.o3" to "先解錨點，再移動",
    "q.l33#10.e" to "轉點處繩子被主鎖約束，操作空間小、動作容易變形。先建立獨立連線，才有容錯空間。",
    "q.l33#11.p" to "卡繩時應該怎麼處理？",
    "q.l33#11.o0" to "先改變拉繩角度或從側面牽引，不要站在繩下猛拉",
    "q.l33#11.o1" to "站在正下方用力拉",
    "q.l33#11.o2" to "用身體重量硬拽",
    "q.l33#11.o3" to "直接割斷",
    "q.l33#11.e" to "站正下方猛拉會被回彈的繩子或落石擊中，也可能把繩結卡得更死。改變角度是最有效的第一步。",
    "q.l33#12.p" to "雙繩下降取繩時，應該拉哪一側？",
    "q.l33#12.o0" to "摩擦力小的一側",
    "q.l33#12.o1" to "摩擦力大的一側",
    "q.l33#12.o2" to "隨便哪一側",
    "q.l33#12.o3" to "兩側同時拉",
    "q.l33#12.e" to "拉摩擦力小的一側更容易抽回，也減少繩皮磨損。前提是繩尾已打結、沒有纏掛。",
    "q.l33#13.p" to "上升固定繩時，哪些屬於「必須隨身」的器材？",
    "q.l33#13.o0" to "手式與胸式上升器（或第二把抓結）",
    "q.l33#13.o1" to "腳踏繩",
    "q.l33#13.o2" to "備份抓結與 PAS",
    "q.l33#13.o3" to "頭盔",
    "q.l33#13.e" to "四者構成完整的上升與備份系統。少一樣，過結與換繩時就會被迫「單點作業」。",
    "q.l33#14.p" to "換繩環節裡最常見的錯誤包括？",
    "q.l33#14.o0" to "先拆舊系統、後建新系統",
    "q.l33#14.o1" to "不測試下降器受力就拆上升器",
    "q.l33#14.o2" to "兩把上升器同時脫開",
    "q.l33#14.o3" to "換繩前先掛入錨點",
    "q.l33#14.e" to "前三項都是「順序錯」。最後一項恰恰是正確做法——先掛錨點，正是為了避免前三種錯誤。",
    "q.l33#15.p" to "下降前必須完成的檢查包括？",
    "q.l33#15.o0" to "下降器穿繩方向正確",
    "q.l33#15.o1" to "摩擦結備份已裝並有效",
    "q.l33#15.o2" to "繩尾已打結",
    "q.l33#15.o3" to "繩長足夠到達下一個站",
    "q.l33#15.e" to "四項缺一都可能導致失控。這組檢查應該在「解除保護之前」全部完成。",
    "q.l33#16.p" to "過繩結時可用作「新連線」的手段包括？",
    "q.l33#16.o0" to "PAS 或扁帶掛入繩結上方",
    "q.l33#16.o1" to "掛入附近的錨點",
    "q.l33#16.o2" to "在上方裝第二把上升器",
    "q.l33#16.o3" to "用手抓住繩子",
    "q.l33#16.e" to "用手抓繩不是連線，手一鬆就沒了。前三種都能形成「獨立於舊系統」的受力點。",
    "q.l33#17.p" to "把「上升透過繩結」的六步排成正確順序。",
    "q.l33#17.o0" to "接近繩結前減速，觀察繩結位置與上方繩段",
    "q.l33#17.o1" to "用 PAS 或扁帶把自己連線到繩結上方或附近錨點",
    "q.l33#17.o2" to "在上方裝第二把上升器或抓結，站起轉移體重",
    "q.l33#17.o3" to "拆下下方上升器，裝到繩結上方",
    "q.l33#17.o4" to "確認新連線受力，再解除 PAS 備份",
    "q.l33#17.e" to "五步的核心是「永遠多一個點」。少任何一步，都會出現一段只有單點受力甚至無連線的空檔。",
    "q.l33#18.p" to "把「上升轉下降」的順序排好。",
    "q.l33#18.o0" to "掛入錨點（PAS 或扁帶）",
    "q.l33#18.o1" to "裝下降器並正確穿繩",
    "q.l33#18.o2" to "讓下降器受力並測試",
    "q.l33#18.o3" to "拆手式上升器，保留胸式或備份抓結",
    "q.l33#18.o4" to "拆下另一把上升器，確認下降器與備份正常",
    "q.l33#18.o5" to "解除 PAS，開始下降",
    "q.l33#18.e" to "順序固定，不許臨時調整。每一步都保證「至少有一個可靠連線」。",
    "q.l33#19.p" to "把「下降轉上升」的順序排好。",
    "q.l33#19.o0" to "在下降器上方裝抓結或上升器並連到安全帶",
    "q.l33#19.o1" to "站起，把體重轉移到抓結",
    "q.l33#19.o2" to "裝第二把上升器或腳踏繩並確認受力",
    "q.l33#19.o3" to "拆下下降器",
    "q.l33#19.o4" to "開始上升",
    "q.l33#19.e" to "關鍵在第三步：新系統必須已經受力，才允許拆掉下降器。",
    "q.l33#20.p" to "把「透過繩結下降」的三步排好。",
    "q.l33#20.o0" to "在繩結上方用 PAS 掛入繩結或錨點形成備份",
    "q.l33#20.o1" to "把下降器移到繩結下方，收緊並測試受力",
    "q.l33#20.o2" to "解除 PAS，繼續下降",
    "q.l33#20.e" to "粗繩結無法直接透過時，先把備份抓結移到繩結下方，再移下降器——兩次轉移之間始終保持一個可靠連線。",
    "q.l33#21.p" to "上升固定繩時，任何時候都應保持 ______ 個獨立連線點。",
    "q.l33#21.a0" to "2",
    "q.l33#21.a1" to "兩",
    "q.l33#21.e" to "兩點連線是固定繩作業的硬原則。唯一的例外是直接系入繩子領攀。",
    "q.l33#22.p" to "上升轉下降時，必須先掛入 ______，再拆上升器。",
    "q.l33#22.a0" to "錨點",
    "q.l33#22.a1" to "確保站",
    "q.l33#22.a2" to "轉點",
    "q.l33#22.e" to "先獲得不依賴舊系統的連線，是所有換繩動作的起點。",
    "q.l33#23.p" to "下降器上方的備份摩擦結常見形式是 prusik 或 ______。",
    "q.l33#23.a0" to "autoblock",
    "q.l33#23.a1" to "法式抓結",
    "q.l33#23.a2" to "摩擦結",
    "q.l33#23.e" to "兩種都是「鬆手即鎖」的備份。裝反或長度不對都會失效，所以要練到閉眼也能確認。",
    "q.l33#24.p" to "把操作環節與它的關鍵原則對應起來。",
    "q.l33#24.l0" to "過繩結",
    "q.l33#24.l1" to "透過轉點",
    "q.l33#24.l2" to "上升轉下降",
    "q.l33#24.l3" to "下降轉上升",
    "q.l33#24.r0" to "先建新連線，再拆舊連線",
    "q.l33#24.r1" to "先掛入錨點，再移動器械",
    "q.l33#24.r2" to "掛錨點 → 裝下降器 → 測試 → 拆上升器",
    "q.l33#24.r3" to "新系統受力後，才拆下降器",
    "q.l33#24.e" to "四個環節的共同結構是「建立 → 轉移 → 拆除」。記結構比記步驟更抗遺忘。",
    "q.l33#25.p" to "把檢查表 ABCDE 與它的內容對應起來。",
    "q.l33#25.l0" to "A 錨點",
    "q.l33#25.l1" to "B 備份",
    "q.l33#25.l2" to "C 連線",
    "q.l33#25.l3" to "E 退出",
    "q.l33#25.r0" to "兩個獨立點、均衡、受力方向正確、銳邊有保護",
    "q.l33#25.r1" to "PAS 或抓結在位，器械各有獨立備份",
    "q.l33#25.r2" to "主鎖鎖門關閉、繩結打緊、繩尾打結",
    "q.l33#25.r3" to "知道最近撤退點、繩長夠、通訊明確",
    "q.l33#25.e" to "這套檢查表的價值在於「每次上繩前過一遍」。它不替代判斷，但能擋住絕大多數低階錯誤。",
    "q.l33#26.p" to "隊友過結時打算「一把上升器先拆，另一把隨後馬上裝」，你會怎麼提醒？",
    "q.l33#26.o0" to "必須先建立 PAS 或錨點連線，不允許出現無連線空檔",
    "q.l33#26.o1" to "動作快就行",
    "q.l33#26.o2" to "白天可以",
    "q.l33#26.o3" to "短繩結可以",
    "q.l33#26.e" to "「隨後馬上」在失手時就是零容錯。過結的容錯空間必須靠第三個連線創造出來。",
    "q.l33#27.p" to "在轉點處，繩子需要從主鎖裡取出再放回，正確做法是？",
    "q.l33#27.o0" to "先掛入錨點，再操作繩子，最後解除備份",
    "q.l33#27.o1" to "先取繩，再掛錨點",
    "q.l33#27.o2" to "讓人拉住繩子",
    "q.l33#27.o3" to "直接把主鎖開啟",
    "q.l33#27.e" to "取繩的瞬間人可能完全依賴舊連線。先建立獨立連線，操作才有意義。",
    "q.l33#28.p" to "為什麼換繩被稱作固定繩操作裡最容易出事的環節？",
    "q.l33#28.o0" to "因為要在拆舊系統與建新系統之間做轉移，容錯窗口最小",
    "q.l33#28.o1" to "因為器材多",
    "q.l33#28.o2" to "因為很累",
    "q.l33#28.o3" to "因為需要兩個人",
    "q.l33#28.e" to "過結只是「加一個點」，換繩要「換一整套系統」。任何順序錯誤都會直接導致失去連線。",
    "q.l34#0.p" to "冰川上最危險、也最容易被低估的地形是？",
    "q.l34#0.o0" to "被雪覆蓋的裂縫與雪橋",
    "q.l34#0.o1" to "冰磧壟",
    "q.l34#0.o2" to "平坦的雪原",
    "q.l34#0.o3" to "冰川兩側的碎石坡",
    "q.l34#0.e" to "裂縫被新雪覆蓋後與普通雪面看起來一樣。冰川事故里，墜入裂縫佔的比例最高。",
    "q.l34#1.p" to "橫向裂縫最常出現在什麼位置？",
    "q.l34#1.o0" to "坡度變化處（坡頂、坡腳、翻越冰坎處）",
    "q.l34#1.o1" to "冰川正中央",
    "q.l34#1.o2" to "冰川末端",
    "q.l34#1.o3" to "冰磧上",
    "q.l34#1.e" to "坡度突變意味著拉伸或壓縮，裂縫就在這些位置張開。上坡前先觀察坡頂那一帶，是最實用的習慣。",
    "q.l34#2.p" to "冰川兩側常見的縱向裂縫，成因是？",
    "q.l34#2.o0" to "冰川流動時兩側與地形摩擦造成的拉伸",
    "q.l34#2.o1" to "落石砸出來的",
    "q.l34#2.o2" to "登山者踩出來的",
    "q.l34#2.o3" to "融水衝出來的",
    "q.l34#2.e" to "中間流速快、兩側慢，速度差造成剪下與拉伸。所以沿冰川中線走通常比貼邊安全。",
    "q.l34#3.p" to "結組行進時，繩距通常取多少？",
    "q.l34#3.o0" to "8–10 公尺",
    "q.l34#3.o1" to "2–3 公尺",
    "q.l34#3.o2" to "20–30 公尺",
    "q.l34#3.o3" to "越近越好",
    "q.l34#3.e" to "繩距太短，一人墜入會直接把隊友拽進去；太長則制動距離與救援難度都上升。裂縫密集區要縮短但不宜小於 6–8 公尺。",
    "q.l34#4.p" to "為什麼結組時要在繩上打結？",
    "q.l34#4.o0" to "限制墜入深度、增加制動摩擦，也便於救援時抓握",
    "q.l34#4.o1" to "防止繩子扭結",
    "q.l34#4.o2" to "標記長度",
    "q.l34#4.o3" to "美觀",
    "q.l34#4.e" to "繩結會在裂縫口形成額外的阻力與卡點，明顯減少墜入深度。代價是抽繩稍麻煩，但值得。",
    "q.l34#5.p" to "三人結組比兩人結組的主要優勢是？",
    "q.l34#5.o0" to "一人墜入時兩人制動、一人可準備救援系統，餘量更大",
    "q.l34#5.o1" to "走得更快",
    "q.l34#5.o2" to "繩更輕",
    "q.l34#5.o3" to "不需要打結",
    "q.l34#5.e" to "兩人結組時，制動的人幾乎無法再操作救援系統；三人結組才有「制動 + 建系統」的分工。",
    "q.l34#6.p" to "判斷雪橋是否可靠，最先看什麼？",
    "q.l34#6.o0" to "顏色與凹陷——發暗、發藍或有放射狀裂紋說明薄",
    "q.l34#6.o1" to "腳印多少",
    "q.l34#6.o2" to "表面是否平整",
    "q.l34#6.o3" to "有沒有風",
    "q.l34#6.e" to "雪橋的強度取決於跨度與雪層厚度。顏色與凹陷是最直觀的線索，腳印只說明「別人也走過」，不說明安全。",
    "q.l34#7.p" to "跨越裂縫密集區，最合適的時間是？",
    "q.l34#7.o0" to "清晨或夜間低溫時段",
    "q.l34#7.o1" to "正午",
    "q.l34#7.o2" to "午後",
    "q.l34#7.o3" to "任何時間都一樣",
    "q.l34#7.e" to "低溫時雪橋最結實，午後融雪後強度顯著下降。行程設計要圍繞這一點安排透過時間。",
    "q.l34#8.p" to "透過冰瀑區（serac 區）的正確做法是？",
    "q.l34#8.o0" to "快速透過、保持間距、戴頭盔，不在區內停留",
    "q.l34#8.o1" to "結組慢慢走",
    "q.l34#8.o2" to "在區內休息",
    "q.l34#8.o3" to "拍照留念",
    "q.l34#8.e" to "冰瀑區的風險是冰塔崩塌，與裂縫不同——它落下來是整塊的。停留時間越短越好，也不要在這裡結組等人。",
    "q.l34#9.p" to "在冰川上行走，繩子應該保持什麼狀態？",
    "q.l34#9.o0" to "適度張緊，不拖地也不過度鬆弛",
    "q.l34#9.o1" to "完全鬆弛拖在雪面",
    "q.l34#9.o2" to "繃得很緊",
    "q.l34#9.o3" to "捲起來提著",
    "q.l34#9.e" to "鬆弛的繩會在墜落瞬間產生衝擊載荷，繃緊的繩則會互相牽扯。適度張緊 + 繩上打結是最穩的組合。",
    "q.l34#10.p" to "遇到明顯的裂縫，最優先的處理是？",
    "q.l34#10.o0" to "繞行，找更窄或已架橋的位置透過",
    "q.l34#10.o1" to "直接跳過去",
    "q.l34#10.o2" to "踩在裂縫邊緣觀察深度",
    "q.l34#10.o3" to "用冰鎬挖寬",
    "q.l34#10.e" to "冰川路線選擇的第一原則是「繞」。跳越與踩邊緣觀察是最常見的兩種自傷方式。",
    "q.l34#11.p" to "為什麼說「沿冰川中線走」通常更安全？",
    "q.l34#11.o0" to "兩側拉伸帶裂縫更多，中線受力相對均勻",
    "q.l34#11.o1" to "中線雪更厚",
    "q.l34#11.o2" to "中線更短",
    "q.l34#11.o3" to "中線人更多",
    "q.l34#11.e" to "中線裂縫通常較少、雪橋跨度較小。但冰瀑區與冰坎處要另做判斷，不能機械照搬。",
    "q.l34#12.p" to "冰川路線的風險評估要考慮哪些？",
    "q.l34#12.o0" to "裂縫密度與雪橋狀況",
    "q.l34#12.o1" to "冰塔與落冰風險",
    "q.l34#12.o2" to "當天氣溫與日照（影響雪橋強度）",
    "q.l34#12.o3" to "隊伍人數與結組方式",
    "q.l34#12.e" to "四項互相影響：溫度決定雪橋，人數決定結組，結組方式決定墜落後果。風險評估是把它們放在一起看。",
    "q.l34#13.p" to "哪些跡象提示雪橋可能不可靠？",
    "q.l34#13.o0" to "橋面明顯下凹",
    "q.l34#13.o1" to "顏色發暗、發藍",
    "q.l34#13.o2" to "橋邊有放射狀裂紋",
    "q.l34#13.o3" to "橋面有新雪覆蓋但下方有空洞回聲",
    "q.l34#13.e" to "四項都是「強度不足」的不同表現。聽到空洞回聲時應該退回去，而不是再往前踩一步。",
    "q.l34#14.p" to "在冰川上，哪些做法會增加風險？",
    "q.l34#14.o0" to "結組距離過近",
    "q.l34#14.o1" to "繩上不打結",
    "q.l34#14.o2" to "在冰瀑區停留休息",
    "q.l34#14.o3" to "沿冰川邊緣走",
    "q.l34#14.e" to "四項分別增加「連帶墜落、深埋、落冰、側向裂縫」的風險。它們都是可以避免的選擇。",
    "q.l34#15.p" to "隊伍透過裂縫密集區前應統一的事項？",
    "q.l34#15.o0" to "繩距與打結方式",
    "q.l34#15.o1" to "透過順序與間距",
    "q.l34#15.o2" to "遇到雪橋的處置原則（探、繞、退）",
    "q.l34#15.o3" to "誰的揹包最重",
    "q.l34#15.e" to "前三項決定「遇到情況時大家怎麼反應」。事前統一，比在裂縫邊上臨時討論安全得多。",
    "q.l34#16.p" to "把透過一段可疑雪橋的流程排成正確順序。",
    "q.l34#16.o0" to "停下，觀察顏色、凹陷與周邊裂紋",
    "q.l34#16.o1" to "用冰鎬或探杆試探橋面厚度",
    "q.l34#16.o2" to "確認繞行不可行後，縮短繩距、逐個透過",
    "q.l34#16.o3" to "全員透過後，最後一人解除保護再跟上",
    "q.l34#16.e" to "試探必須在人上橋之前。逐個透過意味著「一次只承擔一個人的重量」，這是最關鍵的安排。",
    "q.l34#17.p" to "安排冰川行程時，正確的順序是？",
    "q.l34#17.o0" to "先看路線圖與裂縫分佈",
    "q.l34#17.o1" to "確定透過裂縫區的時段（清晨/夜間）",
    "q.l34#17.o2" to "確定結組方式與繩距",
    "q.l34#17.o3" to "出發前再次確認天氣與溫度",
    "q.l34#17.e" to "先地形、再時間、再編隊、最後天氣複核。順序反了就會出現「按計劃走，但時間選錯了」的情況。",
    "q.l34#18.p" to "發現隊友墜入裂縫，最先做的三件事的順序是？",
    "q.l34#18.o0" to "立即制動並保持繩索受力",
    "q.l34#18.o1" to "確認自身位置安全、建立保護",
    "q.l34#18.o2" to "呼叫隊友準備救援系統",
    "q.l34#18.o3" to "按結組救援流程操作",
    "q.l34#18.e" to "制動是唯一不能等的事；之後才是保護與救援系統。詳細流程見「自救與結組救援」一課。",
    "q.l34#19.p" to "冰川結組的常見繩距是 ______–10 公尺。",
    "q.l34#19.a0" to "8",
    "q.l34#19.e" to "8–10 公尺是通行區間。裂縫密集時縮短，但不能短到「一人墜落帶走全隊」。",
    "q.l34#20.p" to "判斷雪橋強度，除了看顏色與凹陷，還應該用冰鎬 ______。",
    "q.l34#20.a0" to "試探",
    "q.l34#20.a1" to "探",
    "q.l34#20.a2" to "探一探",
    "q.l34#20.e" to "試探要在人上橋之前完成。用鎬尖輕插，感受雪層厚度與下方是否有空洞。",
    "q.l34#21.p" to "跨越裂縫密集區最好安排在 ______（時段），此時雪橋最結實。",
    "q.l34#21.a0" to "清晨",
    "q.l34#21.a1" to "早晨",
    "q.l34#21.a2" to "凌晨",
    "q.l34#21.e" to "低溫使雪橋更硬更結實；午後融雪後強度下降明顯。",
    "q.l34#22.p" to "把裂縫型別與它的典型位置對應起來。",
    "q.l34#22.l0" to "橫向裂縫",
    "q.l34#22.l1" to "縱向裂縫",
    "q.l34#22.l2" to "斜向裂縫",
    "q.l34#22.l3" to "冰塔/冰瀑區",
    "q.l34#22.r0" to "坡度變化處（坡頂、坡腳、冰坎）",
    "q.l34#22.r1" to "冰川兩側與地形摩擦的拉伸帶",
    "q.l34#22.r2" to "冰川轉彎或寬度變化處",
    "q.l34#22.r3" to "陡峭冰瀑下方，落冰風險高",
    "q.l34#22.e" to "裂縫的成因是「拉伸」。記住這一點，就能預判下一段路哪裡會裂。",
    "q.l34#23.p" to "把雪橋跡象與處置對應起來。",
    "q.l34#23.l0" to "橋面下凹",
    "q.l34#23.l1" to "顏色發暗發藍",
    "q.l34#23.l2" to "放射狀裂紋",
    "q.l34#23.l3" to "空洞回聲",
    "q.l34#23.r0" to "降低透過優先順序，優先繞行",
    "q.l34#23.r1" to "說明雪層薄，不要單人試探",
    "q.l34#23.r2" to "結構已受損，禁止透過",
    "q.l34#23.r3" to "立即退回，改路線",
    "q.l34#23.e" to "四種跡象的嚴重程度遞進。任何一種出現，都應該先考慮「繞」，而不是「快一點過去」。",
    "q.l34#24.p" to "把角色與職責對應起來（三人結組）。",
    "q.l34#24.l0" to "第一位（領攀/帶路）",
    "q.l34#24.l1" to "中間位",
    "q.l34#24.l2" to "最後一位",
    "q.l34#24.r0" to "判斷路線與雪橋，控制節奏",
    "q.l34#24.r1" to "兼顧前後，傳遞指令",
    "q.l34#24.r2" to "收繩、觀察後方與繩尾狀態",
    "q.l34#24.e" to "三人結組的分工要在出發前說清。中間位不是「最安全的位置」，而是資訊傳遞的樞紐。",
    "q.l34#25.p" to "隊伍裡有人想「踩一腳試試雪橋結不結實」，你會怎麼處理？",
    "q.l34#25.o0" to "阻止，改為用冰鎬或探杆試探，或直接繞行",
    "q.l34#25.o1" to "讓他試，反正結組了",
    "q.l34#25.o2" to "讓他一個人先過",
    "q.l34#25.o3" to "跑過去減少受力時間",
    "q.l34#25.e" to "人是幾十公斤的集中載荷，一腳下去就可能踩穿。試探要用工具，不是用體重。",
    "q.l34#26.p" to "中午氣溫升高，原計劃的裂縫區還有兩小時才到，應該？",
    "q.l34#26.o0" to "重新評估：等到傍晚降溫或改走備用路線",
    "q.l34#26.o1" to "按計劃繼續",
    "q.l34#26.o2" to "加快速度衝過去",
    "q.l34#26.o3" to "在原地等到明天",
    "q.l34#26.e" to "雪橋強度是時間的函式。計劃要圍繞「最結實的時段」設計，而不是讓人去適應計劃。",
    "q.l34#27.p" to "為什麼冰瀑區不適合作為結組等待點？",
    "q.l34#27.o0" to "冰塔崩塌是整塊落冰，等待會把暴露時間拉長",
    "q.l34#27.o1" to "因為風大",
    "q.l34#27.o2" to "因為地面不平",
    "q.l34#27.o3" to "因為訊號不好",
    "q.l34#27.e" to "裂縫風險靠結組分擔，落冰風險只能靠「減少暴露時間」。兩類風險的應對方向完全不同。",
    "q.l34#28.p" to "關於冰川行進的速度與節奏，正確的說法是？",
    "q.l34#28.o0" to "穩定勻速、保持繩距，比忽快忽慢更安全",
    "q.l34#28.o1" to "越快越安全",
    "q.l34#28.o2" to "越慢越安全",
    "q.l34#28.o3" to "按體力各自走",
    "q.l34#28.e" to "忽快忽慢會讓繩子反覆鬆緊，產生衝擊。冰川上「節奏統一」既是安全也是效率。",
    "q.l34#29.p" to "第一次上冰川的人，最該先練的是什麼？",
    "q.l34#29.o0" to "在安全區域練結組行進、繩距控制與制動姿勢",
    "q.l34#29.o1" to "練跑得更快",
    "q.l34#29.o2" to "練獨自透過裂縫",
    "q.l34#29.o3" to "練高空作業",
    "q.l34#29.e" to "制動姿勢與繩距感必須在安全地形上形成肌肉記憶，否則真掉進去時來不及。",
    "q.m13#14.p" to "利用抓結自主上升（prusik 上升）時，正確的順序是？",
    "q.m13#14.o0" to "站起（推上抓結）→ 坐下（轉移體重）→ 推下抓結 → 重複",
    "q.m13#14.o1" to "同時推兩個抓結",
    "q.m13#14.o2" to "只推上面的抓結",
    "q.m13#14.o3" to "用手臂拉",
    "q.m13#14.e" to "「站起—坐—推」的迴圈把體重在上下抓結之間轉移。同步推兩個抓結會直接滑落。",
    "q.m13#15.p" to "自主上升時，腳踏繩（foot loop）的作用是？",
    "q.m13#15.o0" to "把體重轉到腿上，減少手臂負擔",
    "q.m13#15.o1" to "增加摩擦",
    "q.m13#15.o2" to "連線安全帶",
    "q.m13#15.o3" to "標記高度",
    "q.m13#15.e" to "只靠手臂拉，幾十公尺就會力竭。腳踏繩讓腿參與，是能否爬出來的關鍵。",
    "q.m13#16.p" to "結組救援中，最先要做的是？",
    "q.m13#16.o0" to "制動並固定，防止墜落者繼續下滑",
    "q.m13#16.o1" to "立刻下到裂縫裡",
    "q.m13#16.o2" to "呼叫救援",
    "q.m13#16.o3" to "拍照記錄",
    "q.m13#16.e" to "制動是唯一不能等的事。固定之後再談通訊、系統與拉昇。",
    "q.m13#17.p" to "墜落者懸在裂縫裡時，最需要警惕的傷害是？",
    "q.m13#17.o0" to "失溫、繩索壓迫與撞擊傷",
    "q.m13#17.o1" to "曬傷",
    "q.m13#17.o2" to "高山症",
    "q.m13#17.o3" to "脫水",
    "q.m13#17.e" to "裂縫內溫度極低，懸吊還會造成血液迴圈受阻。救援要「快」，不只是把人拉上來。",
    "q.m13#18.p" to "為什麼救援時要先給墜落者一個「自我固定」？",
    "q.m13#18.o0" to "讓他不再依賴主繩，救援者才能騰手建系統",
    "q.m13#18.o1" to "因為不信任繩子",
    "q.m13#18.o2" to "因為規定",
    "q.m13#18.o3" to "因為沒有裝備",
    "q.m13#18.e" to "自我固定（抓結或冰鎬）能穩定位置，也讓墜落者有事可做，減少恐慌。",
    "q.m13#19.p" to "傷員無法自行行動時，拖出裂縫的正確方式是？",
    "q.m13#19.o0" to "建立 3:1 或 5:1 系統，從上方拉昇",
    "q.m13#19.o1" to "直接用手拉繩",
    "q.m13#19.o2" to "讓傷員自己爬",
    "q.m13#19.o3" to "把繩子繞在腰上",
    "q.m13#19.e" to "手拉幾乎不可能，且會失去控制。系統化拉昇是唯一可靠的方式。",
    "q.m13#20.p" to "救援時的時間壓力來自哪些方面？",
    "q.m13#20.o0" to "失溫速度、天氣變化、隊伍體力耗盡",
    "q.m13#20.o1" to "只有體力",
    "q.m13#20.o2" to "只有天氣",
    "q.m13#20.o3" to "只有失溫",
    "q.m13#20.e" to "三者同時作用。救援方案要考慮「多久能完成」，而不只是「能不能完成」。",
    "q.m13#21.p" to "救援溝通中，最不可靠的方式是？",
    "q.m13#21.o0" to "隔著小雪包用喊的",
    "q.m13#21.o1" to "對講機",
    "q.m13#21.o2" to "拉繩訊號",
    "q.m13#21.o3" to "哨子",
    "q.m13#21.e" to "風、繩長與地形會吞掉聲音。事先約定拉繩或哨音訊號，比現場喊更可靠。",
    "q.m13#22.p" to "為什麼自救技能要「在安全地形練到自動」？",
    "q.m13#22.o0" to "真實墜落時注意力被恐懼佔滿，只有自動動作能執行",
    "q.m13#22.o1" to "為了考試",
    "q.m13#22.o2" to "為了速度",
    "q.m13#22.o3" to "為了好看",
    "q.m13#22.e" to "這是所有救援訓練的共通邏輯：把動作練到不需要思考，才有餘量觀察與判斷。",
    "q.m13#23.p" to "結組救援中，第二名隊員的主要任務是？",
    "q.m13#23.o0" to "協助制動、準備系統、觀察上方風險",
    "q.m13#23.o1" to "拍照",
    "q.m13#23.o2" to "繼續前進",
    "q.m13#23.o3" to "收繩",
    "q.m13#23.e" to "三人結組的意義就在這裡：一人制動、一人建系統、一人觀察。兩人結組則要兼顧。",
    "q.m13#24.p" to "如果墜落者已無反應，救援優先順序是？",
    "q.m13#24.o0" to "儘快取出並開始急救，同時呼叫外部支援",
    "q.m13#24.o1" to "先建 5:1 系統",
    "q.m13#24.o2" to "等待救援",
    "q.m13#24.o3" to "先記錄",
    "q.m13#24.e" to "無反應意味著時間窗極短。此時「快」優先於「省力」，必要時用最簡單的系統。",
    "q.m13#25.p" to "救援完成後，最容易被忽略的一步是？",
    "q.m13#25.o0" to "覆盤系統與流程，把問題寫下來",
    "q.m13#25.o1" to "收繩",
    "q.m13#25.o2" to "下山",
    "q.m13#25.o3" to "吃飯",
    "q.m13#25.e" to "演練與實戰的差別會在覆盤裡顯形：哪個環節慢、哪個結打錯、哪句指令沒人聽清。",
    "q.m13#26.p" to "為什麼救援系統要「獨立於主繩」？",
    "q.m13#26.o0" to "主繩可能已被冰屑、銳邊損傷，且仍在承重",
    "q.m13#26.o1" to "因為規定",
    "q.m13#26.o2" to "因為更長",
    "q.m13#26.o3" to "因為更輕",
    "q.m13#26.e" to "把救援系統掛在受損且承重的主繩上，等於把兩次風險疊在一起。",
    "q.m13#27.p" to "在裂縫區，隊伍最該提前決定的是？",
    "q.m13#27.o0" to "誰負責制動、誰負責建系統、如何通訊",
    "q.m13#27.o1" to "誰走最前",
    "q.m13#27.o2" to "誰背最重",
    "q.m13#27.o3" to "誰拍照",
    "q.m13#27.e" to "分工要在出發前定好。墜落髮生的頭三十秒，沒人有時間討論「誰來做什麼」。",
    "q.m14#17.p" to "「沉沒成本」在登山決策裡的典型表現是？",
    "q.m14#17.o0" to "已經花了這麼多錢和時間，不能白來",
    "q.m14#17.o1" to "天氣預報不準",
    "q.m14#17.o2" to "裝備不夠",
    "q.m14#17.o3" to "隊友太慢",
    "q.m14#17.e" to "投入越多，越難放棄。但已付出的成本不會因為繼續而回收，只會增加新的風險。",
    "q.m14#18.p" to "「群體思維」最容易出現在什麼情況下？",
    "q.m14#18.o0" to "隊伍凝聚力強、缺少反對意見、領導表態過早",
    "q.m14#18.o1" to "隊伍分歧大",
    "q.m14#18.o2" to "人數少",
    "q.m14#18.o3" to "天氣差",
    "q.m14#18.e" to "凝聚力是好事，但它會壓制異議。讓最年輕的人先發言、指定「唱反調的人」，都是常見對策。",
    "q.m14#19.p" to "「確認偏誤」指的是？",
    "q.m14#19.o0" to "只尋找支援自己判斷的資訊，忽略相反證據",
    "q.m14#19.o1" to "記不住資訊",
    "q.m14#19.o2" to "過度謹慎",
    "q.m14#19.o3" to "依賴他人",
    "q.m14#19.e" to "想看「今天能上」，就會只注意到天氣好的跡象。主動找反例是唯一的解藥。",
    "q.m14#20.p" to "為什麼重大決策要用檢查表？",
    "q.m14#20.o0" to "疲勞與壓力下會漏項，清單把「記得」變成「逐項確認」",
    "q.m14#20.o1" to "為了留檔",
    "q.m14#20.o2" to "為了顯得專業",
    "q.m14#20.o3" to "因為規定",
    "q.m14#20.e" to "檢查表的作用不是替代判斷，而是保證判斷所需的資訊都到齊。",
    "q.m14#21.p" to "「錨定效應」在行程中的例子是？",
    "q.m14#21.o0" to "把「計劃 6 小時到營地」當成標準，忽略實際路況",
    "q.m14#21.o1" to "相信嚮導",
    "q.m14#21.o2" to "看地圖",
    "q.m14#21.o3" to "量體溫",
    "q.m14#21.e" to "一旦有了錨點，後續判斷都會圍繞它調整。用實際進度而不是計劃值做依據。",
    "q.m14#22.p" to "記錄決策（時間、依據、結論）的價值是？",
    "q.m14#22.o0" to "讓覆盤有據可依，也讓隊伍對同一事實有共同理解",
    "q.m14#22.o1" to "為了報告",
    "q.m14#22.o2" to "為了保險",
    "q.m14#22.o3" to "為了寫書",
    "q.m14#22.e" to "沒有記錄，覆盤會變成「各說各話」。寫下時間線，能看清哪個節點本可以更早決定。",
    "q.m14#23.p" to "「專家光環」會帶來什麼具體風險？",
    "q.m14#23.o0" to "沒人敢質疑明顯錯誤，錯誤被順利執行",
    "q.m14#23.o1" to "專家會累",
    "q.m14#23.o2" to "專家收費高",
    "q.m14#23.o3" to "專家不熟悉路線",
    "q.m14#23.e" to "光環壓制的是「資訊上浮」。隊伍裡最危險的狀態不是沒人懂，而是沒人敢說。",
    "q.l35#0.p" to "雪崩埋壓最主要死因是？",
    "q.l35#0.o0" to "窒息（佔 65–100%）",
    "q.l35#0.o1" to "創傷",
    "q.l35#0.o2" to "低溫",
    "q.l35#0.o3" to "失血",
    "q.l35#0.e" to "這一條直接決定處置順序：先保證氣道與通氣，再談迴圈與復溫。",
    "q.l35#1.p" to "完全埋壓與部分埋壓的存活率，2023 年彙總口徑大致是？",
    "q.l35#1.o0" to "約 48% 與 96%",
    "q.l35#1.o1" to "約 80% 與 90%",
    "q.l35#1.o2" to "約 20% 與 60%",
    "q.l35#1.o3" to "都在 50% 左右",
    "q.l35#1.e" to "兩組數字差一倍以上，說明「頭露在外面」與「整個人被埋」是完全不同的處境。",
    "q.l35#2.p" to "存活曲線的「生存期」大約指埋壓後多久？",
    "q.l35#2.o0" to "前 18 分鐘",
    "q.l35#2.o1" to "前 5 分鐘",
    "q.l35#2.o2" to "18–35 分鐘",
    "q.l35#2.o3" to "90 分鐘以後",
    "q.l35#2.e" to "生存期內的死亡主要來自創傷，氣道通常還通。這也是「18 分鐘」被反覆強調的原因。",
    "q.l35#3.p" to "「窒息期」的曲線特徵是？",
    "q.l35#3.o0" to "存活率陡降，是救援窗口最緊張的一段",
    "q.l35#3.o1" to "曲線平緩",
    "q.l35#3.o2" to "存活率回升",
    "q.l35#3.o3" to "與低溫無關",
    "q.l35#3.e" to "18–35 分鐘的陡降來自氣道被雪堵住與氣袋氧氣耗盡。夥伴救援的價值幾乎全在這段時間裡。",
    "q.l35#4.p" to "「潛伏期」（約 35–90 分鐘）存活率相對平緩，原因是？",
    "q.l35#4.o0" to "有氣袋、氣道通暢的人進入低溫保護狀態，代謝下降",
    "q.l35#4.o1" to "雪融化了",
    "q.l35#4.o2" to "救援到了",
    "q.l35#4.o3" to "創傷恢復",
    "q.l35#4.e" to "低溫在這裡是「保護」而不是「威脅」。這也是為什麼不能簡單地把「埋了很久」等同於「沒機會」。",
    "q.l35#5.p" to "低溫致死在雪崩死亡中佔的比例是？",
    "q.l35#5.o0" to "0–4%",
    "q.l35#5.o1" to "20–30%",
    "q.l35#5.o2" to "50%",
    "q.l35#5.o3" to "幾乎全部",
    "q.l35#5.e" to "比例很低，但個案確實存在。它提醒我們：先通氣、後復溫，順序不能反。",
    "q.l35#6.p" to "雪崩發生後 0–2 分鐘，最優先的動作是？",
    "q.l35#6.o0" to "確認二次雪崩風險、指定安全觀察員、記錄時間與最後目擊點",
    "q.l35#6.o1" to "立刻開始挖",
    "q.l35#6.o2" to "拍照記錄",
    "q.l35#6.o3" to "呼叫家屬",
    "q.l35#6.e" to "沒有觀察員，救援隊可能成為第二批被埋者；沒有時間記錄，後面的 60 分鐘規則無法執行。",
    "q.l35#7.p" to "2–10 分鐘階段的目標是什麼？",
    "q.l35#7.o0" to "儘快「接觸到人」，而不是把雪全部挖開",
    "q.l35#7.o1" to "挖出一條標準通道",
    "q.l35#7.o2" to "把裝備收好",
    "q.l35#7.o3" to "等待專業隊",
    "q.l35#7.e" to "接觸面部就能開始通氣，這比「完整挖出」早幾分鐘，而幾分鐘在窒息期裡就是生死差別。",
    "q.l35#8.p" to "挖到面部後的前 60 秒，順序正確的是？",
    "q.l35#8.o0" to "清口鼻的雪與碎冰 → 查生命體徵 → 無呼吸立即給救援呼吸",
    "q.l35#8.o1" to "先拉出身體 → 再清口鼻",
    "q.l35#8.o2" to "先拍照 → 再施救",
    "q.l35#8.o3" to "先喂熱水",
    "q.l35#8.e" to "先清氣道再談其他。把人直接拉出來既可能加重脊柱損傷，也會把雪推進口鼻。",
    "q.l35#9.p" to "「45 分鐘存活率 25%，高於 40 分鐘的 18%」，正確理解是？",
    "q.l35#9.o0" to "樣本量小、有氣袋者比例不同造成的波動，不是曲線反彈",
    "q.l35#9.o1" to "說明 45 分鐘更安全",
    "q.l35#9.o2" to "說明應該等到 45 分鐘",
    "q.l35#9.o3" to "資料錯了",
    "q.l35#9.e" to "教學要講趨勢，不要拿單點數字做絕對承諾。把波動當規律，會得出荒謬的結論。",
    "q.l35#10.p" to "所有完全埋壓者挖出後看起來正常，應該？",
    "q.l35#10.o0" to "仍然送醫觀察",
    "q.l35#10.o1" to "直接回營地",
    "q.l35#10.o2" to "繼續當天行程",
    "q.l35#10.o3" to "自己走下山",
    "q.l35#10.e" to "缺氧與低溫的後果可能延遲出現。觀察與評估需要裝置與時間，營地裡做不到。",
    "q.l35#11.p" to "雪崩現場必須記錄的資訊包括？",
    "q.l35#11.o0" to "目擊時間或最後已知時間",
    "q.l35#11.o1" to "最後目擊點",
    "q.l35#11.o2" to "埋壓人數",
    "q.l35#11.o3" to "救援人員的姓名",
    "q.l35#11.e" to "前三條直接決定搜尋範圍與醫學決策。救援者姓名屬於事後記錄，不影響現場判斷。",
    "q.l35#12.p" to "挖出之後必須同時處理的方面包括？",
    "q.l35#12.o0" to "脊柱保護，避免粗暴搬動",
    "q.l35#12.o1" to "全身保溫、脫去溼衣、隔絕地面",
    "q.l35#12.o2" to "持續監測心律與核心溫度",
    "q.l35#12.o3" to "讓傷者自己站起來活動",
    "q.l35#12.e" to "前三項是標準處置。讓傷者自行活動會加重低溫與潛在脊柱損傷。",
    "q.l35#13.p" to "哪些屬於「不該用來決定救不救」的因素？",
    "q.l35#13.o0" to "埋壓深度",
    "q.l35#13.o1" to "氣袋有無",
    "q.l35#13.o2" to "雪的密度",
    "q.l35#13.o3" to "氣道是否被完全填滿",
    "q.l35#13.e" to "前三項影響挖掘時間，不影響醫學決策。只有氣道狀態與時間、溫度參與分流。",
    "q.l35#14.p" to "把雪崩現場的前十分鐘排成正確順序。",
    "q.l35#14.o0" to "確認二次雪崩與落石風險，指定安全觀察員",
    "q.l35#14.o1" to "記錄時間與最後目擊點，呼叫救援",
    "q.l35#14.o2" to "信標搜尋並探測定位",
    "q.l35#14.o3" to "開始挖掘，目標是儘快接觸到面部",
    "q.l35#14.e" to "順序背後的邏輯是「先別讓救援變成第二起事故」，然後是「讓後續判斷有據可依」。",
    "q.l35#15.p" to "把挖到面部之後的處置順序排好。",
    "q.l35#15.o0" to "清口鼻的雪與碎冰，評估氣道",
    "q.l35#15.o1" to "1 分鐘內檢查生命體徵",
    "q.l35#15.o2" to "無呼吸立即給救援呼吸",
    "q.l35#15.o3" to "按 60 分鐘規則分流並安排轉運",
    "q.l35#15.e" to "通氣要早於「完整挖出」，也早於搬運。這一條在實操裡最容易被做反。",
    "q.l35#16.p" to "雪崩埋壓的主要死因是窒息，佔全部死亡的 ______–100%。",
    "q.l35#16.a0" to "65",
    "q.l35#16.e" to "65–100% 這個區間來自九項研究。它解釋了為什麼「先通氣」是鐵律。",
    "q.l35#17.p" to "存活曲線裡被反覆強調的「黃金 ______ 分鐘」，指的是窒息期開始前的時間窗。",
    "q.l35#17.a0" to "18",
    "q.l35#17.a1" to "十八",
    "q.l35#17.e" to "18 分鐘是統計上的陡降點。它不是魔法數字，但足夠用來做訓練目標。",
    "q.l35#18.p" to "低溫致死只佔雪崩死亡的 ______–4%。",
    "q.l35#18.a0" to "0",
    "q.l35#18.e" to "0–4%。比例雖低，卻解釋了「長時間埋壓仍可救」的少數個案。",
    "q.l35#19.p" to "把存活曲線的四段與它的特徵對應起來。",
    "q.l35#19.l0" to "生存期（0–18 分鐘）",
    "q.l35#19.l1" to "窒息期（18–35 分鐘）",
    "q.l35#19.l2" to "潛伏期（35–90 分鐘）",
    "q.l35#19.l3" to "長時間期（90 分鐘以上）",
    "q.l35#19.r0" to "死亡多來自創傷，氣道通常通暢",
    "q.l35#19.r1" to "存活率陡降，救援窗口最緊張",
    "q.l35#19.r2" to "有氣袋者進入低溫保護，曲線平緩",
    "q.l35#19.r3" to "以低溫為主，偶有極長埋壓生還",
    "q.l35#19.e" to "四段對應四種死因結構。把曲線講成四個階段，比記單個百分比更有用。",
    "q.l35#20.p" to "把死因與它的佔比對應起來。",
    "q.l35#20.l0" to "窒息",
    "q.l35#20.l1" to "創傷",
    "q.l35#20.l2" to "低溫",
    "q.l35#20.r0" to "65–100%",
    "q.l35#20.r1" to "5–29%",
    "q.l35#20.r2" to "0–4%",
    "q.l35#20.e" to "這組比例是處置優先順序的來源：通氣 > 止血固定 > 復溫。",
    "q.l35#21.p" to "隊伍沒有指定安全觀察員就開始挖人，最大的風險是？",
    "q.l35#21.o0" to "二次雪崩把救援者也埋掉",
    "q.l35#21.o1" to "挖得慢",
    "q.l35#21.o2" to "繩子不夠",
    "q.l35#21.o3" to "沒有記錄",
    "q.l35#21.e" to "雪崩很少只發生一次。觀察員是唯一能在第二次來臨時喊停的人。",
    "q.l35#22.p" to "為什麼不能「一挖到人就拉出來」？",
    "q.l35#22.o0" to "可能加重脊柱損傷，也可能把雪推進口鼻",
    "q.l35#22.o1" to "會弄壞衣服",
    "q.l35#22.o2" to "會耽誤拍照",
    "q.l35#22.o3" to "會嚇到傷者",
    "q.l35#22.e" to "先清臉、清氣道、確認頭頸位置，再清胸與身體。順序錯了，救出來也可能是癱瘓。",
    "q.l35#23.p" to "如果現場只有你一個人，應該先挖還是先呼救？",
    "q.l35#23.o0" to "先挖，救援窗口比任何響應時間都短；有機會再發訊號",
    "q.l35#23.o1" to "先打電話",
    "q.l35#23.o2" to "先回營地叫人",
    "q.l35#23.o3" to "先拍影片",
    "q.l35#23.e" to "單獨一人時，等待救援幾乎等於放棄。發出訊號的時機可以稍後找，挖掘不能等。",
    "q.l35#24.p" to "關於「埋壓時間」的記錄，為什麼必須精確到分鐘？",
    "q.l35#24.o0" to "它決定後續復甦分流採用哪一條規則",
    "q.l35#24.o1" to "為了寫報告",
    "q.l35#24.o2" to "為了保險理賠",
    "q.l35#24.o3" to "為了統計",
    "q.l35#24.e" to "60 分鐘是分流的分界線，而現場往往只能靠目擊時間推算。少記十分鐘，判斷就會走入另一條路徑。",
    "q.l35#25.p" to "為什麼說「埋得深」不等於「沒希望」？",
    "q.l35#25.o0" to "埋深影響挖掘時間，而醫學決策看的是時間、氣道與溫度",
    "q.l35#25.o1" to "因為雪會化",
    "q.l35#25.o2" to "因為人多",
    "q.l35#25.o3" to "因為深埋者更冷",
    "q.l35#25.e" to "把埋深當醫學判據，會讓人提前放棄。埋深只改變你挖多久，不改變你該做什麼。",
    "q.l36#0.p" to "2023 版 ICAR MedCom 的埋壓時間決策線是？",
    "q.l36#0.o0" to "60 分鐘",
    "q.l36#0.o1" to "35 分鐘",
    "q.l36#0.o2" to "90 分鐘",
    "q.l36#0.o3" to "120 分鐘",
    "q.l36#0.e" to "2013 版用的是 35 分鐘，2023 年更新為 60 分鐘。寫教材必須標註年份與口徑。",
    "q.l36#1.p" to "埋壓 25 分鐘、無生命體徵、氣道被散雪部分阻塞（未完全填滿），應該？",
    "q.l36#1.o0" to "按窒息處理：先清口鼻並儘快給救援呼吸，同時開始按壓",
    "q.l36#1.o1" to "按梗阻處理，放棄復甦",
    "q.l36#1.o2" to "先復溫",
    "q.l36#1.o3" to "等待專業隊",
    "q.l36#1.e" to "≤60 分鐘一律按窒息處理，不論氣道是否通暢。散雪不等於梗阻，梗阻要求「完全填滿」。",
    "q.l36#2.p" to "埋壓 70 分鐘、無生命體徵、氣道通暢、無法測核心溫度，應該？",
    "q.l36#2.o0" to "按低溫性心搏驟停處理，開始心肺復甦並轉運",
    "q.l36#2.o1" to "按窒息處理，不復蘇",
    "q.l36#2.o2" to "等待測溫再決定",
    "q.l36#2.o3" to "只做保暖",
    "q.l36#2.e" to "氣道通暢 + 超過 60 分鐘 = 低溫性驟停的可能性足夠高，應當復甦。低溫心臟「沒暖過來不算死」。",
    "q.l36#3.p" to "埋壓 70 分鐘、無生命體徵、口鼻被壓實雪完全填滿、現場無法測溫，應該？",
    "q.l36#3.o0" to "按窒息性心搏驟停處理，不開始心肺復甦",
    "q.l36#3.o1" to "立即開始按壓",
    "q.l36#3.o2" to "先挖出再判斷",
    "q.l36#3.o3" to "給兩次呼吸後放棄",
    "q.l36#3.e" to "這是 2023 版明確列出的「可以不開始復甦」情形。若能測溫且 <30 ℃，則改為嘗試復甦。",
    "q.l36#4.p" to "核心溫度測到 28 ℃、氣道通暢、無生命體徵、埋壓 80 分鐘，應該？",
    "q.l36#4.o0" to "嘗試復甦並轉運到有體外迴圈復溫能力的醫院",
    "q.l36#4.o1" to "放棄復甦",
    "q.l36#4.o2" to "只做保暖",
    "q.l36#4.o3" to "等體溫回升再判斷",
    "q.l36#4.e" to "<30 ℃ + 氣道通暢，不論埋壓多久都應嘗試復甦。這類傷者需要 ECLS 級別的復溫條件。",
    "q.l36#5.p" to "「氣道梗阻」在雪崩救援裡的定義是？",
    "q.l36#5.o0" to "口鼻被壓實雪或碎屑完全填滿",
    "q.l36#5.o1" to "嘴裡有一點雪",
    "q.l36#5.o2" to "有痰",
    "q.l36#5.o3" to "鼻腔出血",
    "q.l36#5.e" to "定義必須嚴格，因為它直接決定是否開始復甦。不確定時按通暢處理，這是偏向救人的預設值。",
    "q.l36#6.p" to "關於氣袋（air pocket），正確的說法是？",
    "q.l36#6.o0" to "有氣袋存活率更高，但氣袋不是判斷救不救的依據",
    "q.l36#6.o1" to "沒有氣袋就不用救",
    "q.l36#6.o2" to "有氣袋就一定活",
    "q.l36#6.o3" to "氣袋決定是否梗阻",
    "q.l36#6.e" to "2023 版明確：氣袋有無、雪密度、埋深都不應改變處置。它們影響的是時間，不是決策。",
    "q.l36#7.p" to "胸外按壓什麼時候可以開始？",
    "q.l36#7.o0" to "不必等完全挖出，露出胸部即可開始",
    "q.l36#7.o1" to "必須等全身挖出",
    "q.l36#7.o2" to "必須等送到醫院",
    "q.l36#7.o3" to "必須等測到體溫",
    "q.l36#7.e" to "「等挖出來再按」會白白浪費幾分鐘。2023 版明確：姿勢異常、尚未脫離雪埋時也可以有效按壓。",
    "q.l36#8.p" to "救援呼吸為什麼要儘早給？",
    "q.l36#8.o0" to "這類傷者絕大多數死於窒息，缺氧是第一問題",
    "q.l36#8.o1" to "因為方便",
    "q.l36#8.o2" to "為了安撫家屬",
    "q.l36#8.o3" to "為了節省氧氣",
    "q.l36#8.e" to "先通氣、再談迴圈。這也是「≤60 分鐘不論氣道」這條規則的生理基礎。",
    "q.l36#9.p" to "停止復甦的指徵通常包括？",
    "q.l36#9.o0" to "致命傷、完全凍結、氣道梗阻且埋壓超過 60 分鐘、血鉀明顯升高",
    "q.l36#9.o1" to "家屬要求",
    "q.l36#9.o2" to "天黑",
    "q.l36#9.o3" to "裝備不足",
    "q.l36#9.e" to "這組指徵來自 2023 版與 ICAR 終止復甦建議。判斷權在受過訓練的人員，不在挖掘者。",
    "q.l36#10.p" to "「先看埋了多深，再決定救不救」這句話錯在哪？",
    "q.l36#10.o0" to "埋深影響挖掘時間，不參與醫學決策",
    "q.l36#10.o1" to "埋深無法測量",
    "q.l36#10.o2" to "埋深總是很淺",
    "q.l36#10.o3" to "埋深決定存活率",
    "q.l36#10.e" to "把工程問題當醫學判據，會讓人提前放棄。決策只看時間、氣道與溫度。",
    "q.l36#11.p" to "按 2023 版，參與分流判斷的要素包括？",
    "q.l36#11.o0" to "埋壓時間",
    "q.l36#11.o1" to "氣道是否通暢",
    "q.l36#11.o2" to "能否測到核心溫度及其數值",
    "q.l36#11.o3" to "埋壓深度",
    "q.l36#11.e" to "前三項構成決策樹。第四項隻影響你要挖多久，不改變分流。",
    "q.l36#12.p" to "低溫性心搏驟停的處置要點包括？",
    "q.l36#12.o0" to "輕柔搬動，避免劇烈顛簸",
    "q.l36#12.o1" to "全身絕緣保溫",
    "q.l36#12.o2" to "持續監測心律與核心溫度",
    "q.l36#12.o3" to "儘快現場復溫到 35 ℃ 再轉運",
    "q.l36#12.e" to "現場做不到有效復溫，硬要「先暖再走」反而延誤。目標是儘快送到有 ECLS 的中心。",
    "q.l36#13.p" to "關於氣道與通氣，正確的做法包括？",
    "q.l36#13.o0" to "清口鼻的雪與碎冰",
    "q.l36#13.o1" to "不確定是否梗阻時按通暢處理",
    "q.l36#13.o2" to "先通氣再考慮按壓",
    "q.l36#13.o3" to "等完全挖出再評估氣道",
    "q.l36#13.e" to "前三項都指向「儘早通氣」。最後一項會延誤最關鍵的那幾分鐘。",
    "q.l36#14.p" to "把「≤60 分鐘、無生命體徵」的處置順序排好。",
    "q.l36#14.o0" to "清口鼻，評估氣道",
    "q.l36#14.o1" to "立即給救援呼吸",
    "q.l36#14.o2" to "開始胸外按壓",
    "q.l36#14.o3" to "保溫、脊柱保護並安排轉運",
    "q.l36#14.e" to "通氣優先於按壓，這是雪崩窒息性驟停與普通心源性驟停最大的不同。",
    "q.l36#15.p" to "把「>60 分鐘」的分流判斷順序排好。",
    "q.l36#15.o0" to "確認埋壓時間確實超過 60 分鐘",
    "q.l36#15.o1" to "評估氣道是否被完全填滿",
    "q.l36#15.o2" to "嘗試測量核心溫度",
    "q.l36#15.o3" to "按對應分支決定是否開始復甦",
    "q.l36#15.e" to "順序體現「先時間、再氣道、後溫度」。三步裡任何一步資訊缺失，都按更傾向救人的分支處理。",
    "q.l36#16.p" to "2023 版 ICAR MedCom 的復甦決策線是埋壓 ______ 分鐘。",
    "q.l36#16.a0" to "60",
    "q.l36#16.e" to "舊版 35 分鐘已廢止。教材與題庫必須統一到 60 分鐘。",
    "q.l36#17.p" to "核心溫度低於 ______ ℃ 且氣道通暢時，不論埋壓多久都應嘗試復甦。",
    "q.l36#17.a0" to "30",
    "q.l36#17.e" to "30 ℃ 是並行判據。它把「低溫保護」的窗口納入了決策。",
    "q.l36#18.p" to "雪崩死因中低溫只佔 0–4%，所以處置順序是先 ______、後復溫。",
    "q.l36#18.a0" to "通氣",
    "q.l36#18.a1" to "氣道",
    "q.l36#18.a2" to "保證氣道",
    "q.l36#18.e" to "先通氣再復溫，這條順序在雪崩救援裡比在普通低溫症裡更嚴格。",
    "q.l36#19.p" to "把埋壓情形與處置對應起來（2023 版）。",
    "q.l36#19.l0" to "≤60 分鐘、無生命體徵",
    "q.l36#19.l1" to ">60 分鐘、氣道通暢、無法測溫",
    "q.l36#19.l2" to ">60 分鐘、氣道梗阻、無法測溫",
    "q.l36#19.l3" to "可測溫且 <30 ℃、氣道通暢",
    "q.l36#19.r0" to "按窒息處理，儘快給救援呼吸",
    "q.l36#19.r1" to "按低溫性驟停處理，開始復甦",
    "q.l36#19.r2" to "按窒息性驟停處理，不開始復甦",
    "q.l36#19.r3" to "不論多久都嘗試復甦並轉運 ECLS",
    "q.l36#19.e" to "四條分支覆蓋了絕大多數現場情形。記住分支條件比背結論更可靠。",
    "q.l36#20.p" to "把「可以停止復甦」的指徵與它的含義對應起來。",
    "q.l36#20.l0" to "致命傷",
    "q.l36#20.l1" to "完全凍結",
    "q.l36#20.l2" to "氣道梗阻且 >60 分鐘",
    "q.l36#20.l3" to "血鉀明顯升高",
    "q.l36#20.r0" to "傷情本身不可救",
    "q.l36#20.r1" to "身體呈凍結狀態，復溫無意義",
    "q.l36#20.r2" to "按窒息性驟停處理，不開始復甦",
    "q.l36#20.r3" to "提示長時間缺氧，預後極差",
    "q.l36#20.e" to "四項都是「醫學上已無逆轉可能」的證據。判斷應由受訓人員完成，並記錄依據。",
    "q.l36#21.p" to "現場有人主張「超過 35 分鐘就別救了」，你會怎麼回應？",
    "q.l36#21.o0" to "那是 2013 版口徑，2023 版已改為 60 分鐘並加入溫度判據",
    "q.l36#21.o1" to "他說得對",
    "q.l36#21.o2" to "看情況",
    "q.l36#21.o3" to "讓他決定",
    "q.l36#21.e" to "中文資料裡 35 分鐘仍大量存在。更新口徑是這類課程最實際的價值之一。",
    "q.l36#22.p" to "情景：埋壓 20 分鐘，挖出時無呼吸，口鼻內有散雪但未完全填滿。最該做的是？",
    "q.l36#22.o0" to "清口鼻、給救援呼吸、開始按壓，儘快轉運",
    "q.l36#22.o1" to "判定為梗阻，不復蘇",
    "q.l36#22.o2" to "先復溫",
    "q.l36#22.o3" to "等專業隊判斷",
    "q.l36#22.e" to "≤60 分鐘 + 非完全梗阻 = 按窒息處理，全力復甦。散雪不構成梗阻。",
    "q.l36#23.p" to "情景：埋壓 70 分鐘，氣道通暢，核心溫度 28 ℃，無生命體徵。最該做的是？",
    "q.l36#23.o0" to "持續復甦、輕柔搬動、全身保溫，轉運到能 ECLS 復溫的醫院",
    "q.l36#23.o1" to "停止復甦",
    "q.l36#23.o2" to "只做保溫觀察",
    "q.l36#23.o3" to "先復溫到 35 ℃ 再轉運",
    "q.l36#23.e" to "低溫性驟停的核心是「送到能復溫的地方」，途中復甦不能停。",
    "q.l36#24.p" to "為什麼說「低溫心臟很敏感」？",
    "q.l36#24.o0" to "劇烈搬動可能誘發室顫，所以要輕柔、水平搬運",
    "q.l36#24.o1" to "因為怕冷",
    "q.l36#24.o2" to "因為心率慢",
    "q.l36#24.o3" to "因為血壓低",
    "q.l36#24.e" to "這是低溫傷者搬運要「平、穩、輕」的原因，也是雪崩救援裡反覆強調脊柱保護之外的另一層理由。",
    "q.l36#25.p" to "一名隊員在救援中情緒崩潰、堅持要停止復甦，領隊應該？",
    "q.l36#25.o0" to "讓他退出操作但繼續復甦，由受訓人員按指徵判斷",
    "q.l36#25.o1" to "立即停止",
    "q.l36#25.o2" to "批評他",
    "q.l36#25.o3" to "讓他繼續按壓",
    "q.l36#25.e" to "情緒需要被接住，但醫學決策不能由情緒決定。換人而不是停手，是更負責的處理。",
    "q.l37#0.p" to "雪崩搜尋的四個階段，順序是？",
    "q.l37#0.o0" to "訊號與線索搜尋 → 粗搜 → 細搜 → 定點探測",
    "q.l37#0.o1" to "粗搜 → 細搜 → 定點探測 → 訊號搜尋",
    "q.l37#0.o2" to "定點探測 → 細搜 → 粗搜",
    "q.l37#0.o3" to "搜尋 → 挖掘 → 探測",
    "q.l37#0.e" to "四階段是「逐步收斂」的過程：從整面坡，到幾公尺，到雪面一點，到具體深度。跳過任何一段都會浪費時間。",
    "q.l37#1.p" to "信標搜尋帶的間距通常取多少？",
    "q.l37#1.o0" to "約 40 公尺，與碎屑邊緣約 20 公尺",
    "q.l37#1.o1" to "10 公尺",
    "q.l37#1.o2" to "80 公尺",
    "q.l37#1.o3" to "越寬越好",
    "q.l37#1.e" to "40 公尺是教學預設值，不是裝置上限。訓練水平不確定時縮到 30 公尺，寧可多走幾趟。",
    "q.l37#2.p" to "搜尋開始前，全隊最該做的一件事是？",
    "q.l37#2.o0" to "所有人把信標切到接收模式，並關掉手機與相機等干擾源",
    "q.l37#2.o1" to "先挖一個試坑",
    "q.l37#2.o2" to "先拍照",
    "q.l37#2.o3" to "先收繩子",
    "q.l37#2.e" to "還有人在傳送模式，搜尋就會失效；電子裝置干擾會縮小有效距離。這兩件事必須在第一步做完。",
    "q.l37#3.p" to "訊號搜尋階段，最先關注什麼？",
    "q.l37#3.o0" to "雪面上的可見線索（手套、杖尖、揹包帶）",
    "q.l37#3.o1" to "信標讀數",
    "q.l37#3.o2" to "雪層結構",
    "q.l37#3.o3" to "風向",
    "q.l37#3.e" to "表面線索可能直接把搜尋範圍縮小到幾十公尺。低頭看信標反而會漏掉這些線索。",
    "q.l37#4.p" to "粗搜階段的目標是把距離縮到多少？",
    "q.l37#4.o0" to "3–5 公尺",
    "q.l37#4.o1" to "20 公尺",
    "q.l37#4.o2" to "0.5 公尺",
    "q.l37#4.o3" to "10–15 公尺",
    "q.l37#4.e" to "3–5 公尺之後才進入細搜。這一步是「從跑改成走」的節點，也是精度開始重要的地方。",
    "q.l37#5.p" to "粗搜時發現距離讀數變大，說明？",
    "q.l37#5.o0" to "方向反了，應原路退回",
    "q.l37#5.o1" to "訊號太強",
    "q.l37#5.o2" to "裝置壞了",
    "q.l37#5.o3" to "被埋者移動了",
    "q.l37#5.e" to "信標讀數是「距離」，變大就是走錯方向。這個判斷要快，不要在原地反覆確認。",
    "q.l37#6.p" to "細搜階段的正確動作是？",
    "q.l37#6.o0" to "把信標貼近雪面，做十字交叉，找讀數最小的點並標記",
    "q.l37#6.o1" to "站著轉圈",
    "q.l37#6.o2" to "沿坡向下直線走",
    "q.l37#6.o3" to "用探杆亂插",
    "q.l37#6.e" to "貼地能減少訊號在雪中的折射誤差。標記最低點是為了讓探杆有一個明確的起點。",
    "q.l37#7.p" to "定點探測時，探杆應該與什麼成 90 度？",
    "q.l37#7.o0" to "與雪面（坡面）成 90 度",
    "q.l37#7.o1" to "與水平面成 90 度",
    "q.l37#7.o2" to "與坡面成 45 度",
    "q.l37#7.o3" to "隨意角度",
    "q.l37#7.e" to "坡面上「垂直向下」會讓探杆斜著穿過雪層，深度讀數被坡角放大。夥伴救援按與雪面 90 度插。",
    "q.l37#8.p" to "一次沒探到，接下來應該？",
    "q.l37#8.o0" to "以 25 公分見方的網格向外擴充套件",
    "q.l37#8.o1" to "換更長的探杆",
    "q.l37#8.o2" to "直接用雪鏟挖",
    "q.l37#8.o3" to "放棄這個點",
    "q.l37#8.e" to "25 公分（約 10 英寸）是標準網格。網格太大會漏，太小會浪費時間。",
    "q.l37#9.p" to "探到硬物之後，怎麼判斷是不是人？",
    "q.l37#9.o0" to "找「軟、有彈性、像身體」的阻力，並對比周圍地面深度",
    "q.l37#9.o1" to "只要探到硬的就挖",
    "q.l37#9.o2" to "看探杆有沒有血跡",
    "q.l37#9.o3" to "聽聲音",
    "q.l37#9.e" to "岩石與冰塊是硬而脆的阻力；人體有彈性。另外被埋者通常不會比周圍地面更深。",
    "q.l37#10.p" to "探到之後，探杆應該怎麼處理？",
    "q.l37#10.o0" to "留在原地不拔出，作為位置與深度標記",
    "q.l37#10.o1" to "立刻拔出",
    "q.l37#10.o2" to "插得更深",
    "q.l37#10.o3" to "交給隊友",
    "q.l37#10.e" to "留在原地的探杆是挖掘者的「靶心」，也是判斷是否挖到正確位置的參照。",
    "q.l37#11.p" to "埋深超過探杆長度時，正確的做法是？",
    "q.l37#11.o0" to "先挖掉約 1 公尺，再用信標重新定位，再探",
    "q.l37#11.o1" to "繼續硬探",
    "q.l37#11.o2" to "放棄",
    "q.l37#11.o3" to "換人探",
    "q.l37#11.e" to "硬探沒有意義，因為探不到底。先縮短距離再重新定位，是唯一有效的流程。",
    "q.l37#12.p" to "為什麼組織化救援的探杆要保持垂直（而不是垂直雪面）？",
    "q.l37#12.o0" to "便於統一不同隊員的深度讀數、形成一致的探測面",
    "q.l37#12.o1" to "因為更省力",
    "q.l37#12.o2" to "因為更快",
    "q.l37#12.o3" to "因為標準如此",
    "q.l37#12.e" to "組織化探線是一條「面」，需要可比的深度資料。夥伴救援只針對一個點，所以垂直於雪面更準。",
    "q.l37#13.p" to "出發前對信標的檢查包括？",
    "q.l37#13.o0" to "電池電量充足",
    "q.l37#13.o1" to "做一次傳送測試",
    "q.l37#13.o2" to "會切接收、會標記與抑制",
    "q.l37#13.o3" to "貼身佩戴，不放在包底",
    "q.l37#13.e" to "四項缺一都會在關鍵時刻失效。放包底是最常見的錯誤——包被埋或掉落，信標也就沒了。",
    "q.l37#14.p" to "探杆的檢查要點包括？",
    "q.l37#14.o0" to "長度按當地雪深選擇",
    "q.l37#14.o1" to "拉繩與鎖釦完好",
    "q.l37#14.o2" to "能單手展開並鎖定",
    "q.l37#14.o3" to "越輕越好",
    "q.l37#14.e" to "救援隊探杆建議至少 3 公尺（UIAA 157）；個人常用 240–320 公分。輕是好事，但強度與鎖定可靠更重要。",
    "q.l37#15.p" to "多人同時被埋時，正確的做法包括？",
    "q.l37#15.o0" to "先標記或抑制第一個訊號",
    "q.l37#15.o1" to "再搜尋第二個訊號",
    "q.l37#15.o2" to "不要在一個訊號上反覆確認而放棄其他區域",
    "q.l37#15.o3" to "只救最近的那個",
    "q.l37#15.e" to "多人埋壓時最大的風險是「只找到一個」。標記與抑制功能就是為此設計的。",
    "q.l37#16.p" to "把一次完整搜尋排成正確順序。",
    "q.l37#16.o0" to "全隊切接收、關閉干擾源",
    "q.l37#16.o1" to "沿搜尋帶做訊號搜尋",
    "q.l37#16.o2" to "粗搜到 3–5 公尺",
    "q.l37#16.o3" to "細搜找最低讀數點並標記",
    "q.l37#16.o4" to "定點探測並留杆",
    "q.l37#16.e" to "五步是從「面」到「點」的收斂過程。任何一步想省，都會在下一步加倍付出。",
    "q.l37#17.p" to "把定點探測的操作順序排好。",
    "q.l37#17.o0" to "從最低讀數點開始，探杆與雪面成 90 度",
    "q.l37#17.o1" to "未探到則按 25 公分網格擴充套件",
    "q.l37#17.o2" to "探到有彈性的阻力後停止",
    "q.l37#17.o3" to "留杆標記，開始挖掘",
    "q.l37#17.e" to "順序裡最容易錯的是最後一步：很多人一探到就拔杆，結果挖掘失去參照。",
    "q.l37#18.p" to "信標搜尋帶間距約 ______ 公尺。",
    "q.l37#18.a0" to "40",
    "q.l37#18.e" to "不確定時縮到 30 公尺。帶太寬會漏訊號，這是搜尋失敗最常見的原因。",
    "q.l37#19.p" to "定點探測的網格邊長是 ______ 公分。",
    "q.l37#19.a0" to "25",
    "q.l37#19.e" to "約 10 英寸。網格太大會漏掉人體，太小則浪費時間。",
    "q.l37#20.p" to "夥伴救援的探杆應與 ______ 成 90 度插入。",
    "q.l37#20.a0" to "雪面",
    "q.l37#20.a1" to "坡面",
    "q.l37#20.e" to "與水平面垂直會讓深度讀數被坡角放大，這是新手最常犯的幾何錯誤。",
    "q.l37#21.p" to "把搜尋階段與它的目標對應起來。",
    "q.l37#21.l0" to "訊號與線索搜尋",
    "q.l37#21.l1" to "粗搜",
    "q.l37#21.l2" to "細搜",
    "q.l37#21.l3" to "定點探測",
    "q.l37#21.r0" to "找到第一個訊號",
    "q.l37#21.r1" to "把距離縮到 3–5 公尺",
    "q.l37#21.r2" to "找到雪面上離被埋者最近的點",
    "q.l37#21.r3" to "用探杆確認位置與深度",
    "q.l37#21.e" to "四個目標層層收斂。記目標比記動作更能適應不同地形。",
    "q.l37#22.p" to "把裝備與它的關鍵要求對應起來。",
    "q.l37#22.l0" to "信標",
    "q.l37#22.l1" to "探杆",
    "q.l37#22.l2" to "雪鏟",
    "q.l37#22.l3" to "頭盔",
    "q.l37#22.r0" to "三天線數字款，貼身佩戴，會標記與抑制",
    "q.l37#22.r1" to "長度匹配雪深，能單手鎖定",
    "q.l37#22.r2" to "金屬刃、鏟柄可靠、能快速取出",
    "q.l37#22.r3" to "搜尋與挖掘全程佩戴",
    "q.l37#22.e" to "四件裡最容易被忽略的是頭盔：挖掘時上方還會掉雪塊與冰屑。",
    "q.l37#23.p" to "搜尋時有人停下來在第一個訊號處反覆確認，你應該？",
    "q.l37#23.o0" to "提醒他先標記/抑制，繼續覆蓋其餘區域",
    "q.l37#23.o1" to "讓他繼續",
    "q.l37#23.o2" to "一起停下來",
    "q.l37#23.o3" to "放棄搜尋",
    "q.l37#23.e" to "多人埋壓時，「先把所有訊號找到」比「把一個點確認到極致」更重要。",
    "q.l37#24.p" to "為什麼搜尋階段要求「關掉手機與相機」？",
    "q.l37#24.o0" to "電子裝置會干擾信標訊號，縮短有效搜尋距離",
    "q.l37#24.o1" to "為了省電",
    "q.l37#24.o2" to "為了安靜",
    "q.l37#24.o3" to "為了防止拍照",
    "q.l37#24.e" to "干擾會讓搜尋帶的有效寬度變小，間接導致漏搜。這條在執行時最常被打折扣。",
    "q.l37#25.p" to "隊伍只有兩個人，一人搜尋一人挖掘，這個分工合理嗎？",
    "q.l37#25.o0" to "合理，但探到後兩人應接力挖掘，不要一人硬挖",
    "q.l37#25.o1" to "不合理，應該兩人一起搜",
    "q.l37#25.o2" to "不合理，應該等待救援",
    "q.l37#25.o3" to "合理，且不需要輪換",
    "q.l37#25.e" to "兩人組的關鍵是「探到即接力」。單人持續挖掘會在幾分鐘內力竭，效率反而更低。",
    "q.l37#26.p" to "搜尋前發現雪崩碎屑區還有上方懸雪，應該？",
    "q.l37#26.o0" to "先指定觀察員並選擇安全接近路線，再開始搜尋",
    "q.l37#26.o1" to "直接衝進去",
    "q.l37#26.o2" to "等雪停",
    "q.l37#26.o3" to "放棄搜尋",
    "q.l37#26.e" to "救援者被二次雪崩埋掉是真實存在的事故型別。觀察員與接近路線是搜尋的一部分，不是額外步驟。",
    "q.l37#27.p" to "「10 分鐘接觸、18 分鐘挖出」這兩個目標的意義是？",
    "q.l37#27.o0" to "它們是隊伍內控指標，用來訓練與覆盤，不是保證",
    "q.l37#27.o1" to "是醫學承諾",
    "q.l37#27.o2" to "是標準規定",
    "q.l37#27.o3" to "是裝置效能",
    "q.l37#27.e" to "目標的作用是讓隊伍知道「慢在哪一步」。把它當承諾，就會在沒做到時失去判斷。",
    "q.l38#0.p" to "挖掘的第一原則是？",
    "q.l38#0.o0" to "永遠從下坡側作業",
    "q.l38#0.o1" to "從正上方往下挖",
    "q.l38#0.o2" to "從上坡側往下挖",
    "q.l38#0.o3" to "從側面平著挖",
    "q.l38#0.e" to "下坡側作業有三個好處：雪能往下拋、通道有坡度、挖掘者不在被埋者上方。",
    "q.l38#1.p" to "傳統「1.5 倍埋深」口訣描述的是？",
    "q.l38#1.o0" to "從探杆沿坡面向下退的距離",
    "q.l38#1.o1" to "通道的寬度",
    "q.l38#1.o2" to "探杆的長度",
    "q.l38#1.o3" to "挖掘的時間",
    "q.l38#1.e" to "退出的距離是為了留出運雪空間。它是經驗法則，新的研究給了替代方案。",
    "q.l38#2.p" to "2023 年雪傳送帶研究對起挖點的主張是？",
    "q.l38#2.o0" to "3 人以上、空間足夠時，直接從探杆處沿落線向下挖",
    "q.l38#2.o1" to "永遠退 1.5 倍埋深",
    "q.l38#2.o2" to "從正上方挖",
    "q.l38#2.o3" to "從側面水平挖",
    "q.l38#2.e" to "偏移起挖會延長到達頭位的時間。研究結論的前提是「人手足夠」，不能無條件套用。",
    "q.l38#3.p" to "什麼情況下才建議偏移起挖？",
    "q.l38#3.o0" to "埋深極淺且腳陷入深度接近埋深，或人手不足用單人方案",
    "q.l38#3.o1" to "任何時候",
    "q.l38#3.o2" to "雪很硬時",
    "q.l38#3.o3" to "天黑時",
    "q.l38#3.e" to "這兩種情形下偏移能減少無效搬運。其他情況下，從探杆處起挖更快。",
    "q.l38#4.p" to "傳送帶通道的寬度通常是？",
    "q.l38#4.o0" to "1–2 公尺",
    "q.l38#4.o1" to "0.3 公尺",
)
